#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_1 2
#define GPIO_2 3
#define POLL_INTERVAL_SEC 2

static volatile sig_atomic_t keep_running = 1;

static void signal_handler(int signum)
{
    (void)signum;
    keep_running = 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line1 = NULL;
    struct gpiod_line *line2 = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Get the two lines */
    line1 = gpiod_chip_get_line(chip, GPIO_1);
    if (!line1) {
        fprintf(stderr, "Failed to get line %d: %s\n", GPIO_1, strerror(errno));
        goto cleanup;
    }

    line2 = gpiod_chip_get_line(chip, GPIO_2);
    if (!line2) {
        fprintf(stderr, "Failed to get line %d: %s\n", GPIO_2, strerror(errno));
        goto cleanup;
    }

    /* Request both lines as outputs, initially low */
    if (gpiod_line_request_output(line1, "digital-output-1", 0) < 0) {
        fprintf(stderr, "Failed to request line %d as output: %s\n", GPIO_1, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(line2, "digital-output-2", 0) < 0) {
        fprintf(stderr, "Failed to request line %d as output: %s\n", GPIO_2, strerror(errno));
        goto cleanup;
    }

    printf("Digital output control started. Press Ctrl+C to exit.\n");

    while (keep_running) {
        /* Toggle both outputs */
        if (gpiod_line_set_value(line1, 1) < 0) {
            fprintf(stderr, "Failed to set line %d high: %s\n", GPIO_1, strerror(errno));
            goto cleanup;
        }
        if (gpiod_line_set_value(line2, 1) < 0) {
            fprintf(stderr, "Failed to set line %d high: %s\n", GPIO_2, strerror(errno));
            goto cleanup;
        }
        printf("GPIO %d and %d set HIGH\n", GPIO_1, GPIO_2);

        sleep(POLL_INTERVAL_SEC);

        if (gpiod_line_set_value(line1, 0) < 0) {
            fprintf(stderr, "Failed to set line %d low: %s\n", GPIO_1, strerror(errno));
            goto cleanup;
        }
        if (gpiod_line_set_value(line2, 0) < 0) {
            fprintf(stderr, "Failed to set line %d low: %s\n", GPIO_2, strerror(errno));
            goto cleanup;
        }
        printf("GPIO %d and %d set LOW\n", GPIO_1, GPIO_2);

        sleep(POLL_INTERVAL_SEC);
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Ensure lines are released even on error path */
    if (line1)
        gpiod_line_release(line1);
    if (line2)
        gpiod_line_release(line2);
    if (chip)
        gpiod_chip_close(chip);

    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_2 2
#define GPIO_3 3
#define POLL_INTERVAL_US 100000

static volatile sig_atomic_t keep_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line2 = NULL;
    struct gpiod_line *line3 = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    line2 = gpiod_chip_get_line(chip, GPIO_2);
    if (!line2) {
        perror("gpiod_chip_get_line(2)");
        goto cleanup;
    }

    line3 = gpiod_chip_get_line(chip, GPIO_3);
    if (!line3) {
        perror("gpiod_chip_get_line(3)");
        goto cleanup;
    }

    /* Request both lines as outputs, initially low */
    if (gpiod_line_request_output(line2, "digital-out", 0) < 0) {
        perror("gpiod_line_request_output(2)");
        goto cleanup;
    }
    if (gpiod_line_request_output(line3, "digital-out", 0) < 0) {
        perror("gpiod_line_request_output(3)");
        goto cleanup;
    }

    printf("Digital output control started. Press Ctrl+C to exit.\n");

    while (keep_running) {
        if (gpiod_line_set_value(line2, 1) < 0) {
            perror("gpiod_line_set_value(2)");
            break;
        }
        if (gpiod_line_set_value(line3, 0) < 0) {
            perror("gpiod_line_set_value(3)");
            break;
        }
        printf("GPIO %d=1, GPIO %d=0\n", GPIO_2, GPIO_3);
        fflush(stdout);

        usleep(POLL_INTERVAL_US);

        if (gpiod_line_set_value(line2, 0) < 0) {
            perror("gpiod_line_set_value(2)");
            break;
        }
        if (gpiod_line_set_value(line3, 1) < 0) {
            perror("gpiod_line_set_value(3)");
            break;
        }
        printf("GPIO %d=0, GPIO %d=1\n", GPIO_2, GPIO_3);
        fflush(stdout);

        usleep(POLL_INTERVAL_US);
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Ensure lines are left in a safe state before release */
    if (line2) gpiod_line_release(line2);
    if (line3) gpiod_line_release(line3);
    if (chip)  gpiod_chip_close(chip);

    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINE_OFFSET 2
#define POLL_INTERVAL_SEC 5

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int signum)
{
    (void)signum;
    g_running = 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to install SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Get the line for BCM GPIO 2 */
    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (!line) {
        fprintf(stderr, "Failed to get line %d: %s\n", GPIO_LINE_OFFSET, strerror(errno));
        goto cleanup;
    }

    /* Request the line as output, initial value LOW (0) */
    if (gpiod_line_request_output(line, "digital-output", 0) < 0) {
        fprintf(stderr, "Failed to request line %d as output: %s\n",
                GPIO_LINE_OFFSET, strerror(errno));
        goto cleanup;
    }

    printf("Digital output control started on GPIO %d.\n", GPIO_LINE_OFFSET);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        int new_value = rand() % 2; /* 0 or 1 */

        if (gpiod_line_set_value(line, new_value) < 0) {
            fprintf(stderr, "Failed to set line value: %s\n", strerror(errno));
            goto cleanup;
        }

        printf("GPIO %d set to %d\n", GPIO_LINE_OFFSET, new_value);

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < POLL_INTERVAL_SEC && g_running; i++) {
            sleep(1);
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    if (ret == EXIT_SUCCESS) {
        printf("\nExiting cleanly.\n");
    }
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>

#define I2C_BUS "/dev/i2c-1"
#define ADS1115_ADDR 0x48

// ADS1115 Registers
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG     0x01

// Config register bits
#define ADS1115_CFG_OS_BEGIN   0x8000
#define ADS1115_CFG_MUX_AIN0_GND 0x4000
#define ADS1115_CFG_PGA_4_096V  0x0200
#define ADS1115_CFG_MODE_SINGLE 0x0100
#define ADS1115_CFG_DR_128SPS  0x0080

static volatile sig_atomic_t running = 1;

void handle_signal(int sig) {
    (void)sig;
    running = 0;
}

int i2c_write_reg16(int fd, uint8_t reg, uint16_t val) {
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (val >> 8) & 0xFF;
    buf[2] = val & 0xFF;
    if (write(fd, buf, 3) != 3) {
        perror("i2c_write_reg16: write failed");
        return -1;
    }
    return 0;
}

int i2c_read_reg16(int fd, uint8_t reg, uint16_t *out) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        perror("i2c_read_reg16: write reg failed");
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        perror("i2c_read_reg16: read failed");
        return -1;
    }
    *out = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

int ads1115_init(int fd) {
    // Set config: OS=1, MUX=AIN0/GND, PGA=4.096V, MODE=single, DR=128 SPS
    uint16_t cfg = ADS1115_CFG_OS_BEGIN | ADS1115_CFG_MUX_AIN0_GND |
                   ADS1115_CFG_PGA_4_096V | ADS1115_CFG_MODE_SINGLE |
                   ADS1115_CFG_DR_128SPS;
    return i2c_write_reg16(fd, ADS1115_REG_CONFIG, cfg);
}

int ads1115_read_channel(int fd, int16_t *value) {
    uint16_t raw;
    if (i2c_read_reg16(fd, ADS1115_REG_CONVERSION, &raw) != 0) {
        return -1;
    }
    *value = (int16_t)raw;
    return 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("open " I2C_BUS);
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(fd);
        return EXIT_FAILURE;
    }

    if (ads1115_init(fd) != 0) {
        fprintf(stderr, "Failed to initialize ADS1115\n");
        close(fd);
        return EXIT_FAILURE;
    }

    while (running) {
        int16_t value;
        if (ads1115_read_channel(fd, &value) == 0) {
            printf("%d\n", value);
            fflush(stdout);
        } else {
            fprintf(stderr, "Error reading ADS1115 channel\n");
        }
        usleep(500000);
    }

    close(fd);
    return EXIT_SUCCESS;
}

#include <stdio.h>
