#define GPIO_4  4
#define GPIO_17 17

static volatile sig_atomic_t keep_running = 1;

static void sighandler(int signo) {
    (void)signo;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line4 = NULL;
    struct gpiod_line *line17 = NULL;
    int rc = EXIT_FAILURE;

