#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PWM_PIN 18
#define PWM_RANGE 255

static volatile sig_atomic_t running = 1;

static void signal_handler(int signum) {
    (void)signum;
    running = 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed (device may be absent).\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PWM_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(PWM_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "Error: failed to set PWM range on GPIO %d.\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        int duty = (rand() % (PWM_RANGE + 1));
        if (gpioPWM(PWM_PIN, duty) != 0) {
            fprintf(stderr, "Warning: gpioPWM failed on GPIO %d.\n", PWM_PIN);
        }
        printf("GPIO %d PWM duty cycle: %d/%d\n", PWM_PIN, duty, PWM_RANGE);
        fflush(stdout);
        time_sleep(0.5);
    }

    gpioPWM(PWM_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <time.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    27
#define CHIP_NAME   "gpiochip0"
#define TIMEOUT_US  30000

static volatile sig_atomic_t running = 1;

static void sighandler(int sig)
{
    (void)sig;
    running = 0;
}

static int wait_for_level(struct gpiod_line *line, int val, int timeout_us)
{
    struct timespec start, now;
    clock_gettime(CLOCK_MONOTONIC, &start);
    while (1) {
        int v = gpiod_line_get_value(line);
        if (v < 0) return -1;
        if (v == val) return 0;
        clock_gettime(CLOCK_MONOTONIC, &now);
        long elapsed = (now.tv_sec - start.tv_sec) * 1000000L +
                       (now.tv_nsec - start.tv_nsec) / 1000L;
        if (elapsed > timeout_us) return -1;
    }
}

static long measure_pulse(struct gpiod_line *trig, struct gpiod_line *echo)
{
    if (gpiod_line_set_value(trig, 0) < 0) return -1;
    usleep(2);
    if (gpiod_line_set_value(trig, 1) < 0) return -1;
    usleep(10);
    if (gpiod_line_set_value(trig, 0) < 0) return -1;

    if (wait_for_level(echo, 1, TIMEOUT_US) < 0) return -1;
    struct timespec t1;
    clock_gettime(CLOCK_MONOTONIC, &t1);

    if (wait_for_level(echo, 0, TIMEOUT_US) < 0) return -1;
    struct timespec t2;
    clock_gettime(CLOCK_MONOTONIC, &t2);

    long diff_ns = (t2.tv_sec - t1.tv_sec) * 1000000000L +
                   (t2.tv_nsec - t1.tv_nsec);
    return diff_ns / 58L;
}

int main(void)
{
    struct sigaction sa = { .sa_handler = sighandler };
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    struct gpiod_line *trig = gpiod_chip_get_line(chip, TRIGGER_PIN);
    struct gpiod_line *echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!trig || !echo) {
        fprintf(stderr, "Failed to get GPIO lines: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(trig, "hc-sr04-trig", 0) < 0) {
        fprintf(stderr, "Failed to request trigger line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_input(echo, "hc-sr04-echo") < 0) {
        fprintf(stderr, "Failed to request echo line: %s\n", strerror(errno));
        gpiod_line_release(trig);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("HC-SR04 distance measurement started. Press Ctrl+C to stop.\n");

    while (running) {
        long pulse = measure_pulse(trig, echo);
        if (pulse < 0) {
            fprintf(stderr, "Timeout or read error: %s\n", strerror(errno));
        } else if (pulse > 500000000L) {
            fprintf(stderr, "Distance out of range (%ld ns)\n", pulse);
        } else {
            float dist = pulse / 2.0f;
            printf("Distance: %.2f cm\n", dist);
        }
        sleep(60);
    }

    gpiod_line_release(trig);
    gpiod_line_release(echo);
    gpiod_chip_close(chip);
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define ADS1115_ADDR   0x28

/* ADS1115 register addresses */
#define REG_CONVERSION 0x00
#define REG_CONFIG     0x01

/*
 * Config word (16-bit):
 *   Bit 15    OS       = 1  (begin single conversion)
 *   Bits 14:12 MUX     = 100 (AIN0 vs GND)
 *   Bits 11:9  PGA      = 001 (+/-4.096V)
 *   Bit  8     MODE     = 1  (single-shot)
 *   Bits 7:5   DR       = 100 (128 SPS)
 *   Bit  4     COMP_MODE= 0
 *   Bit  3     COMP_POL = 0
 *   Bit  2     COMP_LAT = 0
 *   Bits 1:0   COMP_QUE = 11 (comparator disabled)
 */
#define CONFIG_VALUE   0xC3E0

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int signo) {
    (void)signo;
    g_running = 0;
}

static int i2c_write_reg(int fd, uint8_t reg, uint16_t value) {
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (uint8_t)(value >> 8);
    buf[2] = (uint8_t)(value & 0xFF);

    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "i2c_write_reg(0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg(int fd, uint8_t reg, uint16_t *out) {
    uint8_t buf[2];

    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read_reg write(0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }

    if (read(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "i2c_read_reg read(0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }

    *out = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

static int ads1115_start_conversion(int fd) {
    return i2c_write_reg(fd, REG_CONFIG, CONFIG_VALUE);
}

static int ads1115_read_conversion(int fd, int16_t *raw) {
    uint16_t val;
    if (i2c_read_reg(fd, REG_CONVERSION, &val) != 0)
        return -1;
    *raw = (int16_t)val;
    return 0;
}

static int ads1115_wait_for_conversion(int fd) {
    for (int i = 0; i < 100; i++) {
        uint16_t cfg;
        if (i2c_read_reg(fd, REG_CONFIG, &cfg) != 0)
            return -1;
        if (cfg & 0x8000) /* OS bit set => conversion complete */
            return 0;
        usleep(10000); /* 10 ms */
    }
    fprintf(stderr, "ADS1115 conversion timeout\n");
    return -1;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n",
                ADS1115_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    while (g_running) {
        if (ads1115_start_conversion(fd) != 0) {
            fprintf(stderr, "Failed to start conversion.\n");
            break;
        }

        if (ads1115_wait_for_conversion(fd) != 0) {
            fprintf(stderr, "Conversion not ready.\n");
            break;
        }

        int16_t raw;
        if (ads1115_read_conversion(fd, &raw) != 0) {
            fprintf(stderr, "Failed to read conversion data.\n");
            break;
        }

        printf("Raw ADC value: %d\n", raw);
        fflush(stdout);

        /* Sleep 5 s in 100 ms slices so SIGINT is caught promptly */
        for (int i = 0; i < 50 && g_running; i++)
            usleep(100000);
    }

    close(fd);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINE_OFFSET 18
#define POLL_INTERVAL_SEC 1

static volatile sig_atomic_t keep_running = 1;

static void signal_handler(int signum)
{
    (void)signum;
    keep_running = 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to install SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Get the line for BCM GPIO 18 */
    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (!line) {
        fprintf(stderr, "Failed to get line %d: %s\n", GPIO_LINE_OFFSET, strerror(errno));
        goto cleanup;
    }

    /* Request the line as output, initial value LOW (0) */
    if (gpiod_line_request_output(line, "digital-output", 0) < 0) {
        fprintf(stderr, "Failed to request line %d as output: %s\n",
                GPIO_LINE_OFFSET, strerror(errno));
        goto cleanup;
    }

    printf("Digital output control started on GPIO %d.\n", GPIO_LINE_OFFSET);
    printf("Press Ctrl+C to exit.\n");

    while (keep_running) {
        /* Toggle the output state */
        static int state = 0;
        state = !state;

        if (gpiod_line_set_value(line, state) < 0) {
            fprintf(stderr, "Failed to set line value: %s\n", strerror(errno));
            goto cleanup;
        }

        printf("GPIO %d set to %d\n", GPIO_LINE_OFFSET, state);

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < POLL_INTERVAL_SEC && keep_running; i++) {
            sleep(1);
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Release the line and close the chip */
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    if (ret == EXIT_SUCCESS) {
        printf("\nExiting cleanly.\n");
    }
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINE_OFFSET 18
#define NUM_CYCLES 3
#define CYCLE_DELAY_SEC 2

static volatile sig_atomic_t keep_running = 1;

static void signal_handler(int signum) {
    (void)signum;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("Failed to install SIGINT handler");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("Failed to install SIGTERM handler");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Error opening %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_LINE_OFFSET, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(line, "digital-output-demo", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as output: %s\n", GPIO_LINE_OFFSET, strerror(errno));
        goto cleanup;
    }

    printf("Digital output control started on GPIO %d.\n", GPIO_LINE_OFFSET);
    printf("Press Ctrl+C to exit after %d cycles.\n", NUM_CYCLES);

    for (int i = 0; i < NUM_CYCLES && keep_running; i++) {
        printf("Cycle %d/%d: Setting GPIO high...\n", i + 1, NUM_CYCLES);
        if (gpiod_line_set_value(line, 1) < 0) {
            fprintf(stderr, "Error setting GPIO high: %s\n", strerror(errno));
            goto cleanup;
        }
        sleep(CYCLE_DELAY_SEC);

        if (!keep_running) break;

        printf("Cycle %d/%d: Setting GPIO low...\n", i + 2, NUM_CYCLES);
        if (gpiod_line_set_value(line, 0) < 0) {
            fprintf(stderr, "Error setting GPIO low: %s\n", strerror(errno));
            goto cleanup;
        }
        sleep(CYCLE_DELAY_SEC);
    }

    if (!keep_running) {
        printf("\nInterrupt received. Exiting gracefully.\n");
    } else {
        printf("\nCompleted %d cycles.\n", NUM_CYCLES);
    }
    ret = EXIT_SUCCESS;

cleanup:
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>

#define I2C_BUS "/dev/i2c-1"
#define ADS1115_ADDR 0x48

// ADS1115 Registers
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG     0x01

// Config register bits
#define ADS1115_CFG_OS_BEGIN   0x8000
#define ADS1115_CFG_MUX_AIN0_GND 0x4000
#define ADS1115_CFG_PGA_4_096V  0x0200
#define ADS1115_CFG_MODE_SINGLE 0x0100
#define ADS1115_CFG_DR_128SPS  0x0080

static volatile sig_atomic_t running = 1;

void handle_signal(int sig) {
    (void)sig;
    running = 0;
}

int i2c_write_reg16(int fd, uint8_t reg, uint16_t value) {
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (value >> 8) & 0xFF;
    buf[2] = value & 0xFF;
    if (write(fd, buf, 3) != 3) {
        perror("i2c_write_reg16: write failed");
        return -1;
    }
    return 0;
}

int i2c_read_reg16(int fd, uint8_t reg, uint16_t *value) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        perror("i2c_read_reg16: write reg failed");
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        perror("i2c_read_reg16: read failed");
        return -1;
    }
    *value = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

int ads1115_init(int fd) {
    // Set config: OS=1, MUX=AIN0/GND, PGA=4.096V, MODE=single, DR=128 SPS
    uint16_t config = ADS1115_CFG_OS_BEGIN | ADS1115_CFG_MUX_AIN0_GND |
                      ADS1115_CFG_PGA_4_096V | ADS1115_CFG_MODE_SINGLE |
                      ADS1115_CFG_DR_128SPS;
    if (i2c_write_reg16(fd, ADS1115_REG_CONFIG, config) < 0) {
        return -1;
    }
    return 0;
}

int ads1115_read_channel(int fd, int16_t *out) {
    uint16_t raw;
    if (i2c_read_reg16(fd, ADS1115_REG_CONVERSION, &raw) < 0) {
        return -1;
    }
    *out = (int16_t)raw;
    return 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("open " I2C_BUS);
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(fd);
        return EXIT_FAILURE;
    }

    if (ads1115_init(fd) < 0) {
        fprintf(stderr, "Failed to initialize ADS1115\n");
        close(fd);
        return EXIT_FAILURE;
    }

    while (running) {
        int16_t val;
        if (ads1115_read_channel(fd, &val) < 0) {
            fprintf(stderr, "Failed to read ADS1115 channel\n");
            break;
        }
        printf("%d\n", val);
        fflush(stdout);
        usleep(10000); // 10ms delay for ~100Hz sampling
    }

    close(fd);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_2 2
#define GPIO_3 3
#define POLL_INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;

static void handle_signal(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line2 = NULL;
    struct gpiod_line *line3 = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    line2 = gpiod_chip_get_line(chip, GPIO_2);
    if (!line2) {
        perror("gpiod_chip_get_line(2)");
        goto cleanup;
    }

    line3 = gpiod_chip_get_line(chip, GPIO_3);
    if (!line3) {
        perror("gpiod_chip_get_line(3)");
        goto cleanup;
    }

    /* Request both lines as outputs, initially low */
    if (gpiod_line_request_output(line2, "gpio-demo", 0) < 0) {
        perror("gpiod_line_request_output(2)");
        goto cleanup;
    }
    if (gpiod_line_request_output(line3, "gpio-demo", 0) < 0) {
        perror("gpiod_line_request_output(3)");
        goto cleanup;
    }

    printf("GPIO %d and %d initialized as outputs (low).\n", GPIO_2, GPIO_3);

    while (running) {
        /* Toggle both lines */
        if (gpiod_line_set_value(line2, 1) < 0) {
            perror("gpiod_line_set_value(2)");
            break;
        }
        if (gpiod_line_set_value(line3, 1) < 0) {
            perror("gpiod_line_set_value(3)");
            break;
        }
        printf("GPIO %d and %d set HIGH.\n", GPIO_2, GPIO_3);
        sleep(POLL_INTERVAL_SEC);

        if (!running) break;

        if (gpiod_line_set_value(line2, 0) < 0) {
            perror("gpiod_line_set_value(2)");
            break;
        }
        if (gpiod_line_set_value(line3, 0) < 0) {
            perror("gpiod_line_set_value(3)");
            break;
        }
        printf("GPIO %d and %d set LOW.\n", GPIO_2, GPIO_3);
        sleep(POLL_INTERVAL_SEC);
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Ensure lines are left in a safe state before release */
    if (line2) gpiod_line_release(line2);
    if (line3) gpiod_line_release(line3);
    if (chip)  gpiod_chip_close(chip);

    if (ret == EXIT_SUCCESS)
        printf("Program terminated cleanly.\n");

    return ret;
}

