        if (gpiod_line_set_value(line17, 0) < 0) {
            fprintf(stderr, "Failed to set line %d low: %s\n", GPIO_17_OFFSET, strerror(errno));
            goto cleanup;
        }
        if (gpiod_line_set_value(line18, 0) < 0) {
            fprintf(stderr, "Failed to set line %d low: %s\n", GPIO_18_OFFSET, strerror(errno));
            goto cleanup;
        }
        printf("GPIO %d and %d set LOW\n", GPIO_17_OFFSET, GPIO_18_OFFSET);

        usleep(POLL_INTERVAL_US);
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Ensure lines are released even on error path */
    if (line17) {
        gpiod_line_release(line17);
    }
    if (line18) {
        gpiod_line_release(line18);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    if (ret == EXIT_SUCCESS) {
        printf("\nExiting cleanly.\n");
    }
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define SI7021_ADDR 0x40

/* Command bytes */
#define CMD_MEASURE_TEMP_HOLD   0xE3
#define CMD_MEASURE_HUMID_HOLD  0xE5
#define CMD_READ_TEMP_PREV      0xE0
#define CMD_READ_HUMID_PREV     0xE1
#define CMD_RESET               0xFE

static volatile sig_atomic_t g_running = 1;

static void sighandler(int signo) {
    (void)signo;
    g_running = 0;
}

static int i2c_write_byte(int fd, uint8_t byte) {
    if (write(fd, &byte, 1) != 1) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len) {
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int si7021_reset(int fd) {
    if (i2c_write_byte(fd, CMD_RESET) < 0)
        return -1;
    usleep(15000); /* datasheet: wait >12 ms after reset */
    return 0;
}

/*
 * Read temperature in Celsius.
 * Returns 0 on success, -1 on error.
 * Stores temperature in *out_temp_celsius.
 */
static int si7021_read_temperature(int fd, float *out_temp_celsius) {
    if (i2c_write_byte(fd, CMD_MEASURE_TEMP_HOLD) < 0)
        return -1;

    usleep(10000); /* hold-time ~11 ms */

    uint8_t buf[2];
    if (i2c_read_bytes(fd, buf, sizeof(buf)) < 0)
        return -1;

    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    raw >>= 4; /* remove status bits */

    /* DigiSpark / Si7021: T = (175.72 * raw / 65536) - 46.85 */
    *out_temp_celsius = (175.72f * raw) / 65536.0f - 46.85f;
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    const char *dev = "/dev/i2c-1";
    int fd = open(dev, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", dev, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, SI7021_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n",
                SI7021_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    /* Quick presence probe: try a zero-length write */
    if (i2c_write_byte(fd, 0x00) < 0) {
        fprintf(stderr, "SI7021 not responding at 0x%02X\n", SI7021_ADDR);
        close(fd);
        return EXIT_FAILURE;
    }

    if (si7021_reset(fd) < 0) {
        fprintf(stderr, "SI7021 reset failed\n");
        close(fd);
        return EXIT_FAILURE;
    }

    while (g_running) {
        float temp;
        if (si7021_read_temperature(fd, &temp) == 0) {
            printf("Temperature: %.2f °C\n", temp);
            fflush(stdout);
        } else {
            fprintf(stderr, "Failed to read temperature\n");
        }
        sleep(5);
    }

    close(fd);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define ADS1115_ADDR 0x48

/* ADS1115 registers */
#define REG_CONVERSION 0x00
#define REG_CONFIG     0x01

/* Config register bit fields (16-bit, MSB first) */
#define CFG_OS_SINGLE   0x8000  /* Operational status / single-shot start */
#define CFG_MUX_AIN0_GND 0x4000 /* AIN0 vs GND */
#define CFG_PGA_4_096V  0x0200  /* PGA = +/-4.096 V */
#define CFG_MODE_SINGLE 0x0100  /* Single-shot mode */
#define CFG_DR_128SPS   0x0080  /* Data rate = 128 SPS */

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int i2c_write_reg16(int fd, uint8_t reg, uint16_t val)
{
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (val >> 8) & 0xFF;
    buf[2] = val & 0xFF;
    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "i2c_write_reg16: write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read_reg16: write reg failed: %s\n", strerror(errno));
        return -1;
    }
    if (read(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "i2c_read_reg16: read failed: %s\n", strerror(errno));
        return -1;
    }
    *out = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n",
                ADS1115_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    /* Probe: try a config read to confirm the device is present */
    uint16_t cfg = 0;
    if (i2c_read_reg16(fd, REG_CONFIG, &cfg) < 0) {
        fprintf(stderr, "ADS1115 not responding at 0x%02X\n", ADS1115_ADDR);
        close(fd);
        return EXIT_FAILURE;
    }

    printf("Sampling ADS1115 at 0x%02X every 1 s for 3 cycles...\n", ADS1115_ADDR);

    for (int cycle = 0; cycle < 3 && g_running; ++cycle) {
        uint16_t config = CFG_OS_SINGLE | CFG_MUX_AIN0_GND |
                          CFG_PGA_4_096V | CFG_MODE_SINGLE | CFG_DR_128SPS;

        if (i2c_write_reg16(fd, REG_CONFIG, config) < 0) {
            fprintf(stderr, "Failed to configure ADS1115\n");
            break;
        }

        /* Wait for conversion to complete (~7.5 ms at 128 SPS; use 10 ms margin) */
        usleep(10000);

        uint16_t raw;
        if (i2c_read_reg16(fd, REG_CONVERSION, &raw) < 0) {
            fprintf(stderr, "Failed to read conversion result\n");
            break;
        }

        int16_t signed_raw = (int16_t)raw;
        float voltage = (signed_raw * 4.096f) / 32768.0f;
        printf("Cycle %d: raw=0x%04X (%d), voltage=%.3f V\n",
               cycle + 1, raw, signed_raw, voltage);

        if (g_running)
            sleep(1);
    }

    if (!g_running)
        fprintf(stderr, "\nInterrupted by signal.\n");

    if (close(fd) < 0)
        perror("close");

    return g_running ? EXIT_SUCCESS : EXIT_FAILURE;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define NUM_PINS 6
static const unsigned int pins[NUM_PINS] = {8, 9, 10, 11, 23, 24};

static volatile sig_atomic_t keep_running = 1;

static void sighandler(int signo)
{
    (void)signo;
    keep_running = 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_PINS];
    int vals[NUM_PINS];
    int rc = EXIT_FAILURE;

    memset(lines, 0, sizeof(lines));
    memset(vals, 0, sizeof(vals));

    for (int i = 0; i < NUM_PINS; i++)
        lines[i] = NULL;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name(\"gpiochip0\")");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_PINS; i++) {
        lines[i] = gpiod_chip_get_line(chip, pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "gpiod_chip_get_line(%u): %s\n",
                    pins[i], strerror(errno));
            goto cleanup;
        }
        if (gpiod_line_request_output(lines[i], "digital-out", 0) < 0) {
            fprintf(stderr, "gpiod_line_request_output(%u): %s\n",
                    pins[i], strerror(errno));
            goto cleanup;
        }
    }

    printf("Starting 256-cycle cycle on GPIO %u, %u, %u, %u, %u, %u...\n",
           pins[0], pins[1], pins[2], pins[3], pins[4], pins[5]);
    fflush(stdout);

    for (int cycle = 0; cycle < 256 && keep_running; cycle++) {
        for (int p = 0; p < NUM_PINS; p++) {
            vals[p] = cycle & 1;
            if (gpiod_line_set_value(lines[p], vals[p]) < 0) {
                fprintf(stderr, "gpiod_line_set_value(%u, %d): %s\n",
                        pins[p], vals[p], strerror(errno));
                goto cleanup;
            }
        }
        usleep(100000);
    }

    if (!keep_running)
        printf("\nInterrupted by signal.\n");

    rc = EXIT_SUCCESS;

cleanup:
    for (int i = 0; i < NUM_PINS; i++) {
        if (lines[i])
            gpiod_line_release(lines[i]);
    }
    if (chip)
        gpiod_chip_close(chip);

    return rc;
}

