            if (ret < 0) {
                fprintf(stderr, "Failed to set value on line %d\n", pins[i]);
                goto cleanup;
            }
            printf("GPIO %d: %s\n", pins[i], values[i] ? "HIGH" : "LOW");
        }
        fflush(stdout);
        usleep(100000); // 0.1 seconds
    }

cleanup:
    // Release lines and close chip
    for (int i = 0; i < 3; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return EXIT_SUCCESS;
}

