    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to install signal handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP, strerror(errno));
        return EXIT_FAILURE;
    }

    line2 = gpiod_chip_get_line(chip, GPIO_2);
    if (!line2) {
        fprintf(stderr, "Failed to get line %d: %s\n", GPIO_2, strerror(errno));
        goto cleanup;
    }

    line3 = gpiod_chip_get_line(chip, GPIO_3);
    if (!line3) {
        fprintf(stderr, "Failed to get line %d: %s\n", GPIO_3, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(line2, "digital-output-2", 0) < 0) {
        fprintf(stderr, "Failed to request line %d as output: %s\n", GPIO_2, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(line3, "digital-output-3", 0) < 0) {
        fprintf(stderr, "Failed to request line %d as output: %s\n", GPIO_3, strerror(errno));
        goto cleanup;
    }

    printf("Starting 3-cycle cycle on GPIO %d and %d...\n", GPIO_2, GPIO_3);

    for (int i = 0; i < NUM_CYCLES && running; i++) {
        if (gpiod_line_set_value(line2, 1) < 0) {
            fprintf(stderr, "Failed to set GPIO %d high: %s\n", GPIO_2, strerror(errno));
            goto cleanup;
        }
        if (gpiod_line_set_value(line3, 1) < 0) {
            fprintf(stderr, "Failed to set GPIO %d high: %s\n", GPIO_3, strerror(errno));
            goto cleanup;
        }
        printf("Cycle %d: GPIO %d HIGH, GPIO %d HIGH\n", i + 1, GPIO_2, GPIO_3);
        usleep(500000);

        if (gpiod_line_set_value(line2, 0) < 0) {
            fprintf(stderr, "Failed to set GPIO %d low: %s\n", GPIO_2, strerror(errno));
            goto cleanup;
        }
        if (gpiod_line_set_value(line3, 0) < 0) {
            fprintf(stderr, "Failed to set GPIO %d low: %s\n", GPIO_3, strerror(errno));
            goto cleanup;
        }
        printf("Cycle %d: GPIO %d LOW, GPIO %d LOW\n", i + 1, GPIO_2, GPIO_3);
        usleep(500000);
    }

    if (!running) {
        printf("\nInterrupted by signal.\n");
    } else {
        printf("\nCompleted %d cycles.\n", NUM_CYCLES);
    }
    ret = EXIT_SUCCESS;

cleanup:
    if (line2) gpiod_line_release(line2);
    if (line3) gpiod_line_release(line3);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

