#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define DHT11_PIN 4
#define MAX_TIMINGS 85

static volatile sig_atomic_t running = 1;

static void sighandler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to install signal handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, DHT11_PIN);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", DHT11_PIN, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input(line, "dht11-reader") < 0) {
        fprintf(stderr, "Failed to request input on GPIO %d: %s\n", DHT11_PIN, strerror(errno));
        goto cleanup;
    }

    int data[5] = {0, 0, 0, 0, 0};
    int laststate = 1;
    int counter = 0;
    int j = 0;

    while (running && j < MAX_TIMINGS) {
        int bit = gpiod_line_get_value(line);
        if (bit < 0) {
            fprintf(stderr, "GPIO read error: %s\n", strerror(errno));
            goto cleanup;
        }
        if (bit != laststate) {
            counter++;
            laststate = bit;
            if (counter > 255) {
                break;
            }
            if (counter >= 2) {
                data[j / 8] <<= 1;
                if (counter > 1) {
                    data[j / 8] |= 1;
                }
            }
            j++;
        }
    }

    if (!running) {
        fprintf(stderr, "Interrupted before completion.\n");
        goto cleanup;
    }

    if (j < 40) {
        fprintf(stderr, "DHT11 communication failed: incomplete data (%d/%d)\n", j, 40);
        goto cleanup;
    }

    if (data[0] + data[1] + data[2] + data[3] != data[4]) {
        fprintf(stderr, "DHT11 checksum error: %d + %d + %d + %d != %d\n",
                data[0], data[1], data[2], data[3], data[4]);
        goto cleanup;
    }

    float humidity = (float)((data[0] << 8) | data[1]) / 10.0f;
    float temperature = (float)(((data[2] & 0x7F) << 8) | data[3]) / 10.0f;
    if (data[2] & 0x80) {
        temperature *= -1.0f;
    }

    printf("Humidity: %.1f%%, Temperature: %.1f°C\n", humidity, temperature);
    ret = EXIT_SUCCESS;

cleanup:
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

