#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_2 2
#define GPIO_3 3
#define NUM_CYCLES 3
#define CYCLE_DELAY_SEC 5

static volatile sig_atomic_t running = 1;

static void signal_handler(int signum) {
    (void)signum;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line2 = NULL;
    struct gpiod_line *line3 = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to install signal handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip %s: %s\n", GPIO_CHIP, strerror(errno));
        return EXIT_FAILURE;
    }

    line2 = gpiod_chip_get_line(chip, GPIO_2);
    if (!line2) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", GPIO_2, strerror(errno));
        goto cleanup;
    }

    line3 = gpiod_chip_get_line(chip, GPIO_3);
    if (!line3) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", GPIO_3, strerror(errno));
        goto cleanup;
    }

    /* Request both lines as outputs, initially low */
    if (gpiod_line_request_output(line2, "digital_output", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO %d as output: %s\n", GPIO_2, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(line3, "digital_output", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO %d as output: %s\n", GPIO_3, strerror(errno));
        goto cleanup;
    }

    printf("Starting 3-cycle cycle control on GPIO %d and %d.\n", GPIO_2, GPIO_3);

    for (int i = 0; i < NUM_CYCLES && running; i++) {
        printf("Cycle %d/%d\n", i + 1, NUM_CYCLES);

        if (gpiod_line_set_value(line2, 1) < 0) {
            fprintf(stderr, "Failed to set GPIO %d high: %s\n", GPIO_2, strerror(errno));
            goto cleanup;
        }
        if (gpiod_line_set_value(line3, 0) < 0) {
            fprintf(stderr, "Failed to set GPIO %d low: %s\n", GPIO_3, strerror(errno));
            goto cleanup;
        }
        printf("  Cycle %d/%d: GPIO %d=1, GPIO %d=0\n", i + 1, NUM_CYCLES, GPIO_2, GPIO_3);

        sleep(CYCLE_DELAY_SEC);

        if (gpiod_line_set_value(line2, 0) < 0) {
            fprintf(stderr, "Failed to set GPIO %d low: %s\n", GPIO_2, strerror(errno));
            goto cleanup;
        }
        if (gpiod_line_set_value(line3, 1) < 0) {
            fprintf(stderr, "Failed to set GPIO %d high: %s\n", GPIO_3, strerror(errno));
            goto cleanup;
        }
        printf("  Cycle %d/%d: GPIO %d=0, GPIO %d=1\n", i + 1, NUM_CYCLES, GPIO_2, GPIO_3);

        sleep(CYCLE_DELAY_SEC);
    }

    if (running) {
        ret = EXIT_SUCCESS;
    } else {
        printf("\nInterrupted by signal, exiting gracefully.\n");
    }

cleanup:
    /* Ensure lines are left in a safe state before release */
    if (line2) {
        gpiod_line_set_value(line2, 0);
        gpiod_line_release(line2);
    }
    if (line3) {
        gpiod_line_set_value(line3, 0);
        gpiod_line_release(line3);
    }
