#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PWM_PIN_1 2
#define PWM_PIN_2 3
#define PWM_PIN_3 18

static volatile sig_atomic_t running = 1;

static void signal_handler(int signum) {
    (void)signum;
    running = 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed (device may be absent).\n");
        return EXIT_FAILURE;
    }

    int pins[] = {PWM_PIN_1, PWM_PIN_2, PWM_PIN_3};
    const int num_pins = (int)(sizeof(pins) / sizeof(pins[0]));

    for (int i = 0; i < num_pins; i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: gpioSetMode failed for pin %d.\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetPWMfrequency(pins[i], 1000) != 0) {
            fprintf(stderr, "Warning: gpioSetPWMfrequency failed for pin %d.\n", pins[i]);
        }
        if (gpioSetPWMrange(pins[i], 1024) != 0) {
            fprintf(stderr, "Warning: gpioSetPWMrange failed for pin %d.\n", pins[i]);
        }
    }

    while (running) {
        for (int i = 0; i < num_pins; i++) {
            int duty = (i + 1) * 100;
            if (gpioPWM(pins[i], duty) != 0) {
                fprintf(stderr, "Error: gpioPWM failed for pin %d.\n", pins[i]);
                goto cleanup;
            }
            printf("Pin %d: PWM duty cycle = %d\n", pins[i], duty);
        }
        fflush(stdout);
        time_sleep(0.15);
    }

cleanup:
    for (int i = 0; i < num_pins; i++) {
        gpioPWM(pins[i], 0);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

