#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>

#define OPT3001_ADDR 0x44

static volatile sig_atomic_t running = 1;

void int_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = int_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("open /dev/i2c-1");
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, OPT3001_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(fd);
        return EXIT_FAILURE;
    }

    uint8_t config[2] = {0x00, 0x00};
    if (write(fd, config, 2) != 2) {
        perror("write config");
        close(fd);
        return EXIT_FAILURE;
    }

    uint8_t reg = 0x00;
    if (write(fd, &reg, 1) != 1) {
        perror("write reg pointer");
        close(fd);
        return EXIT_FAILURE;
    }

    uint8_t data[2];
    if (read(fd, data, 2) != 2) {
        perror("read measurement");
        close(fd);
        return EXIT_FAILURE;
    }

    uint16_t raw = ((uint16_t)data[0] << 8) | data[1];
    int exponent = (raw >> 12) & 0x0F;
    int mantissa = raw & 0x0FFF;
    float value = mantissa * (1.0f / (float)(1 << exponent));

    printf("OPT3001: %.2f\n", value);

    close(fd);
    return EXIT_SUCCESS;
}

