#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_17_OFFSET 17
#define GPIO_18_OFFSET 18
#define POLL_INTERVAL_US 500000

static volatile sig_atomic_t keep_running = 1;

static void signal_handler(int signum)
{
    (void)signum;
    keep_running = 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line17 = NULL;
    struct gpiod_line *line18 = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Get the lines */
    line17 = gpiod_chip_get_line(chip, GPIO_17_OFFSET);
    if (!line17) {
        fprintf(stderr, "Failed to get line %d: %s\n", GPIO_17_OFFSET, strerror(errno));
        goto cleanup;
    }

    line18 = gpiod_chip_get_line(chip, GPIO_18_OFFSET);
    if (!line18) {
        fprintf(stderr, "Failed to get line %d: %s\n", GPIO_18_OFFSET, strerror(errno));
        goto cleanup;
    }

    /* Request both lines as outputs, initially low */
    if (gpiod_line_request_output(line17, "digital-out-17", 0) < 0) {
        fprintf(stderr, "Failed to request line %d as output: %s\n", GPIO_17_OFFSET, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(line18, "digital-out-18", 0) < 0) {
        fprintf(stderr, "Failed to request line %d as output: %s\n", GPIO_18_OFFSET, strerror(errno));
        goto cleanup;
    }

    printf("Digital output control started. Press Ctrl+C to exit.\n");

    while (keep_running) {
        /* Toggle both lines */
        if (gpiod_line_set_value(line17, 1) < 0) {
            fprintf(stderr, "Failed to set line %d high: %s\n", GPIO_17_OFFSET, strerror(errno));
            break;
        }
        if (gpiod_line_set_value(line18, 1) < 0) {
            fprintf(stderr, "Failed to set line %d high: %s\n", GPIO_18_OFFSET, strerror(errno));
            break;
        }
        printf("GPIO 17 HIGH, GPIO 18 HIGH\n");
        usleep(POLL_INTERVAL_US);

        if (gpiod_line_set_value(line17, 0) < 0) {
            fprintf(stderr, "Failed to set line %d low: %s\n", GPIO_17_OFFSET, strerror(errno));
            break;
        }
        if (gpiod_line_set_value(line18, 0) < 0) {
            fprintf(stderr, "Failed to set line %d low: %s\n", GPIO_18_OFFSET, strerror(errno));
            break;
        }
        printf("GPIO 17 LOW, GPIO 18 LOW\n");
        usleep(POLL_INTERVAL_US);
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Ensure lines are left in a safe state before releasing */
    if (line17) {
        gpiod_line_set_value(line17, 0);
        gpiod_line_release(line17);
    }
    if (line18) {
        gpiod_line_set_value(line18, 0);
        gpiod_line_release(line18);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    if (ret == EXIT_SUCCESS) {
        printf("\nExiting cleanly.\n");
    }
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <signal.h>

#define PORT "/dev/ttyS0"
#define BAUD_RATE B115200

static volatile sig_atomic_t keep_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    int fd = open(PORT, O_RDWR | O_NOCTTY | O_NONBLOCK);
    if (fd == -1) {
        fprintf(stderr, "Error opening %s: %s\n", PORT, strerror(errno));
        return EXIT_FAILURE;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        fprintf(stderr, "tcgetattr failed: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    cfsetospeed(&tty, BAUD_RATE);
    cfsetispeed(&tty, BAUD_RATE);

    tty.c_cflag |= (CLOCAL | CREAD);
    tty.c_cflag &= ~PARENB;
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CSIZE;
    tty.c_cflag |= CS8;

    tty.c_lflag &= ~(ICANON | ECHO | ECHOE | ISIG);
    tty.c_iflag &= ~(IXON | IXOFF | IXANY);
    tty.c_oflag &= ~OPOST;

    tty.c_cc[VMIN] = 0;
    tty.c_cc[VTIME] = 10;

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        fprintf(stderr, "tcsetattr failed: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    ssize_t n;
    char buf[256];

    while (keep_running) {
        n = read(fd, buf, sizeof(buf) - 1);
        if (n > 0) {
            buf[n] = '\0';
            printf("%s", buf);
            fflush(stdout);
        } else if (n == -1 && errno != EAGAIN && errno != EWOULDBLOCK) {
            fprintf(stderr, "read error: %s\n", strerror(errno));
            break;
        }
        usleep(10000);
    }

    close(fd);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
