#include <string.h>
#include <gpiod.h>

#define GPIO_4   4
#define GPIO_17  17
#define CHIP_NAME "gpiochip0"
#define POLL_MS  10

static volatile sig_atomic_t running = 1;

static void sighandler(int signo)
{
    (void)signo;
    running = 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line4 = NULL;
    struct gpiod_line *line17 = NULL;
    int rc = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    line4   = gpiod_chip_get_line(chip, GPIO_4);
    line17 = gpiod_chip_get_line(chip, GPIO_17);
    if (!line4 || !line17) {
        fprintf(stderr, "Failed to get GPIO lines: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(line4, "digital-out-4", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO %d as output: %s\n",
                GPIO_4, strerror(errno));
        goto cleanup;
