    if (gpiod_line_request_output(line17, "digital-out-17", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO %d as output: %s\n",
                GPIO_17, strerror(errno));
        goto cleanup;
    }

    while (running) {
        if (gpiod_line_set_value(line4, 1) < 0) {
            fprintf(stderr, "Failed to set GPIO %d high: %s\n",
                    GPIO_4, strerror(errno));
            goto cleanup;
        }
        printf("GPIO %d = HIGH\n", GPIO_4);

        usleep(POLL_MS * 1000);

        if (gpiod_line_set_value(line4, 0) < 0) {
            fprintf(stderr, "Failed to set GPIO %d low: %s\n",
                    GPIO_4, strerror(errno));
            goto cleanup;
        }
        printf("GPIO %d = LOW\n", GPIO_4);

        usleep(POLL_MS * 1000);

        if (gpiod_line_set_value(line17, 1) < 0) {
            fprintf(stderr, "Failed to set GPIO %d high: %s\n",
                    GPIO_17, strerror(errno));
            goto cleanup;
        }
        printf("GPIO %d = HIGH\n", GPIO_17);

        usleep(POLL_MS * 1000);

        if (gpiod_line_set_value(line17, 0) < 0) {
            fprintf(stderr, "Failed to set GPIO %d low: %s\n",
                    GPIO_17, strerror(errno));
            goto cleanup;
        }
        printf("GPIO %d = LOW\n", GPIO_17);

        usleep(POLL_MS * 1000);
    }

    rc = EXIT_SUCCESS;

cleanup:
    if (line4)
        gpiod_line_release(line4);
    if (line17)
        gpiod_line_release(line17);
    if (chip)
        gpiod_chip_close(chip);

