#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINE_OFFSET 2
#define NUM_CYCLES 3
#define CYCLE_INTERVAL_SEC 60

static volatile sig_atomic_t running = 1;

static void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        running = 0;
    }
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to install SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Get the GPIO line */
    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (!line) {
        fprintf(stderr, "Failed to get line %d: %s\n", GPIO_LINE_OFFSET, strerror(errno));
        goto cleanup;
    }

    /* Request the line as output, initially low */
    if (gpiod_line_request_output(line, "digital-output", 0) < 0) {
        fprintf(stderr, "Failed to request line %d as output: %s\n", GPIO_LINE_OFFSET, strerror(errno));
        goto cleanup;
    }

    printf("Starting digital output control on GPIO %d for %d cycles, %d seconds each.\n",
           GPIO_LINE_OFFSET, NUM_CYCLES, CYCLE_INTERVAL_SEC);

    for (int i = 0; i < NUM_CYCLES && running; i++) {
        /* Apply high state */
        if (gpiod_line_set_value(line, 1) < 0) {
            fprintf(stderr, "Failed to set line high: %s\n", strerror(errno));
            goto cleanup;
        }
        printf("Cycle %d/%d: GPIO %d set HIGH\n", i + 1, NUM_CYCLES, GPIO_LINE_OFFSET);

        sleep(CYCLE_INTERVAL_SEC);

        if (!running) break;

        /* Apply low state */
        if (gpiod_line_set_value(line, 0) < 0) {
            fprintf(stderr, "Failed to set line low: %s\n", strerror(errno));
            goto cleanup;
        }
        printf("Cycle %d/%d: GPIO %d set LOW\n", i + 1, NUM_CYCLES, GPIO_LINE_OFFSET);

        sleep(CYCLE_INTERVAL_SEC);
    }

    if (running) {
        ret = EXIT_SUCCESS;
    } else {
        printf("\nInterrupted by signal, exiting gracefully.\n");
    }

cleanup:
    /* Release the line and close the chip */
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define GPIO_5   5
#define GPIO_17  17
#define GPIO_24  24
#define CHIP_NAME "gpiochip0"
#define POLL_INTERVAL_US 200000

static volatile sig_atomic_t keep_running = 1;

static void handle_signal(int sig)
{
    (void)sig;
    keep_running = 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[3] = {NULL, NULL, NULL};
    int pins[3] = {GPIO_5, GPIO_17, GPIO_24};
    const char *labels[3] = {"GPIO5", "GPIO17", "GPIO24"};
    int values[3] = {0, 0, 0};
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    for (int i = 0; i < 3; i++) {
        lines[i] = gpiod_chip_get_line(chip, pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get line %d: %s\n", pins[i], strerror(errno));
            goto cleanup;
        }
        if (gpiod_line_request_output(lines[i], "digital-output-demo", 0) < 0) {
            fprintf(stderr, "Failed to request output on line %d: %s\n",
                    pins[i], strerror(errno));
            goto cleanup;
        }
    }

    while (keep_running) {
        for (int i = 0; i < 3; i++) {
            if (gpiod_line_set_value(lines[i], values[i]) < 0) {
                fprintf(stderr, "Failed to set value on %s: %s\n",
                        labels[i], strerror(errno));
                goto cleanup;
            }
            printf("%s=%d ", labels[i], values[i]);
        }
        printf("\n");
        fflush(stdout);

        for (int i = 0; i < 3; i++)
            values[i] = !values[i];

        usleep(POLL_INTERVAL_US);
    }

    ret = EXIT_SUCCESS;

cleanup:
    for (int i = 0; i < 3; i++) {
        if (lines[i])
            gpiod_line_release(lines[i]);
    }
    if (chip)
        gpiod_chip_close(chip);

    return ret;
}

