#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_LINE 2
#define NUM_CYCLES 3
#define CYCLE_DELAY_MS 100

static volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret;

    // Set up signal handler for clean exit
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("Failed to set up signal handler");
        return EXIT_FAILURE;
    }

    // Open GPIO chip
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request line as output, initially low
    ret = gpiod_line_request_output(line, "digital_output", 0);
    if (ret < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("Starting %d cycles, applying HIGH every other cycle...\n", NUM_CYCLES);

    for (int i = 0; i < NUM_CYCLES && keep_running; i++) {
        if (i % 2 == 0) {
            ret = gpiod_line_set_value(line, 1);
        } else {
            ret = gpiod_line_set_value(line, 0);
        }
        if (ret < 0) {
            perror("Failed to set GPIO value");
            break;
        }
        printf("Cycle %d: GPIO %d set to %s\n", i + 1, GPIO_LINE,
               (i % 2 == 0) ? "HIGH" : "LOW");

        // Sleep in small increments so we can respond to signals promptly
        for (int ms = 0; ms < CYCLE_DELAY_MS && keep_running; ms += 50) {
            usleep(50000);
        }
    }

    // Cleanup
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

