#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>

#define W1_BASE "/sys/bus/w1/devices"
#define MAX_DEVICES 3

static volatile sig_atomic_t running = 1;

static void sighandler(int sig) {
    (void)sig;
    running = 0;
}

static int read_temp(const char *path, float *temp) {
    FILE *fp = fopen(path, "r");
    if (!fp) return -1;

    char line[256];
    if (!fgets(line, sizeof(line), fp)) {
        fclose(fp);
        return -1;
    }
    fclose(fp);

    char *p = strstr(line, "t=");
    if (!p) return -1;

    long val = strtol(p + 2, NULL, 10);
    if (val == -27315 || val > 150000 || val < -150000) return -1;

    *temp = (float)val / 1000.0f;
    return 0;
}

int main(void) {
    struct sigaction sa = {0};
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    char base[MAX_DEVICES][32];
    int found = 0;

    for (int i = 0; i < MAX_DEVICES; i++) {
        snprintf(base[i], sizeof(base[i]), "%s/28-%s", W1_BASE, "000000000000");
        if (access(base[i], F_OK) == 0) {
            found++;
        } else {
            snprintf(base[i], sizeof(base[i]), "%s/28-%s", W1_BASE, "000000000001");
            if (access(base[i], F_OK) == 0) {
                found++;
            }
        }
    }

    if (found == 0) {
        fprintf(stderr, "No DS18B20 devices found under %s\n", W1_BASE);
        return EXIT_FAILURE;
    }

    while (running) {
        for (int i = 0; i < found && running; i++) {
            float t;
            if (read_temp(base[i], &t) == 0) {
                printf("Temperature: %.2f C\n", t);
                fflush(stdout);
            } else {
                fprintf(stderr, "Warning: invalid reading from %s\n", base[i]);
            }
        }
        if (running) sleep(5);
    }

    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define HTU21D_ADDR    0x40

/* HTU21D command: start temperature conversion */
#define CMD_TEMP       0xE3
/* HTU21D command: start humidity conversion */
#define CMD_HUMID      0xE5

static volatile sig_atomic_t g_running = 1;

static void sighandler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int i2c_write_cmd(int fd, uint8_t cmd)
{
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "i2c write(0x%02X) failed: %s\n", cmd, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_block(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "i2c read failed: got %zd of %zu (%s)\n",
                n, len, strerror(errno));
        return -1;
    }
    return 0;
}

/*
 * Read one conversion result.
 * Returns 0 on success and stores the raw 16-bit value in *raw.
 * Returns -1 on any I/O or protocol error.
 */
static int read_conversion(int fd, uint8_t cmd, uint16_t *raw)
{
    if (i2c_write_cmd(fd, cmd) < 0)
        return -1;

    /* Datasheet: typ. 12 ms conversion time; wait up to 25 ms */
    usleep(25000);

    uint8_t buf[3];
    if (i2c_read_block(fd, buf, sizeof(buf)) < 0)
        return -1;

    /* Byte 0 = MSB, byte 1 = LSB, byte 2 = clock-out bits — must be 0x00 */
    if (buf[2] != 0x00) {
        fprintf(stderr, "HTU21D clock-out mismatch: 0x%02X\n", buf[2]);
        return -1;
    }

    *raw = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

/*
 * Convert raw temperature / humidity to Celsius / %RH.
 * Returns 0 on success and stores the result in *out.
 * Returns -1 on invalid data (per datasheet).
 */
static int convert_raw(uint16_t raw, float *out)
{
    if (raw == 0x0000 || raw == 0xFFFE) {
        fprintf(stderr, "HTU21D raw 0x%04X: sensor not ready or absent\n", raw);
        return -1;
    }

    uint32_t t = (uint32_t)(raw >> 8);
    uint32_t h = (uint32_t)(raw & 0x00FF);

    /* Temperature: 14-bit result, resolution 1/128 deg C */
    float temp = -46.85 + 175.72 * (float)t / 65536.0f;

    /* Humidity: 12-bit result, resolution 1/16 %RH */
    float hum = -6.0 + 125.0 * (float)h / 65536.0f;

    if (hum < 0.0f)   hum = 0.0f;
    if (hum > 100.0f) hum = 100.0f;

    *out = temp;
    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, HTU21D_ADDR) < 0) {
        fprintf(stderr, "ioctl I2C_SLAVE 0x%02X failed: %s\n",
                HTU21D_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    printf("HTU21D reader started on %s @ 0x%02X. Press Ctrl-C to stop.\n",
           I2C_BUS, HTU21D_ADDR);

    while (g_running) {
        uint16_t raw_t = 0, raw_h = 0;

        if (read_conversion(fd, CMD_TEMP, &raw_t) < 0) {
            fprintf(stderr, "Temperature read failed; retrying next cycle.\n");
        } else if (convert_raw(raw_t, NULL) < 0) {
            fprintf(stderr, "Temperature out of range; skipping.\n");
        } else {
            float temp;
            if (convert_raw(raw_t, &temp) == 0) {
                printf("Temperature: %.2f C\n", temp);
            }
        }

        if (!g_running)
            break;

        if (read_conversion(fd, CMD_HUMID, &raw_h) < 0) {
            fprintf(stderr, "Humidity read failed; retrying next cycle.\n");
        } else if (convert_raw(raw_h, NULL) < 0) {
            fprintf(stderr, "Humidity out of range; skipping.\n");
        } else {
            float humid;
            if (convert_raw(raw_h, &humid) == 0) {
                printf("Humidity: %.2f %%\n", humid);
            }
        }

        if (g_running)
            sleep(60);
    }

    close(fd);
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

