    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Get the two lines */
    line1 = gpiod_chip_get_line(chip, GPIO_1);
    if (!line1) {
        fprintf(stderr, "Failed to get line %d: %s\n", GPIO_1, strerror(errno));
        goto cleanup;
    }

    line2 = gpiod_chip_get_line(chip, GPIO_2);
    if (!line2) {
        fprintf(stderr, "Failed to get line %d: %s\n", GPIO_2, strerror(errno));
        goto cleanup;
    }

    /* Request both lines as outputs, initially low */
    if (gpiod_line_request_output(line1, "digital-out", 0) < 0) {
        fprintf(stderr, "Failed to request line %d as output: %s\n", GPIO_1, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(line2, "digital-out", 0) < 0) {
        fprintf(stderr, "Failed to request line %d as output: %s\n", GPIO_2, strerror(errno));
        goto cleanup;
    }

    printf("Digital output control started. Press Ctrl+C to exit.\n");

    while (keep_running) {
        /* Toggle both lines */
        if (gpiod_line_set_value(line1, 1) < 0) {
            fprintf(stderr, "Failed to set line %d high: %s\n", GPIO_1, strerror(errno));
            break;
        }
        if (gpiod_line_set_value(line2, 1) < 0) {
            fprintf(stderr, "Failed to set line %d high: %s\n", GPIO_2, strerror(errno));
            break;
        }
        printf("GPIO %d and %d set HIGH\n", GPIO_1, GPIO_2);

        sleep(POLL_INTERVAL_SEC);

        if (!keep_running)
            break;

        if (gpiod_line_set_value(line1, 0) < 0) {
            fprintf(stderr, "Failed to set line %d low: %s\n", GPIO_1, strerror(errno));
            break;
        }
        if (gpiod_line_set_value(line2, 0) < 0) {
            fprintf(stderr, "Failed to set line %d low: %s\n", GPIO_2, strerror(errno));
            break;
        }
        printf("GPIO %d and %d set LOW\n", GPIO_1, GPIO_2);

        sleep(POLL_INTERVAL_SEC);
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Ensure lines are left in a safe state before release */
    if (line1)
        gpiod_line_set_value(line1, 0);
    if (line2)
        gpiod_line_set_value(line2, 0);

    if (line1)
        gpiod_line_release(line1);
    if (line2)
        gpiod_line_release(line2);
    if (chip)
        gpiod_chip_close(chip);

    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>

#define ADXL345_ADDRESS 0x53
#define ADXL345_POWER_CTL 0x2D
#define ADXL345_DATA_FORMAT 0x31
#define ADXL345_DATAX0 0x32

static volatile sig_atomic_t running = 1;

void handle_signal(int sig) {
    (void)sig;
    running = 0;
}

int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

int i2c_read_bytes(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) {
        perror("I2C write register address failed");
        return -1;
    }
    if (read(fd, buf, len) != len) {
        perror("I2C read failed");
        return -1;
    }
    return 0;
}

int adxl345_init(int fd) {
    if (i2c_write_byte(fd, ADXL345_POWER_CTL, 0x08) < 0) return -1;
    if (i2c_write_byte(fd, ADXL345_DATA_FORMAT, 0x00) < 0) return -1;
    return 0;
}

int read_acceleration(int fd, float *x, float *y, float *z) {
    uint8_t buf[6];
    if (i2c_read_bytes(fd, ADXL345_DATAX0, buf, 6) < 0) return -1;

    int16_t raw_x = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t raw_y = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t raw_z = (int16_t)((buf[5] << 8) | buf[4]);

    *x = (float)raw_x / 256.0f;
    *y = (float)raw_y / 256.0f;
    *z = (float)raw_z / 256.0f;

    return 0;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Failed to open /dev/i2c-1");
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, ADXL345_ADDRESS) < 0) {
        perror("Failed to set I2C slave address");
        close(fd);
        return EXIT_FAILURE;
    }

    if (adxl345_init(fd) < 0) {
        fprintf(stderr, "ADXL345 initialization failed\n");
        close(fd);
        return EXIT_FAILURE;
    }

    while (running) {
        float x, y, z;
        if (read_acceleration(fd, &x, &y, &z) == 0) {
            printf("X: %.2f g, Y: %.2f g, Z: %.2f g\n", x, y, z);
        } else {
            fprintf(stderr, "Failed to read acceleration data\n");
        }
        usleep(100000);
    }

    i2c_write_byte(fd, ADXL345_POWER_CTL, 0x00);
    close(fd);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_LINE 27
#define NUM_CYCLES 50
#define CYCLE_DELAY_MS 100

static volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret;

    // Set up signal handler for clean exit
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("Failed to set up signal handler");
        return EXIT_FAILURE;
    }

    // Open GPIO chip
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return EXIT_FAILURE;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request line as output, initially low
    ret = gpiod_line_request_output(line, "digital_output", 0);
    if (ret < 0) {
        perror("Failed to request GPIO line as output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("Starting %d cycles on GPIO %d...\n", NUM_CYCLES, GPIO_LINE);

    for (int i = 0; i < NUM_CYCLES && keep_running; i++) {
        // Toggle state
        int val = (i % 2 == 0) ? 1 : 0;
        ret = gpiod_line_set_value(line, val);
        if (ret < 0) {
            perror("Failed to set GPIO value");
            break;
        }
        printf("Cycle %d: GPIO %d = %d\n", i + 1, GPIO_LINE, val);

        // Wait 0.1 seconds
        usleep(CYCLE_DELAY_MS * 1000);
    }

    // Cleanup
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    printf("Exiting.\n");
    return EXIT_SUCCESS;
}

