#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define NUM_PINS 4
static const unsigned int pins[NUM_PINS] = {17, 22, 23, 24};

static volatile sig_atomic_t running = 1;

static void sighandler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_PINS];
    int vals[NUM_PINS];
    int rc = EXIT_FAILURE;

    memset(lines, 0, sizeof(lines));

    for (int i = 0; i < NUM_PINS; i++) {
        lines[i] = NULL;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to install signal handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_PINS; i++) {
        lines[i] = gpiod_chip_get_line(chip, pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get line %u: %s\n", pins[i], strerror(errno));
            goto cleanup;
        }
        if (gpiod_line_request_input(lines[i], "dht22") < 0) {
            fprintf(stderr, "Failed to request line %u as input: %s\n", pins[i], strerror(errno));
            goto cleanup;
        }
    }

    while (running) {
        printf("DHT22 readings:\n");
        for (int i = 0; i < NUM_PINS && running; i++) {
            vals[i] = gpiod_line_get_value(lines[i]);
            if (vals[i] < 0) {
                fprintf(stderr, "Error reading GPIO %u: %s\n", pins[i], strerror(errno));
                continue;
            }
            printf("GPIO %u: %s\n", pins[i], vals[i] ? "HIGH" : "LOW");
        }
        if (running) sleep(2);
    }

    rc = EXIT_SUCCESS;

cleanup:
    for (int i = 0; i < NUM_PINS; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return rc;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PWM_PIN_1 17
#define PWM_PIN_2 22
#define PWM_PIN_3 27

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    int pins[] = {PWM_PIN_1, PWM_PIN_2, PWM_PIN_3};
    const int num_pins = (int)(sizeof(pins) / sizeof(pins[0]));

    for (int i = 0; i < num_pins && running; ++i) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: gpioSetMode failed for pin %d.\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetPWMfrequency(pins[i], 1000) != 0) {
            fprintf(stderr, "Warning: gpioSetPWMfrequency failed for pin %d.\n", pins[i]);
        }
        if (gpioSetPWMrange(pins[i], 100) != 0) {
            fprintf(stderr, "Warning: gpioSetPWMrange failed for pin %d.\n", pins[i]);
        }
    }

    while (running) {
        for (int i = 0; i < num_pins; ++i) {
            if (gpioPWM(pins[i], 50) != 0) {
                fprintf(stderr, "Error: gpioPWM failed for pin %d.\n", pins[i]);
                goto cleanup;
            }
        }
        printf("PWM ON\n");
        fflush(stdout);

        sleep(0.5);

        for (int i = 0; i < num_pins; ++i) {
            if (gpioPWM(pins[i], 0) != 0) {
                fprintf(stderr, "Error: gpioPWM failed for pin %d.\n", pins[i]);
                goto cleanup;
            }
        }
        printf("PWM OFF\n");
        fflush(stdout);

        sleep(0.5);
    }

cleanup:
    for (int i = 0; i < num_pins; ++i) {
        gpioPWM(pins[i], 0);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

