#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/videodev2.h>

#define DEVICE_NAME "/dev/video0"
#define OUTPUT_FILE "captured_image.jpg"

static volatile sig_atomic_t keep_running = 1;

static void signal_handler(int signum) {
    (void)signum;
    keep_running = 0;
}

int main(void) {
    int fd = -1;
    FILE *fp = NULL;
    unsigned char *buffer = NULL;
    struct v4l2_buffer buf;
    enum v4l2_buf_type type;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("Failed to install SIGINT handler");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("Failed to install SIGTERM handler");
        return EXIT_FAILURE;
    }

    /* Open the video device */
    fd = open(DEVICE_NAME, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", DEVICE_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Query capabilities */
    struct v4l2_capability cap;
    memset(&cap, 0, sizeof(cap));
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        fprintf(stderr, "Error querying capabilities: %s\n", strerror(errno));
        goto cleanup;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is not a video capture device\n", DEVICE_NAME);
        goto cleanup;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming I/O\n", DEVICE_NAME);
        goto cleanup;
    }

    /* Set format to YUYV (YUV 4:2:2) */
    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = 640;
    fmt.fmt.pix.height = 480;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        fprintf(stderr, "Error setting format: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Set image encoding to JPEG */
    struct v4l2_jpegcompression comp;
    memset(&comp, 0, sizeof(comp));
    comp.quality = 75;

    if (ioctl(fd, VIDIOC_S_JPEGCOMP, &comp) < 0) {
        fprintf(stderr, "Error setting JPEG compression: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Request buffers */
    unsigned int count;
    if (ioctl(fd, VIDIOC_REQBUFS, &count) < 0) {
        fprintf(stderr, "Error requesting buffers: %s\n", strerror(errno));
        goto cleanup;
    }

    if (count < 1) {
        fprintf(stderr, "Insufficient buffer memory\n");
        goto cleanup;
    }

    /* Query buffer */
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
        fprintf(stderr, "Error querying buffer: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Map buffer */
    buffer = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
    if (buffer == MAP_FAILED) {
        fprintf(stderr, "Error mapping buffer: %s\n", strerror(errno));
        buffer = NULL;
        goto cleanup;
    }

    /* Queue buffer */
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        fprintf(stderr, "Error queuing buffer: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Start streaming */
    type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        fprintf(stderr, "Error starting streaming: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Capture frame */
    fd_set fds;
    struct timeval tv;
    int r;

    FD_ZERO(&fds);
    FD_SET(fd, &fds);

    tv.tv_sec = 5;
    tv.tv_usec = 0;

    r = select(fd + 1, &fds, NULL, NULL, &tv);
    if (r == -1) {
        if (errno == EINTR) {
            fprintf(stderr, "Interrupted by signal\n");
        } else {
            fprintf(stderr, "select() failed: %s\n", strerror(errno));
        }
        goto cleanup;
    } else if (r == 0) {
        fprintf(stderr, "Timeout waiting for frame\n");
        goto cleanup;
    }

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        fprintf(stderr, "Error dequeuing buffer: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Save image */
    fp = fopen(OUTPUT_FILE, "wb");
    if (!fp) {
        fprintf(stderr, "Error opening output file: %s\n", strerror(errno));
        goto cleanup;
    }

    if (fwrite(buffer, 1, buf.bytesused, fp) != buf.bytesused) {
        fprintf(stderr, "Error writing image data: %s\n", strerror(errno));
        fclose(fp);
        fp = NULL;
        goto cleanup;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing output file: %s\n", strerror(errno));
        fp = NULL;
        goto cleanup;
    }
    fp = NULL;

    printf("Image saved as %s (%u bytes)\n", OUTPUT_FILE, buf.bytesused);

    ret = EXIT_SUCCESS;

cleanup:
    if (fp) {
        fclose(fp);
    }
    if (buffer && buffer != MAP_FAILED) {
        munmap(buffer, buf.length);
    }
    if (fd >= 0) {
        if (ioctl(fd, VIDIOC_STREAMOFF, &type) < 0) {
            fprintf(stderr, "Warning: error stopping streaming: %s\n", strerror(errno));
        }
        close(fd);
    }
    return ret;
}

