    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line_22 = NULL;
    struct gpiod_line *line_27 = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("Failed to install SIGINT handler");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("Failed to install SIGTERM handler");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Error opening %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    line_22 = gpiod_chip_get_line(chip, GPIO_22_OFFSET);
    if (!line_22) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_22_OFFSET, strerror(errno));
        goto cleanup;
    }

    line_27 = gpiod_chip_get_line(chip, GPIO_27_OFFSET);
    if (!line_27) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", GPIO_27_OFFSET, strerror(errno));
        goto cleanup;
    }

    /* Request both lines as outputs, initially low */
    if (gpiod_line_request_output(line_22, "digital-output-22", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO %d as output: %s\n", GPIO_22_OFFSET, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(line_27, "digital-output-27", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO %d as output: %s\n", GPIO_27_OFFSET, strerror(errno));
        goto cleanup;
    }

    printf("Digital output control started. Press Ctrl+C to exit.\n");

    while (keep_running) {
        if (gpiod_line_set_value(line_22, 1) < 0) {
            fprintf(stderr, "Error setting GPIO %d high: %s\n", GPIO_22_OFFSET, strerror(errno));
            break;
        }
        if (gpiod_line_set_value(line_27, 1) < 0) {
            fprintf(stderr, "Error setting GPIO %d high: %s\n", GPIO_27_OFFSET, strerror(errno));
            break;
        }
        printf("GPIO %d and %d set HIGH\n", GPIO_22_OFFSET, GPIO_27_OFFSET);
        usleep(POLL_INTERVAL_US);

        if (gpiod_line_set_value(line_22, 0) < 0) {
            fprintf(stderr, "Error setting GPIO %d low: %s\n", GPIO_22_OFFSET, strerror(errno));
            break;
        }
        if (gpiod_line_set_value(line_27, 0) < 0) {
            fprintf(stderr, "Error setting GPIO %d low: %s\n", GPIO_27_OFFSET, strerror(errno));
            break;
        }
        printf("GPIO %d and %d set LOW\n", GPIO_22_OFFSET, GPIO_27_OFFSET);
        usleep(POLL_INTERVAL_US);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line_22) {
        gpiod_line_release(line_22);
    }
    if (line_27) {
        gpiod_line_release(line_27);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define SSD1306_I2C_ADDR 0x3C

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write(int fd, const uint8_t *buf, size_t len) {
    if (write(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int ssd1306_command(int fd, uint8_t cmd) {
    uint8_t buf[2] = {0x00, cmd};
    return i2c_write(fd, buf, 2);
}

static int ssd1306_init(int fd) {
    if (ssd1306_command(fd, 0xAE) < 0) return -1; /* Display off */
    if (ssd1306_command(fd, 0xD5) < 0) return -1; /* Set display clock divide ratio/oscillator frequency */
    if (ssd1306_command(fd, 0x80) < 0) return -1;
    if (ssd1306_command(fd, 0xA8) < 0) return -1; /* Set multiplex ratio */
    if (ssd1306_command(fd, 0x3F) < 0) return -1; /* 1/64 duty */
    if (ssd1306_command(fd, 0xD3) < 0) return -1; /* Set display offset */
    if (ssd1306_command(fd, 0x00) < 0) return -1; /* No offset */
    if (ssd1306_command(fd, 0x40) < 0) return -1; /* Set start line address */
    if (ssd1306_command(fd, 0x8D) < 0) return -1; /* Charge pump regulator */
    if (ssd1306_command(fd, 0x14) < 0) return -1; /* Enable charge pump */
    if (ssd1306_command(fd, 0x20) < 0) return -1; /* Memory addressing mode */
    if (ssd1306_command(fd, 0x00) < 0) return -1; /* Horizontal addressing mode */
    if (ssd1306_command(fd, 0xA1) < 0) return -1; /* Segment re-map: column 127 mapped to SEG0 */
    if (ssd1306_command(fd, 0xC8) < 0) return -1; /* COM scan direction: remapped */
    if (ssd1306_command(fd, 0xDA) < 0) return -1; /* Set COM pins hardware configuration */
    if (ssd1306_command(fd, 0x12) < 0) return -1; /* Alternative pin configuration */
    if (ssd1306_command(fd, 0x81) < 0) return -1; /* Set contrast control */
    if (ssd1306_command(fd, 0xCF) < 0) return -1; /* Contrast value */
    if (ssd1306_command(fd, 0xD9) < 0) return -1; /* Set pre-charge period */
    if (ssd1306_command(fd, 0xF1) < 0) return -1; /* Phase 1: 1 count, Phase 2: 1 count */
    if (ssd1306_command(fd, 0xDB) < 0) return -1; /* Set VCOMH deselect level */
    if (ssd1306_command(fd, 0x40) < 0) return -1; /* ~0.77 x Vcc */
    if (ssd1306_command(fd, 0xA4) < 0) return -1; /* Entire display on (resume) */
    if (ssd1306_command(fd, 0xA6) < 0) return -1; /* Normal display (not inverted) */
    if (ssd1306_command(fd, 0xAF) < 0) return -1; /* Display on */
    return 0;
}

static int ssd1306_set_cursor(int fd, uint8_t col, uint8_t page) {
    if (ssd1306_command(fd, 0xB2) < 0) return -1; /* Set column start address for page boundary */
    if (ssd1306_command(fd, 0x00) < 0) return -1;
    if (ssd1306_command(fd, 0x10) < 0) return -1;
    if (ssd1306_command(fd, 0xB3) < 0) return -1; /* Set page start address */
    if (ssd1306_command(fd, page) < 0) return -1;
    if (ssd1306_command(fd, 0xB4) < 0) return -1; /* Set memory addressing mode */
    if (ssd1306_command(fd, 0x00) < 0) return -1; /* Horizontal addressing mode */
    if (ssd1306_command(fd, 0x40) < 0) return -1; /* Set column start address */
    if (ssd1306_command(fd, col) < 0) return -1;
    return 0;
}

static int ssd1306_clear(int fd) {
    uint8_t buf[128];
    memset(buf, 0x00, sizeof(buf));
    for (int p = 0; p < 8; p++) {
        if (ssd1306_set_cursor(fd, 0, (uint8_t)p) < 0) return -1;
        if (i2c_write(fd, buf, sizeof(buf)) < 0) return -1;
    }
    return 0;
}

static int ssd1306_display_string(int fd, const char *str) {
    if (!str || !*str) return -1;
    uint8_t col = 0;
    uint8_t page = 0;
    while (*str && col < 128) {
        if (col + 8 > 128) {
            page++;
            col = 0;
            if (page > 7) break;
            if (ssd1306_set_cursor(fd, 0, page) < 0) return -1;
        }
        uint8_t data[8];
        for (int i = 0; i < 8; i++) {
            data[i] = (uint8_t)(*(str++));
        }
        if (ssd1306_set_cursor(fd, col, page) < 0) return -1;
        if (i2c_write(fd, data, 8) < 0) return -1;
        col += 8;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, SSD1306_I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", SSD1306_I2C_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    if (ssd1306_init(fd) < 0) {
        fprintf(stderr, "SSD1306 initialization failed.\n");
        close(fd);
        return EXIT_FAILURE;
    }

    if (ssd1306_clear(fd) < 0) {
        fprintf(stderr, "Failed to clear display.\n");
        close(fd);
        return EXIT_FAILURE;
    }

    while (running) {
        char buffer[17];
        snprintf(buffer, sizeof(buffer), "Temperature: %.2f C", 25.5);
        if (ssd1306_display_string(fd, buffer) < 0) {
            fprintf(stderr, "Failed to display temperature.\n");
            break;
        }
        usleep(100000);
    }

    if (ssd1306_clear(fd) < 0) {
        fprintf(stderr, "Warning: failed to clear display during cleanup.\n");
    }
    close(fd);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define CONSUMER "gpio-demo"
#define CHIP_NAME "gpiochip0"

static volatile sig_atomic_t keep_running = 1;

static void sighandler(int signo)
{
    (void)signo;
    keep_running = 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[3] = {NULL, NULL, NULL};
    int pins[3] = {2, 3, 5};
    int vals[3] = {0, 0, 0};
    int rc = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    for (int i = 0; i < 3; i++) {
        lines[i] = gpiod_chip_get_line(chip, pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get line %d: %s\n", pins[i], strerror(errno));
            goto cleanup;
        }
    }

    for (int i = 0; i < 3; i++) {
        if (gpiod_line_request_output(lines[i], CONSUMER, 0) < 0) {
            fprintf(stderr, "Failed to request line %d as output: %s\n",
                    pins[i], strerror(errno));
            goto cleanup;
        }
    }

    while (keep_running) {
        for (int i = 0; i < 3; i++) {
            if (gpiod_line_set_value(lines[i], vals[i]) < 0) {
                fprintf(stderr, "Failed to set line %d: %s\n", pins[i], strerror(errno));
                goto cleanup;
            }
            printf("GPIO %d -> %d\n", pins[i], vals[i]);
        }
        fflush(stdout);
        sleep(5);
    }

    rc = EXIT_SUCCESS;

cleanup:
    for (int i = 0; i < 3; i++) {
        if (lines[i])
            gpiod_line_release(lines[i]);
    }
    if (chip)
        gpiod_chip_close(chip);

    return rc;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_PIN_1 8
#define PWM_PIN_2 9
#define PWM_PIN_3 11
#define PWM_PIN_4 18

static volatile sig_atomic_t running = 1;

static void signal_handler(int signum) {
    (void)signum;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install signal handler\n");
    }

    int pins[] = {PWM_PIN_1, PWM_PIN_2, PWM_PIN_3, PWM_PIN_4};
    const int num_pins = (int)(sizeof(pins) / sizeof(pins[0]));

    while (running) {
        printf("Applying PWM: ");
        for (int i = 0; i < num_pins; i++) {
            gpioPWM(pins[i], (i % 2 == 0) ? 128 : 64);
            printf("%d ", pins[i]);
        }
        printf("\n");
        fflush(stdout);

        if (running) {
            time_sleep(1.0);
        }
    }

    for (int i = 0; i < num_pins; i++) {
        gpioPWM(pins[i], 0);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    23
#define BUZZER_PIN  24

static volatile sig_atomic_t running = 1;

static void sighandler(int sig)
{
    (void)sig;
    running = 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig = NULL;
    struct gpiod_line *echo = NULL;
    struct gpiod_line *buz = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    trig = gpiod_chip_get_line(chip, TRIGGER_PIN);
    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    buz = gpiod_chip_get_line(chip, BUZZER_PIN);
    if (!trig || !echo || !buz) {
        fprintf(stderr, "Failed to get GPIO lines: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(trig, "hc-sr04-trig", 0) < 0 ||
        gpiod_line_request_input(echo, "hc-sr04-echo") < 0 ||
        gpiod_line_request_output(buz, "hc-sr04-buzz", 0) < 0) {
        perror("gpiod_line_request");
        goto cleanup;
    }

    while (running) {
        /* Ensure trigger starts low */
        if (gpiod_line_set_value(trig, 0) < 0) {
            perror("gpiod_line_set_value (trigger low)");
            break;
        }
        usleep(2);

        /* 10 us trigger pulse */
        if (gpiod_line_set_value(trig, 1) < 0) {
            perror("gpiod_line_set_value (trigger high)");
            break;
        }
        usleep(10);
        if (gpiod_line_set_value(trig, 0) < 0) {
            perror("gpiod_line_set_value (trigger low)");
            break;
        }

        /* Wait for echo rising edge */
        int timeout = 100000; /* 100 ms */
        while (gpiod_line_get_value(echo) == 0 && running && timeout-- > 0) {
            usleep(1);
        }
        if (timeout <= 0 || !running) {
            fprintf(stderr, "Timeout waiting for echo start\n");
            break;
        }

        unsigned long start_tick = 0;
        timeout = 100000;
        while (gpiod_line_get_value(echo) == 1 && running && timeout-- > 0) {
            start_tick++;
            usleep(1);
        }
        if (timeout <= 0 || !running) {
            fprintf(stderr, "Timeout waiting for echo end\n");
            break;
        }

        unsigned long elapsed = start_tick;
        unsigned long end_tick = start_tick + elapsed;

        /* Wait for echo falling edge */
        timeout = 100000;
        while (gpiod_line_get_value(echo) == 1 && running && timeout-- > 0) {
            end_tick++;
            usleep(1);
        }
        if (timeout <= 0 || !running) {
            fprintf(stderr, "Timeout waiting for echo end\n");
            break;
        }

        unsigned long duration = end_tick - start_tick;
        float distance = (duration / 58.0f);

        printf("Distance: %.2f cm\n", distance);

        if (distance < 50.0f) {
            if (gpiod_line_set_value(buz, 1) < 0) {
                perror("gpiod_line_set_value (buzzer on)");
                break;
            }
            usleep(500000);
            if (gpiod_line_set_value(buz, 0) < 0) {
                perror("gpiod_line_set_value (buzzer off)");
                break;
            }
        }

        usleep(200000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (trig) gpiod_line_release(trig);
    if (echo) gpiod_line_release(echo);
    if (buz)  gpiod_line_release(buz);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

