#define LED_PIN 18

static volatile sig_atomic_t running = 1;

static void signal_handler(int signum) {
    (void)signum;
    running = 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed (device may be absent).\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        if (gpioWrite(LED_PIN, 1) != 0) {
            fprintf(stderr, "Warning: gpioWrite high failed on pin %d.\n", LED_PIN);
        }
        usleep(10000);
        if (!running) break;
        if (gpioWrite(LED_PIN, 0) != 0) {
            fprintf(stderr, "Warning: gpioWrite low failed on pin %d.\n", LED_PIN);
        }
        usleep(10000);
    }

    gpioWrite(LED_PIN, 0);
    gpioTerminate();
