static const unsigned int pins[NUM_PINS] = {1, 4, 5, 6, 21, 22, 23, 24};

static volatile sig_atomic_t running = 1;

static void sighandler(int signo) {
    (void)signo;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_PINS];
    int vals[NUM_PINS];
    int rc = EXIT_FAILURE;

    memset(lines, 0, sizeof(lines));
    memset(vals, 0, sizeof(vals));

    for (int i = 0; i < NUM_PINS; i++) {
        lines[i] = NULL;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGINT): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGTERM): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_PINS; i++) {
        lines[i] = gpiod_chip_get_line(chip, pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get line %u: %s\n", pins[i], strerror(errno));
            goto cleanup;
        }
        if (gpiod_line_request_output(lines[i], "digital-out-demo", 0) < 0) {
            fprintf(stderr, "Failed to request line %u as output: %s\n", pins[i], strerror(errno));
            goto cleanup;
        }
        vals[i] = 0;
    }

    printf("GPIO outputs initialized:\n");
    for (int i = 0; i < NUM_PINS; i++) {
        if (gpiod_line_set_value(lines[i], vals[i]) < 0) {
            fprintf(stderr, "Failed to set value on line %u: %s\n", pins[i], strerror(errno));
            goto cleanup;
        }
        printf("  GPIO %u -> %d\n", pins[i], vals[i]);
    }
    printf("Press Ctrl+C to exit.\n");

    while (running) {
        sleep(1);
    }

    rc = EXIT_SUCCESS;

cleanup:
    for (int i = 0; i < NUM_PINS; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return rc;
}

