#define BME280_I2C_ADDR 0x76
#define I2C_BUS "/dev/i2c-1"

#define BME280_REG_ID 0xD0
#define BME280_REG_RESET 0xE0
#define BME280_REG_CTRL_HUM 0xF2
#define BME280_REG_STATUS 0xF3
#define BME280_REG_CTRL_MEAS 0xF4
#define BME280_REG_CONFIG 0xF5
#define BME280_REG_DATA 0xF7

static volatile sig_atomic_t running = 1;

static void sighandler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

static int i2c_read(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, len) != (ssize_t)len) return -1;
    return 0;
}

static int bme280_wait_ready(int fd) {
    for (int i = 0; i < 100; i++) {
        uint8_t status;
        if (i2c_read(fd, BME280_REG_STATUS, &status, 1) < 0) return -1;
        if ((status & 0x01) == 0) return 0;
        usleep(2000);
    }
    return -1;
}

static int bme280_init(int fd) {
    uint8_t id;
    if (i2c_read(fd, BME280_REG_ID, &id, 1) < 0) {
        fprintf(stderr, "Error: cannot read chip ID: %s\n", strerror(errno));
        return -1;
    }
    if (id != 0x60) {
        fprintf(stderr, "Error: unexpected chip ID 0x%02X (expected 0x60)\n", id);
        return -1;
    }

    if (i2c_write(fd, BME280_REG_RESET, 0xB6) < 0) {
        fprintf(stderr, "Error: reset write failed: %s\n", strerror(errno));
        return -1;
    }
    usleep(2000);

    if (bme280_wait_ready(fd) < 0) {
        fprintf(stderr, "Error: BME280 not ready after reset\n");
        return -1;
    }

    if (i2c_write(fd, BME280_REG_CTRL_HUM, 0x01) < 0) return -1;
    if (i2c_write(fd, BME280_REG_CONFIG, 0xA0) < 0) return -1;
    if (i2c_write(fd, BME280_REG_CTRL_MEAS, 0x27) < 0) return -1;

    return 0;
}

static int bme280_read(int fd, float *temp, float *hum) {
    uint8_t data[8];
    if (i2c_read(fd, BME280_REG_DATA, data, 8) < 0) return -1;

    int32_t raw_t = (data[3] << 12) | (data[4] << 4) | (data[5] >> 4);
    int32_t raw_h = (data[6] << 8) | data[7];

    *temp = (float)raw_t / 100.0f;
    *hum = (float)raw_h / 1024.0f;
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

