        fprintf(stderr, "Error setting I2C slave 0x%02X: %s\n", BME280_I2C_ADDR, strerror(errno));
        close(fd);
        return 1;
    }

    if (bme280_init(fd) < 0) {
        fprintf(stderr, "BME280 initialization failed.\n");
        close(fd);
        return 1;
    }

    while (running) {
        float temp, hum;
        if (bme280_read(fd, &temp, &hum) < 0) {
            fprintf(stderr, "Error reading BME280: %s\n", strerror(errno));
            break;
        }
        printf("Temperature: %.2f C, Humidity: %.2f %%\n", temp, hum);
        fflush(stdout);
        sleep(5);
    }

    close(fd);
    return 0;
}

