#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define ADS1115_ADDR   0x48

/* ADS1115 register addresses */
#define REG_CONVERSION 0x00
#define REG_CONFIG     0x01

/*
 * Config register bits (16-bit, big-endian on the bus):
 *   [15]    OS       = 1  (begin single conversion)
 *   [14:12] MUX      = 100 (AIN0 vs GND)
 *   [11:9]  PGA      = 001 (±4.096 V)
 *   [8]     MODE     = 1  (single-shot)
 *   [7:5]   DR       = 100 (128 SPS)
 *   [4]     C_MODE   = 0
 *   [3]     C_POL    = 0
 *   [2]     C_LAT    = 0
 *   [1:0]   COMP      = 11 (disabled)
 */
#define CONFIG_VALUE   0xC083

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int signo) {
    (void)signo;
    g_running = 0;
}

static int i2c_write_reg16(int fd, uint8_t reg, uint16_t val) {
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (uint8_t)(val >> 8);
    buf[2] = (uint8_t)(val & 0xFF);

    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "i2c_write_reg16(0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *out) {
    uint8_t buf[2];

    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read_reg16 write(0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }

    if (read(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "i2c_read_reg16 read(0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }

    *out = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n", ADS1115_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    /* Verify device presence by reading the config register */
    uint16_t cfg_check = 0;
    if (i2c_read_reg16(fd, REG_CONFIG, &cfg_check) < 0) {
        fprintf(stderr, "ADS1115 not responding at 0x%02X\n", ADS1115_ADDR);
        close(fd);
        return EXIT_FAILURE;
    }

    while (g_running) {
        if (i2c_write_reg16(fd, REG_CONFIG, CONFIG_VALUE) < 0) {
            break;
        }

        /* Wait for conversion to complete (~8 ms at 128 SPS) */
        usleep(10000);

        uint16_t raw = 0;
        if (i2c_read_reg16(fd, REG_CONVERSION, &raw) < 0) {
            break;
        }

        /* Convert to signed 16-bit two's complement */
        int16_t value = (int16_t)raw;
        printf("%d\n", value);
        fflush(stdout);

        usleep(200000);
    }

    close(fd);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
