            fprintf(stderr, "Failed to set line value: %s\n", strerror(errno));
            goto cleanup;
        }

        printf("GPIO %d set to %d\n", GPIO_LINE_OFFSET, state);
        fflush(stdout);

        usleep(POLL_INTERVAL_US);
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Release the line and close the chip */
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    if (ret == EXIT_SUCCESS) {
        printf("\nExiting cleanly.\n");
    }
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>

#define I2C_BUS "/dev/i2c-1"
#define HD44780_ADDR 0x27

static volatile sig_atomic_t running = 1;

void int_handler(int sig) {
    (void)sig;
    running = 0;
}

int i2c_write_byte(int fd, unsigned char data) {
    if (write(fd, &data, 1) != 1) {
        perror("i2c_write_byte");
        return -1;
    }
    return 0;
}

int hd44780_command(int fd, unsigned char cmd) {
    if (i2c_write_byte(fd, cmd) < 0) return -1;
    usleep(2000);
    return 0;
}

int hd44780_data(int fd, unsigned char data) {
    if (i2c_write_byte(fd, data | 0x08) < 0) return -1; // Enable high
    usleep(1000);
    if (i2c_write_byte(fd, data & 0xF0) < 0) return -1; // Enable low
    usleep(1000);
    return 0;
}

int hd44780_init(int fd) {
    usleep(50000);
    if (hd44780_command(fd, 0x30) < 0) return -1;
    usleep(5000);
    if (hd44780_command(fd, 0x30) < 0) return -1;
    usleep(150);
    if (hd44780_command(fd, 0x30) < 0) return -1;
    if (hd44780_command(fd, 0x20) < 0) return -1; // 4-bit mode
    if (hd44780_command(fd, 0x28) < 0) return -1; // 2 lines, 5x8 font
    if (hd44780_command(fd, 0x0C) < 0) return -1; // Display on, cursor off
    if (hd44780_command(fd, 0x06) < 0) return -1; // Increment cursor
    if (hd44780_command(fd, 0x01) < 0) return -1; // Clear
    usleep(2000);
    return 0;
}

int hd44780_set_cursor(int fd, int row, int col) {
    unsigned char addr = (row == 0) ? 0x00 : 0x40;
    addr += col;
    if (hd44780_command(fd, 0x80 | addr) < 0) return -1;
    return 0;
}

int main() {
    struct sigaction sa;
    sa.sa_handler = int_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, HD44780_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(fd);
        return 1;
    }

    if (hd44780_init(fd) < 0) {
        fprintf(stderr, "HD44780 initialization failed\n");
        close(fd);
        return 1;
    }

    while (running) {
        int val = rand() % 100;
        char buf[17];
        snprintf(buf, sizeof(buf), "%d", val);

        hd44780_set_cursor(fd, 0, 0);
        for (int i = 0; i < 16 && buf[i] != '\0'; i++) {
            if (hd44780_data(fd, buf[i]) < 0) {
                fprintf(stderr, "Data write failed\n");
                break;
            }
        }

        sleep(10);
    }

    hd44780_command(fd, 0x01); // Clear display
    close(fd);
    printf("\nProgram terminated cleanly.\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>

#define I2C_BUS "/dev/i2c-1"
#define MPU6050_ADDR 0x68

#define PWR_MGMT_1   0x6B
#define ACCEL_XOUT_H 0x3B

static volatile sig_atomic_t running = 1;
static int g_fd = -1;

static void sighandler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg(uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(g_fd, buf, 2) != 2) return -1;
    return 0;
}

static int i2c_read_burst(uint8_t reg, uint8_t *buf, size_t len) {
    if (write(g_fd, &reg, 1) != 1) return -1;
    if (read(g_fd, buf, len) != (ssize_t)len) return -1;
    return 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    g_fd = open(I2C_BUS, O_RDWR);
    if (g_fd < 0) {
        perror("open " I2C_BUS);
        return EXIT_FAILURE;
    }

    if (ioctl(g_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(g_fd);
        return EXIT_FAILURE;
    }

    if (i2c_write_reg(PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "MPU6050 not responding at 0x%02X\n", MPU6050_ADDR);
        close(g_fd);
        return EXIT_FAILURE;
    }

    for (int i = 0; i < 100 && running; ++i) {
        uint8_t buf[6];
        if (i2c_read_burst(ACCEL_XOUT_H, buf, sizeof(buf)) < 0) {
            fprintf(stderr, "I2C read failed\n");
            break;
        }
        int16_t ax = (int16_t)((buf[0] << 8) | buf[1]);
        int16_t ay = (int16_t)((buf[2] << 8) | buf[3]);
        int16_t az = (int16_t)((buf[4] << 8) | buf[5]);
        printf("ax=%d ay=%d az=%d\n", ax, ay, az);
        fflush(stdout);
        usleep(10000);
    }

    close(g_fd);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_14_OFFSET 14
#define GPIO_15_OFFSET 15
#define POLL_INTERVAL_SEC 5

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int signum)
{
    (void)signum;
    g_running = 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line14 = NULL;
    struct gpiod_line *line15 = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Get the two lines */
    line14 = gpiod_chip_get_line(chip, GPIO_14_OFFSET);
    if (!line14) {
        fprintf(stderr, "Failed to get line %d: %s\n", GPIO_14_OFFSET, strerror(errno));
        goto cleanup;
    }

    line15 = gpiod_chip_get_line(chip, GPIO_15_OFFSET);
    if (!line15) {
        fprintf(stderr, "Failed to get line %d: %s\n", GPIO_15_OFFSET, strerror(errno));
        goto cleanup;
    }

    /* Request both lines as outputs, initial value LOW (0) */
    if (gpiod_line_request_output(line14, "digital-out", 0) < 0) {
        fprintf(stderr, "Failed to request line %d as output: %s\n",
                GPIO_14_OFFSET, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(line15, "digital-out", 0) < 0) {
        fprintf(stderr, "Failed to request line %d as output: %s\n",
                GPIO_15_OFFSET, strerror(errno));
        goto cleanup;
    }

    printf("Digital output control started. Press Ctrl+C to exit.\n");

    while (g_running) {
        /* Apply HIGH (1) to both lines */
        if (gpiod_line_set_value(line14, 1) < 0) {
            fprintf(stderr, "Failed to set line %d high: %s\n",
                    GPIO_14_OFFSET, strerror(errno));
            break;
        }
        if (gpiod_line_set_value(line15, 1) < 0) {
            fprintf(stderr, "Failed to set line %d high: %s\n",
                    GPIO_15_OFFSET, strerror(errno));
            break;
        }
        printf("GPIO %d and %d set HIGH\n", GPIO_14_OFFSET, GPIO_15_OFFSET);

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < POLL_INTERVAL_SEC && g_running; i++) {
            sleep(1);
        }
    }

    /* Ensure both lines are LOW before releasing */
    gpiod_line_set_value(line14, 0);
    gpiod_line_set_value(line15, 0);

    ret = EXIT_SUCCESS;

cleanup:
    if (line14)
        gpiod_line_release(line14);
    if (line15)
        gpiod_line_release(line15);
    if (chip)
        gpiod_chip_close(chip);

    if (ret == EXIT_SUCCESS)
        printf("Program terminated cleanly.\n");
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <pigpio.h>

#include <MQTTClient.h>

#define MQTT_HOST "localhost"
#define MQTT_PORT 1883
#define MQTT_TOPIC "sensor_data"
#define MQTT_CLIENT_ID "rpi_sensor_publisher"

#define SENSOR_READ_INTERVAL_US 10000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_sensor_data(float *temperature, float *humidity) {
    /* Simulate reading from a hypothetical sensor */
    static int count = 0;
    if (count++ % 2 == 0) {
        *temperature = 25.0f + ((float)(rand() % 100) / 100.0f);
        *humidity = 45.0f + ((float)(rand() % 100) / 100.0f);
        return 0;
    }
    return -1;
}

static int validate_sensor_data(float temperature, float humidity) {
    if (temperature < -40.0f || temperature > 100.0f) {
        fprintf(stderr, "Error: Temperature out of range: %.2f\n", temperature);
        return -1;
    }
    if (humidity < 0.0f || humidity > 100.0f) {
        fprintf(stderr, "Error: Humidity out of range: %.2f\n", humidity);
        return -1;
    }
    return 0;
}

static int format_mqtt_message(float temperature, float humidity, char *buffer, size_t buffer_size) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        perror("localtime");
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo) == 0) {
        fprintf(stderr, "Error: strftime failed\n");
        return -1;
    }

    int result = snprintf(buffer, buffer_size,
                          "{\"timestamp\": \"%s\", \"temperature\": %.2f, \"humidity\": %.2f}",
                          timestamp, temperature, humidity);

    if (result < 0 || (size_t)result >= buffer_size) {
        fprintf(stderr, "Error: Message formatting failed\n");
        return -1;
    }
    return 0;
}

int main(void) {
    MQTTClient client;
    MQTTClient_connectOptions conn_opts = MQTTClient_connectOptions_initializer;
    char message_buffer[256];
    int rc;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    MQTTClient_create(&client, MQTT_HOST, MQTT_CLIENT_ID,
                      MQTTCLIENT_PERSISTENCE_NONE, NULL);

    conn_opts.keepAliveInterval = 20;
    conn_opts.cleansession = 1;

    if ((rc = MQTTClient_connect(client, &conn_opts)) != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Error: Failed to connect, return code %d\n", rc);
        goto cleanup_gpio;
    }

    while (running) {
        float temperature, humidity;

        if (read_sensor_data(&temperature, &humidity) != 0) {
            fprintf(stderr, "Warning: Sensor read failed, skipping cycle\n");
            usleep(SENSOR_READ_INTERVAL_US);
            continue;
        }

        if (validate_sensor_data(temperature, humidity) != 0) {
            fprintf(stderr, "Warning: Sensor data invalid, skipping cycle\n");
            usleep(SENSOR_READ_INTERVAL_US);
            continue;
        }

        if (format_mqtt_message(temperature, humidity, message_buffer, sizeof(message_buffer)) != 0) {
            fprintf(stderr, "Error: Failed to format MQTT message, skipping cycle\n");
            usleep(SENSOR_READ_INTERVAL_US);
            continue;
        }

        if ((rc = MQTTClient_publishMessage(client, MQTT_TOPIC, message_buffer, NULL)) != MQTTCLIENT_SUCCESS) {
            fprintf(stderr, "Error: Failed to publish message, return code %d\n", rc);
        } else {
            printf("Published: %s\n", message_buffer);
        }

        usleep(SENSOR_READ_INTERVAL_US);
    }

    MQTTClient_disconnect(client, 1000);
    MQTTClient_destroy(&client);

cleanup_gpio:
    gpioTerminate();
    return EXIT_SUCCESS;
}

