#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <time.h>
#include <gpiod.h>

#define TRIGGER_PIN  17
#define ECHO_PIN     22
#define TRIGGER_PIN2 27

#define SPEED_OF_SOUND_CM_PER_S 34300.0
#define MAX_DISTANCE_CM         400.0
#define MIN_DISTANCE_CM         2.0
#define TIMEOUT_US              100000
#define POLL_INTERVAL_MS        100

static volatile sig_atomic_t g_running = 1;

static void sighandler(int signo)
{
    (void)signo;
    g_running = 0;
}

static bool in_range(double d, double minv, double maxv)
{
    return d >= minv && d <= maxv;
}

static void sleep_us(unsigned int us)
{
    struct timespec ts = {
        .tv_sec  = us / 1000000U,
        .tv_nsec = (long)(us % 1000000U) * 1000L
    };
    nanosleep(&ts, NULL);
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig = NULL;
    struct gpiod_line *echo = NULL;
    struct gpiod_line *trig2 = NULL;
    int rc = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    trig  = gpiod_chip_get_line(chip, TRIGGER_PIN);
    echo  = gpiod_chip_get_line(chip, ECHO_PIN);
    trig2 = gpiod_chip_get_line(chip, TRIGGER_PIN2);
    if (!trig || !echo || !trig2) {
        fprintf(stderr, "Failed to get GPIO lines: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(trig, "hc-sr04-trig", 0) < 0 ||
        gpiod_line_request_output(trig2, "hc-sr04-trig2", 0) < 0 ||
        gpiod_line_request_input(echo, "hc-sr04-echo") < 0) {
        perror("gpiod_line_request");
        goto cleanup;
    }

    while (g_running) {
        /* --- Trigger single measurement --- */
        if (gpiod_line_set_value(trig, 0) < 0) {
            perror("gpiod_line_set_value(0)");
            break;
        }
        sleep_us(2);

        if (gpiod_line_set_value(trig, 1) < 0) {
            perror("gpiod_line_set_value(1)");
            break;
        }
        sleep_us(10);
        if (gpiod_line_set_value(trig, 0) < 0) {
            perror("gpiod_line_set_value(0)");
            break;
        }

        /* --- Wait for echo rising edge --- */
        unsigned int t0 = 0;
        while (gpiod_line_get_value(echo) == 0) {
            if (t0 >= TIMEOUT_US) {
                fprintf(stderr, "Timeout waiting for echo start\n");
                break;
            }
            sleep_us(POLL_INTERVAL_MS * 1000U);
            t0 += POLL_INTERVAL_MS * 1000U;
        }
        if (!g_running) break;

        unsigned int start_tick = 0;
        while (gpiod_line_get_value(echo) == 1) {
            if (start_tick >= TIMEOUT_US) {
                fprintf(stderr, "Timeout waiting for echo end\n");
                break;
            }
            sleep_us(POLL_INTERVAL_MS * 1000U);
            start_tick += POLL_INTERVAL_MS * 1000U;
        }
        if (!g_running) break;

        unsigned int elapsed = start_tick - t0;
        if (elapsed == 0) {
            fprintf(stderr, "Invalid pulse width\n");
            continue;
        }

        double distance = (double)elapsed * SPEED_OF_SOUND_CM_PER_S / 2000000.0;

        if (!in_range(distance, MIN_DISTANCE_CM, MAX_DISTANCE_CM)) {
            fprintf(stderr, "Distance %.2f cm out of range [%.0f-%.0f]\n",
                    distance, MIN_DISTANCE_CM, MAX_DISTANCE_CM);
            continue;
        }

        printf("Distance: %.2f cm\n", distance);
        fflush(stdout);
    }

    rc = EXIT_SUCCESS;

cleanup:
    if (trig)   gpiod_line_release(trig);
    if (echo)   gpiod_line_release(echo);
    if (trig2)  gpiod_line_release(trig2);
    if (chip)   gpiod_chip_close(chip);
    return rc;
}

