#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <time.h>
#include <sys/time.h>

#include <MQTTClient.h>

#define MAX_PAYLOAD 1024

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

typedef struct {
    char *device_id;
    char *mqtt_broker;
    char *mqtt_topic;
    char *payload;
} config_t;

static int parse_config(const char *filename, config_t *cfg) {
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        fprintf(stderr, "Error opening config file: %s\n", strerror(errno));
        return -1;
    }

    char line[512];
    while (fgets(line, sizeof(line), fp)) {
        char *key = strtok(line, "=");
        char *val = strtok(NULL, "\n");
        if (!key || !val) continue;

        if (strcmp(key, "device_id") == 0) cfg->device_id = strdup(val);
        else if (strcmp(key, "mqtt_broker") == 0) cfg->mqtt_broker = strdup(val);
        else if (strcmp(key, "mqtt_topic") == 0) cfg->mqtt_topic = strdup(val);
        else if (strcmp(key, "payload") == 0) cfg->payload = strdup(val);
    }

    fclose(fp);

    if (!cfg->device_id || !cfg->mqtt_broker || !cfg->mqtt_topic || !cfg->payload) {
        fprintf(stderr, "Missing required config values\n");
        return -1;
    }
    return 0;
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <config_file> <log_file>\n", argv[0]);
        return 1;
    }

    config_t cfg;
    memset(&cfg, 0, sizeof(cfg));

    if (parse_config(argv[1], &cfg) != 0) {
        free(cfg.device_id);
        free(cfg.mqtt_broker);
        free(cfg.mqtt_topic);
        free(cfg.payload);
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    MQTTClient client;
    MQTTClient_connectOptions conn_opts = MQTTClient_connectOptions_initializer;
    int rc;

    rc = MQTTClient_create(&client, cfg.mqtt_broker, "sensor_node", MQTTCLIENT_PERSISTENCE_NONE);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to create MQTT client, return code %d\n", rc);
        goto cleanup;
    }

    conn_opts.keepAliveInterval = 60;
    conn_opts.cleansession = 1;

    rc = MQTTClient_connect(client, &conn_opts);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to connect to MQTT broker, return code %d\n", rc);
        goto cleanup;
    }

    char payload[MAX_PAYLOAD];
    snprintf(payload, sizeof(payload), "%s", cfg.payload);

    rc = MQTTClient_publish(client, cfg.mqtt_topic, strlen(payload), payload, 0, 1);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to publish message, return code %d\n", rc);
    } else {
        printf("Published: %s\n", payload);
    }

    MQTTClient_disconnect(client, 1000);
    MQTTClient_destroy(&client);

cleanup:
    free(cfg.device_id);
    free(cfg.mqtt_broker);
    free(cfg.mqtt_topic);
    free(cfg.payload);
    return (rc == MQTTCLIENT_SUCCESS) ? 0 : 1;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PWM_PIN 18
#define PWM_RANGE 255

static volatile sig_atomic_t running = 1;

static void signal_handler(int signum) {
    (void)signum;
    running = 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed (device may be absent).\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PWM_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(PWM_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "Error: failed to set PWM range on GPIO %d.\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        int duty_cycle = rand() % (PWM_RANGE + 1);
        if (gpioPWM(PWM_PIN, duty_cycle) != 0) {
            fprintf(stderr, "Warning: gpioPWM failed for duty cycle %d.\n", duty_cycle);
        }
        printf("GPIO %d PWM duty cycle: %d\n", PWM_PIN, duty_cycle);
        fflush(stdout);

        for (int i = 0; i < 5 && running; i++) {
            sleep(1);
        }
    }

    gpioPWM(PWM_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

