            int rc = gpiod_line_event_wait(echo, &(struct timespec){0, TIMEOUT_US});
            if (rc < 0) {
                perror("gpiod_line_event_wait(rising)");
                break;
            }
            if (rc == 0) {
                fprintf(stderr, "Timeout waiting for echo start\n");
                continue;
            }
            if (gpiod_line_event_read(echo, NULL) < 0) {
                perror("gpiod_line_event_read(rising)");
                break;
            }
            start = gpiod_line_get_value(echo);
            if (start < 0) {
                perror("gpiod_line_get_value(rising)");
                break;
            }
        } else {
            usleep(50);
            continue;
        }

        /* Wait for echo falling edge */
        val = gpiod_line_get_value(echo);
        if (val < 0) {
            perror("gpiod_line_get_value(falling)");
            break;
        }
        if (val == 0) {
            unsigned long end = 0;
            int rc = gpiod_line_event_wait(echo, &(struct timespec){0, TIMEOUT_US});
            if (rc < 0) {
                perror("gpiod_line_event_wait(falling)");
                break;
            }
            if (rc == 0) {
                fprintf(stderr, "Timeout waiting for echo end\n");
                continue;
            }
            if (gpiod_line_event_read(echo, NULL) < 0) {
                perror("gpiod_line_event_read(falling)");
                break;
            }
            end = gpiod_line_get_value(echo);
            if (end < 0) {
                perror("gpiod_line_get_value(falling)");
                break;
            }
        } else {
            usleep(50);
            continue;
        }

        unsigned long diff = end - start;
        if (diff > 0 && diff < 1000000) {
            float distance = (float)diff / 58.0f;
            printf("Distance: %.2f cm\n", distance);
            fflush(stdout);
        } else {
            fprintf(stderr, "Invalid measurement (%lu us)\n", diff);
        }

        usleep(200000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (trig) gpiod_line_release(trig);
    if (echo) gpiod_line_release(echo);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

