#include <signal.h>
#include <errno.h>
#include <time.h>
#include <sys/time.h>

#include <MQTTClient.h>

#define MAX_RETRIES 3
#define RETRY_DELAY_MS 1000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

typedef struct {
    char *device_id;
    char *topic;
    char *broker_address;
    int port;
    int keepalive_interval;
    int qos;
} config_t;

static void parse_config(const char *config_str, config_t *cfg) {
    cfg->device_id = NULL;
    cfg->topic = NULL;
    cfg->broker_address = NULL;
    cfg->port = 1883;
    cfg->keepalive_interval = 60;
    cfg->qos = 0;

    char *saveptr = NULL;
    char *token = strtok_r((char *)config_str, ",", &saveptr);
    while (token != NULL) {
        char *key = strtok_r(token, "=", &saveptr);
        char *value = strtok_r(NULL, "", &saveptr);

        if (key == NULL || value == NULL) {
            token = strtok_r(NULL, ",", &saveptr);
            continue;
        }

        if (strcmp(key, "device_id") == 0) {
            cfg->device_id = strdup(value);
        } else if (strcmp(key, "topic") == 0) {
            cfg->topic = strdup(value);
        } else if (strcmp(key, "broker_address") == 0) {
            cfg->broker_address = strdup(value);
        } else if (strcmp(key, "port") == 0) {
            cfg->port = atoi(value);
        } else if (strcmp(key, "keepalive_interval") == 0) {
            cfg->keepalive_interval = atoi(value);
        } else if (strcmp(key, "qos") == 0) {
            cfg->qos = atoi(value);
        }
        token = strtok_r(NULL, ",", &saveptr);
    }
}

static void free_config(config_t *cfg) {
    free(cfg->device_id);
    free(cfg->topic);
    free(cfg->broker_address);
    cfg->device_id = NULL;
    cfg->topic = NULL;
    cfg->broker_address = NULL;
}

static int validate_reading(const char *reading) {
    /* Simple byte-length check; real validation depends on sensor protocol */
    return (reading != NULL && strlen(reading) > 0);
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s \"config=device_id=...,topic=...,broker_address=...,port=...,keepalive_interval=...,qos=\"\n", argv[0]);
        return EXIT_FAILURE;
    }

    config_t cfg;
    parse_config(argv[1], &cfg);

    if (cfg.device_id == NULL || cfg.topic == NULL || cfg.broker_address == NULL) {
        fprintf(stderr, "Error: Missing required configuration parameters.\n");
        free_config(&cfg);
        return EXIT_FAILURE;
    }

    if (cfg.port <= 0 || cfg.port > 65535) {
        fprintf(stderr, "Error: Invalid port number: %d\n", cfg.port);
        free_config(&cfg);
        return EXIT_FAILURE;
    }

    if (cfg.qos < 0 || cfg.qos > 2) {
        fprintf(stderr, "Error: Invalid QoS level: %d\n", cfg.qos);
        free_config(&cfg);
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        free_config(&cfg);
        return EXIT_FAILURE;
    }

    MQTTClient client;
    MQTTClient_connectOptions conn_opts = MQTTClient_connectOptions_initializer;
    int rc = 0;

    if ((rc = MQTTClient_create(&client, cfg.broker_address, "sensor_publisher",
                                MQTTCLIENT_PERSISTENCE_NONE)) != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Error: Failed to create MQTT client: %s\n", MQTTClient_strerror(rc));
        free_config(&cfg);
        return EXIT_FAILURE;
    }

    conn_opts.keepAliveInterval = cfg.keepalive_interval;
    conn_opts.cleansession = 1;
    conn_opts.connectTimeout = 10;

    int retries = 0;
    do {
        if ((rc = MQTTClient_connect(client, &conn_opts)) != MQTTCLIENT_SUCCESS) {
            fprintf(stderr, "Error: Failed to connect to MQTT broker: %s (attempt %d/%d)\n",
                    MQTTClient_strerror(rc), retries + 1, MAX_RETRIES);
            retries++;
            if (retries < MAX_RETRIES) {
                sleep(RETRY_DELAY_MS / 1000);
            }
        } else {
            break;
        }
    } while (running && retries < MAX_RETRIES);

    if (!running) {
        fprintf(stderr, "Interrupted before connection.\n");
        MQTTClient_disconnect(client, 1000);
        MQTTClient_destroy(&client);
        free_config(&cfg);
        return EXIT_FAILURE;
    }

    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Error: Could not connect to MQTT broker after %d attempts.\n", MAX_RETRIES);
        MQTTClient_disconnect(client, 1000);
        MQTTClient_destroy(&client);
        free_config(&cfg);
        return EXIT_FAILURE;
    }

    printf("Connected to MQTT broker at %s:%d\n", cfg.broker_address, cfg.port);

    char payload[256];
    time_t now = time(NULL);
    struct tm *tm_info = localtime(&now);
    strftime(payload, sizeof(payload), "%Y-%m-%dT%H:%M:%SZ", tm_info);

    if (validate_reading(payload)) {
        if ((rc = MQTTClient_publish(client, cfg.topic, 0, payload, cfg.qos, 0)) != MQTTCLIENT_SUCCESS) {
            fprintf(stderr, "Error: Failed to publish message: %s\n", MQTTClient_strerror(rc));
        } else {
            printf("Published reading: %s\n", payload);
        }
    } else {
        fprintf(stderr, "Error: Invalid reading data.\n");
    }

    MQTTClient_disconnect(client, 1000);
    MQTTClient_destroy(&client);
    free_config(&cfg);

    if (rc != MQTTCLIENT_SUCCESS) {
        return EXIT_FAILURE;
    }

    return EXIT_SUCCESS;
}

