#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <MQTTClient.h>

#define MQTT_HOST "localhost"
#define MQTT_PORT 1883
#define MQTT_TOPIC "sensor/ads1115"
#define ADS1115_ADDR 0x48
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_CONFIG_BASE 0x4000
#define ADS1115_CONFIG_COMP_QUE_DISABLE 0x0003
#define ADS1115_CONFIG_OS_BEGIN 0x8000
#define ADS1115_CONFIG_MUX_AIN0_GND 0x4000
#define ADS1115_CONFIG_PGA_4_096V 0x0200
#define ADS1115_CONFIG_MODE_SINGLE 0x0100
#define ADS1115_CONFIG_DR_128_SPS 0x0080

static volatile sig_atomic_t running = 1;
static MQTTClient client;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int ads1115_init(int handle) {
    int config = ADS1115_CONFIG_OS_BEGIN | ADS1115_CONFIG_MUX_AIN0_GND |
                 ADS1115_CONFIG_PGA_4_096V | ADS1115_CONFIG_MODE_SINGLE |
                 ADS1115_CONFIG_DR_128_SPS | ADS1115_CONFIG_COMP_QUE_DISABLE;
    char buf[2];
    buf[0] = ADS1115_REG_CONFIG;
    buf[1] = (config >> 8) & 0xFF;
    if (i2cWriteDevice(handle, buf, 2) != 0) return -1;
    gpioDelay(10000);
    return 0;
}

int ads1115_read(int handle, int16_t *value) {
    char reg = ADS1115_REG_CONVERSION;
    if (i2cWriteDevice(handle, &reg, 1) != 0) return -1;
    char data[2];
    if (i2cReadDevice(handle, data, 2) != 2) return -1;
    *value = (data[0] << 8) | data[1];
    return 0;
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    int i2c_handle = i2cOpen(1, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (ads1115_init(i2c_handle) != 0) {
        fprintf(stderr, "ADS1115 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    MQTTClient_connectOptions conn_opts = MQTTClient_connectOptions_initializer;
    conn_opts.keepAliveInterval = 20;
    conn_opts.cleansession = 1;

    if (MQTTClient_create(&client, MQTT_HOST, "rpi_sensor",
                          MQTTCLIENT_PERSISTENCE_NONE) != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to create MQTT client\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (MQTTClient_connect(client, &conn_opts) != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to connect to MQTT broker\n");
        MQTTClient_destroy(&client);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("Connected to MQTT broker. Publishing ADS1115 readings...\n");

    for (int i = 0; i < 10 && running; i++) {
        int16_t raw;
        if (ads1115_read(i2c_handle, &raw) == 0) {
            char payload[20];
            snprintf(payload, sizeof(payload), "%d", raw);
            MQTTClient_message pubmsg = MQTTClient_message_initializer;
            pubmsg.payload = payload;
            pubmsg.payloadlen = strlen(payload);
            pubmsg.qos = 1;
            pubmsg.retained = 0;

            MQTTClient_deliveryToken token;
            if (MQTTClient_publishMessage(client, MQTT_TOPIC, &pubmsg, &token) != MQTTCLIENT_SUCCESS) {
                fprintf(stderr, "Failed to publish message\n");
            } else {
                printf("Published: %s\n", payload);
            }
        } else {
            fprintf(stderr, "Failed to read ADS1115 value\n");
        }
        sleep(1);
    }

    MQTTClient_disconnect(client, 1000);
    MQTTClient_destroy(&client);
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define GPIO_17 17
#define GPIO_18 18
#define CHIP_NAME "gpiochip4"
#define POLL_INTERVAL_US 50000

static volatile sig_atomic_t keep_running = 1;

static void handle_signal(int sig)
{
    (void)sig;
    keep_running = 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line17 = NULL;
    struct gpiod_line *line18 = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Get the lines */
    line17 = gpiod_chip_get_line(chip, GPIO_17);
    if (!line17) {
        fprintf(stderr, "Failed to get line %d: %s\n", GPIO_17, strerror(errno));
        goto cleanup;
    }
    line18 = gpiod_chip_get_line(chip, GPIO_18);
    if (!line18) {
        fprintf(stderr, "Failed to get line %d: %s\n", GPIO_18, strerror(errno));
        goto cleanup;
    }

    /* Request both lines as outputs, initially low */
    if (gpiod_line_request_output(line17, "digital-out", 0) < 0) {
        fprintf(stderr, "Failed to request line %d as output: %s\n",
                GPIO_17, strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_output(line18, "digital-out", 0) < 0) {
        fprintf(stderr, "Failed to request line %d as output: %s\n",
                GPIO_18, strerror(errno));
        goto cleanup;
    }

    printf("Digital output control started. Press Ctrl+C to exit.\n");

    while (keep_running) {
        if (gpiod_line_set_value(line17, 1) < 0) {
            fprintf(stderr, "Failed to set line %d high: %s\n",
                    GPIO_17, strerror(errno));
            break;
        }
        if (gpiod_line_set_value(line18, 0) < 0) {
            fprintf(stderr, "Failed to set line %d low: %s\n",
                    GPIO_18, strerror(errno));
            break;
        }
        printf("GPIO %d=1, GPIO %d=0\n", GPIO_17, GPIO_18);
        fflush(stdout);

        usleep(POLL_INTERVAL_US);

        if (gpiod_line_set_value(line17, 0) < 0) {
            fprintf(stderr, "Failed to set line %d low: %s\n",
                    GPIO_17, strerror(errno));
            break;
        }
        if (gpiod_line_set_value(line18, 1) < 0) {
            fprintf(stderr, "Failed to set line %d high: %s\n",
                    GPIO_18, strerror(errno));
            break;
        }
        printf("GPIO %d=0, GPIO %d=1\n", GPIO_17, GPIO_18);
        fflush(stdout);

        usleep(POLL_INTERVAL_US);
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Ensure lines are left in a safe state before release */
    if (line17) {
        gpiod_line_set_value(line17, 0);
        gpiod_line_release(line17);
    }
    if (line18) {
        gpiod_line_set_value(line18, 0);
        gpiod_line_release(line18);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    if (ret == EXIT_SUCCESS) {
        printf("\nExiting cleanly.\n");
    }
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_LINE 17
#define POLL_INTERVAL_SEC 5

static volatile sig_atomic_t keep_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    /* Get the line for GPIO 17 */
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request the line as output, initial value LOW (0) */
    ret = gpiod_line_request_output(line, "digital-output", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("Digital output control started on GPIO %d. Press Ctrl+C to exit.\n", GPIO_LINE);

    while (keep_running) {
        /* Toggle the output state */
        static int state = 0;
        state = !state;

        ret = gpiod_line_set_value(line, state);
        if (ret < 0) {
            perror("gpiod_line_set_value");
            break;
        }

        printf("GPIO %d set to %d\n", GPIO_LINE, state);
        fflush(stdout);

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < POLL_INTERVAL_SEC && keep_running; i++) {
            sleep(1);
        }
    }

    /* Clean up: release line and close chip */
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_17 17
#define GPIO_23 23

static volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line17 = NULL;
    struct gpiod_line *line23 = NULL;
    int ret = EXIT_FAILURE;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open gpiochip0");
        return EXIT_FAILURE;
    }

    line17 = gpiod_chip_get_line(chip, GPIO_17);
    if (!line17) {
        perror("Failed to get GPIO 17");
        goto cleanup;
    }

    line23 = gpiod_chip_get_line(chip, GPIO_23);
    if (!line23) {
        perror("Failed to get GPIO 23");
        goto cleanup;
    }

    if (gpiod_line_request_output(line17, "digital_out", 0) < 0) {
        perror("Failed to request GPIO 17 as output");
