#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <termios.h>
#include <signal.h>

#define SERIAL_PORT "/dev/ttyS0"
#define BAUD_RATE B9600

static volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int setup_serial(const char *port, speed_t baud_rate) {
    int fd = open(port, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd == -1) {
        perror("Error opening serial port");
        return -1;
    }

    struct termios tty;
    memset(&tty, 0, sizeof(tty));
    if (tcgetattr(fd, &tty) != 0) {
        perror("Error getting termios attributes");
        close(fd);
        return -1;
    }

    cfsetospeed(&tty, baud_rate);
    cfsetispeed(&tty, baud_rate);

    tty.c_cflag &= ~PARENB;   // No parity
    tty.c_cflag &= ~CSTOPB;   // 1 stop bit
    tty.c_cflag &= ~CSIZE;
    tty.c_cflag |= CS8;       // 8 data bits
    tty.c_cflag &= ~CRTSCTS;  // No hardware flow control
    tty.c_cflag |= CREAD | CLOCAL;

    tty.c_lflag &= ~(ICANON | ECHO | ECHOE | ISIG); // Non-canonical mode
    tty.c_iflag &= ~(IXON | IXOFF | IXANY);         // No software flow control
    tty.c_oflag &= ~OPOST;                           // Raw output

    tty.c_cc[VMIN] = 0;      // Non-blocking read
    tty.c_cc[VTIME] = 5;     // 0.5 second timeout

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        close(fd);
        return -1;
    }

    return fd;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Error registering signal handler");
        return EXIT_FAILURE;
    }

    int fd = setup_serial(SERIAL_PORT, BAUD_RATE);
    if (fd == -1) {
        return EXIT_FAILURE;
    }

    printf("Serial communication started on %s at 9600 baud.\n", SERIAL_PORT);
    printf("Press Ctrl+C to exit.\n");

    while (keep_running) {
        unsigned char buffer[256];
        ssize_t bytes_read = read(fd, buffer, sizeof(buffer));

        if (bytes_read > 0) {
            printf("Received: ");
            for (ssize_t i = 0; i < bytes_read; i++) {
                putchar(buffer[i]);
            }
            putchar('\n');
            fflush(stdout);
        } else if (bytes_read == -1 && errno != EAGAIN && errno != EWOULDBLOCK) {
            perror("Error reading from serial port");
            break;
        }
    }

    close(fd);
    printf("\nSerial communication stopped.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define MPU6050_ADDR 0x68
#define PWR_MGMT_1   0x6B
#define ACCEL_XOUT_H 0x3B

static volatile sig_atomic_t running = 1;

static void sighandler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening /dev/i2c-1: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n",
                MPU6050_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    /* Wake up the MPU6050 by clearing SLEEP bit in PWR_MGMT_1 */
    uint8_t buf[2] = {PWR_MGMT_1, 0x00};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing PWR_MGMT_1: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }
    usleep(100000); /* allow oscillator to stabilize */

    while (running) {
        uint8_t reg = ACCEL_XOUT_H;
        if (write(fd, &reg, 1) != 1) {
            fprintf(stderr, "Error selecting register 0x%02X: %s\n",
                    ACCEL_XOUT_H, strerror(errno));
            break;
        }

        uint8_t data[6];
        ssize_t n = read(fd, data, 6);
        if (n != 6) {
            fprintf(stderr, "Error reading accel data (got %zd bytes): %s\n",
                    n, n < 0 ? strerror(errno) : "short read");
            break;
        }

        int16_t raw_x = (int16_t)((data[0] << 8) | data[1]);
        int16_t raw_y = (int16_t)((data[2] << 8) | data[3]);
        int16_t raw_z = (int16_t)((data[4] << 8) | data[5]);

        printf("Accel X: %d, Y: %d, Z: %d\n", raw_x, raw_y, raw_z);
        fflush(stdout);

        usleep(100000);
    }

    close(fd);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define BMP280_I2C_ADDR 0x76

/* BMP280 registers */
#define BMP280_REG_TEMP_MSB   0xFA
#define BMP280_REG_PRESS_MSB  0xF7
#define BMP280_REG_CONFIG     0xF5
#define BMP280_REG_CTRL_MEAS  0xF4
#define BMP280_REG_ID         0xD0

#define BMP280_CHIP_ID        0x58

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo) {
    (void)signo;
    g_running = 0;
}

static int i2c_write_reg(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read burst from 0x%02X failed: got %zd of %zu (%s)\n",
                reg, n, len, strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    const char *dev_path = "/dev/i2c-1";
    int fd = open(dev_path, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", dev_path, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, BMP280_I2C_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                BMP280_I2C_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    /* Verify chip ID */
    uint8_t id = 0;
    if (i2c_read_burst(fd, BMP280_REG_ID, &id, 1) < 0) {
        close(fd);
        return EXIT_FAILURE;
    }
    if (id != BMP280_CHIP_ID) {
        fprintf(stderr, "Chip ID mismatch: got 0x%02X, expected 0x%02X\n",
                id, BMP280_CHIP_ID);
        close(fd);
        return EXIT_FAILURE;
    }

    /* Config: t_sb=500ms(0b010), filter=off(0b000), spi3w_en=0 */
    if (i2c_write_reg(fd, BMP280_REG_CONFIG, 0x00) < 0) {
        close(fd);
        return EXIT_FAILURE;
    }

    /* Ctrl_meas: osrs_t=x1(0b001), osrs_p=x1(0b001), mode=normal(0b11) -> 0x27 */
    if (i2c_write_reg(fd, BMP280_REG_CTRL_MEAS, 0x27) < 0) {
        close(fd);
        return EXIT_FAILURE;
    }

    while (g_running) {
        uint8_t d[3];
        if (i2c_read_burst(fd, BMP280_REG_PRESS_MSB, d, 3) < 0) {
            break;
        }
        int32_t raw_p = ((int32_t)d[0] << 12) | ((int32_t)d[1] << 4) | (d[2] >> 4);
        int32_t raw_t = ((int32_t)d[2] << 12) | ((int32_t)d[1] << 4) | (d[0] >> 4);

        /* Datasheet conversion formulas (x1 power-of-two oversampling) */
        double temp_c = (double)raw_t / 16384.0 - 42.5;
        double pres_pa = (double)raw_p / 16384.0 * 51200.0;

        printf("Temperature: %.2f C, Pressure: %.2f Pa\n", temp_c, pres_pa);
        fflush(stdout);

        /* Sleep 5 s in 100 ms slices so SIGINT is noticed promptly */
        for (int i = 0; i < 50 && g_running; i++) {
            usleep(100000);
        }
    }

    if (close(fd) < 0) {
        perror("close");
        return EXIT_FAILURE;
    }
    return EXIT_SUCCESS;
}

