#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <time.h>
#include <sys/time.h>

#include <MQTTClient.h>

#define MAX_PAYLOAD 1024

static volatile sig_atomic_t running = 1;

static void signal_handler(int signum) {
    (void)signum;
    running = 0;
}

static int get_timestamp(char *buf, size_t len) {
    struct timeval tv;
    if (gettimeofday(&tv, NULL) != 0) return -1;
    struct tm tm_info;
    if (localtime_r(&tv.tv_sec, &tm_info) == NULL) return -1;
    if (strftime(buf, len, "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) return -1;
    return 0;
}

int main(void) {
    char timestamp[MAX_PAYLOAD];
    char payload[MAX_PAYLOAD];

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Failed to register signal handler");
        return EXIT_FAILURE;
    }

    MQTTClient client;
    MQTTClient_connectOptions conn_opts = MQTTClient_connectOptions_initializer;
    int rc;

    if (MQTTClient_create(&client, "tcp://localhost:1883", "sensor_node", MQTTCLIENT_PERSISTENCE_NONE, NULL) != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to create MQTT client\n");
        return EXIT_FAILURE;
    }

    conn_opts.keepAliveInterval = 60;
    conn_opts.cleansession = 1;

    if ((rc = MQTTClient_connect(client, &conn_opts)) != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to connect to MQTT broker: %s\n", MQTTClient_strerror(rc));
        MQTTClient_destroy(&client);
        return EXIT_FAILURE;
    }

    if (get_timestamp(timestamp, sizeof(timestamp)) != 0) {
        fprintf(stderr, "Failed to generate timestamp\n");
        MQTTClient_disconnect(client, 1000);
        MQTTClient_destroy(&client);
        return EXIT_FAILURE;
    }

    snprintf(payload, sizeof(payload), "{\"timestamp\": \"%s\", \"sensor_data\": \"12345\"}", timestamp);

    if ((rc = MQTTClient_publish(client, "sensor/data", strlen(payload), payload, 0, 1)) != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to publish message: %s\n", MQTTClient_strerror(rc));
    } else {
        printf("Published: %s\n", payload);
    }

    MQTTClient_disconnect(client, 1000);
    MQTTClient_destroy(&client);

    return EXIT_SUCCESS;
}

