#define PWM_PIN_3 18
#define PWM_PIN_4 23
#define PWM_PIN_5 24

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed (device may be absent).\n");
        return EXIT_FAILURE;
    }

    int pins[] = {PWM_PIN_1, PWM_PIN_2, PWM_PIN_3, PWM_PIN_4, PWM_PIN_5};
    const char *names[] = {"GPIO 2", "GPIO 3", "GPIO 18", "GPIO 23", "GPIO 24"};
    const int values[] = {128, 64, 32, 16, 8};

    printf("Configuring PWM outputs on BCM GPIO pins:\n");
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); ++i) {
