int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to install signal handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, DHT_PIN);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", DHT_PIN, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input(line, "dht22") < 0) {
        fprintf(stderr, "Failed to request input on GPIO %d: %s\n", DHT_PIN, strerror(errno));
        goto cleanup;
    }

    int data[5] = {0, 0, 0, 0, 0};
    int laststate = 1;
    int counter = 0;
    int j = 0;

    // Send start signal
    if (gpiod_line_set_value(line, 0) < 0) {
        fprintf(stderr, "Failed to set line low: %s\n", strerror(errno));
        goto cleanup;
    }
    usleep(20000); // 20ms low
    if (gpiod_line_set_value(line, 1) < 0) {
        fprintf(stderr, "Failed to set line high: %s\n", strerror(errno));
        goto cleanup;
    }
    usleep(30);   // 30us high

    // Switch to input and wait for response
    if (gpiod_line_request_input(line, "dht22") < 0) {
        fprintf(stderr, "Failed to switch to input: %s\n", strerror(errno));
        goto cleanup;
    }

    // Wait for sensor to pull low (response)
    int timeout = 0;
    while (gpiod_line_get_value(line) == 1 && timeout < 100) {
        usleep(1);
        timeout++;
    }
    if (timeout >= 100) {
        fprintf(stderr, "DHT22 not responding (no ACK)\n");
        goto cleanup;
    }

    // Read 40 bits
    for (int i = 0; i < MAX_TIMINGS && running; i++) {
        counter = 0;
        while (gpiod_line_get_value(line) == laststate && counter < 255 && running) {
            usleep(1);
            counter++;
            if (counter > 100) break;
        }
        laststate = gpiod_line_get_value(line);

        if (counter == 0) break;

        if ((i >= 4) && (i % 2 == 0)) {
            data[j / 8] <<= 1;
            if (counter > 16) data[j / 8] |= 1;
            j++;
        }
    }

    if (j < 40) {
        fprintf(stderr, "DHT22 read incomplete (%d bits)\n", j);
        goto cleanup;
    }

    // Verify checksum
    if (((data[0] + data[1] + data[2] + data[3]) & 0xFF) != data[4]) {
        fprintf(stderr, "DHT22 checksum error\n");
        goto cleanup;
    }

    float temperature = (float)((data[2] << 8) | data[3]) / 10.0;
    float humidity = (float)((data[0] << 8) | data[1]) / 10.0;

    printf("Temperature: %.1f C, Humidity: %.1f %%\n", temperature, humidity);
    ret = EXIT_SUCCESS;

cleanup:
    if (line) gpiod_line_release(line);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

