#include <gpiod.h>

#define CONSUMER "gpio-switch"
#define NUM_PINS 4

static const unsigned int pins[NUM_PINS] = {17, 23, 24, 25};

static volatile sig_atomic_t running = 1;

static void sighandler(int signo)
{
    (void)signo;
    running = 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_PINS];
    int vals[NUM_PINS];
    int rc = EXIT_FAILURE;

    memset(lines, 0, sizeof(lines));

    for (int i = 0; i < NUM_PINS; i++)
        vals[i] = -1;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_PINS; i++) {
        lines[i] = gpiod_chip_get_line(chip, pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get line %u: %s\n", pins[i], strerror(errno));
            goto cleanup;
        }
        if (gpiod_line_request_output(lines[i], CONSUMER, 0) < 0) {
            fprintf(stderr, "Failed to request line %u as output: %s\n", pins[i], strerror(errno));
            goto cleanup;
        }
    }

    while (running) {
        for (int i = 0; i < NUM_PINS; i++) {
            if (vals[i] != -1) {
                if (gpiod_line_set_value(lines[i], vals[i]) < 0) {
                    fprintf(stderr, "Failed to set line %u: %s\n", pins[i], strerror(errno));
                    goto cleanup;
                }
                printf("GPIO %u: %s\n", pins[i], vals[i] ? "ON" : "OFF");
            }
        }
        fflush(stdout);
        sleep(10);
    }

    rc = EXIT_SUCCESS;

cleanup:
    for (int i = 0; i < NUM_PINS; i++) {
        if (lines[i])
            gpiod_line_release(lines[i]);
    }
    if (chip)
        gpiod_chip_close(chip);

    return rc;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <MQTTClient.h>

#define MQTT_HOST "localhost"
#define MQTT_PORT 1883
#define MQTT_TOPIC "sensor/mcp3008"
#define NUM_CHANNELS 8

static volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid channel %d\n", channel);
        return -1;
    }
    int adc_value = 0;
    char buffer[3];
    buffer[0] = 0x01;
    buffer[1] = (0x08 | channel) << 4;
    buffer[2] = 0x00;
    if (gpioWrite(0, 1) != 0) {
        fprintf(stderr, "Failed to set CS high\n");
        return -1;
    }
    gpioDelay(1000);
    int bytes = serRead(0, buffer, 3);
    if (bytes != 3) {
        fprintf(stderr, "Failed to read from SPI: expected 3 bytes, got %d\n", bytes);
        gpioWrite(0, 0);
        return -1;
    }
    if (gpioWrite(0, 0) != 0) {
        fprintf(stderr, "Failed to set CS low\n");
        return -1;
    }
    adc_value = ((buffer[1] & 0x03) << 8) + buffer[2];
    return adc_value;
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    int channels[NUM_CHANNELS] = {0, 1, 2, 3, 4, 5, 6, 7};
    MQTTClient client;
    MQTTClient_connectOptions conn_opts = MQTTClient_connectOptions_initializer;
    MQTTClient_message pubmsg = MQTTClient_message_initializer;
    MQTTClient_deliveryToken token;

    MQTTClient_create(&client, MQTT_HOST, "rpi_sensor", MQTTCLIENT_PERSISTENCE_NONE);
    conn_opts.keepAliveInterval = 20;
    conn_opts.cleansession = 1;

    int rc = MQTTClient_connect(client, &conn_opts);
    if (rc != MQTTCLIENT_SUCCESS) {
        fprintf(stderr, "Failed to connect, return code %d\n", rc);
        MQTTClient_destroy(&client);
        gpioTerminate();
        return 1;
    }

    for (int i = 0; i < NUM_CHANNELS && running; i++) {
        int value = read_mcp3008(channels[i]);
        if (value >= 0) {
            char payload[20];
            snprintf(payload, sizeof(payload), "%d", value);
            pubmsg.payload = payload;
            pubmsg.payloadlen = strlen(payload);
            pubmsg.qos = 1;
            pubmsg.retained = 0;
            MQTTClient_publishMessage(client, MQTT_TOPIC, &pubmsg, &token);
            printf("Published channel %d: %s\n", channels[i], payload);
        } else {
            fprintf(stderr, "Error reading channel %d\n", channels[i]);
        }
        sleep(1);
    }

    MQTTClient_disconnect(client, 1000);
    MQTTClient_destroy(&client);
    gpioTerminate();
    return 0;
}

#include <stdio.h>
