#include <linux/videodev2.h>

#define DEVICE_NAME "/dev/video0"
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define OUTPUT_FILE "captured_image.jpg"

static int xioctl(int fd, unsigned long request, void *arg)
{
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (-1 == r && EINTR == errno);
    return r;
}

int main(void)
{
    int fd = -1;
    FILE *fp = NULL;
    unsigned char *buffer = NULL;
    size_t buffer_size = 0;

    /* Open the video device */
    fd = open(DEVICE_NAME, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", DEVICE_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Set format: YUYV 640x480 */
    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (xioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        fprintf(stderr, "Error setting format: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    /* Set capture mode to streaming */
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        fprintf(stderr, "Error starting stream: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    /* Allocate memory for the captured image */
    buffer_size = IMAGE_WIDTH * IMAGE_HEIGHT * 2; /* YUYV: 2 bytes per pixel */
    buffer = malloc(buffer_size);
    if (!buffer) {
        fprintf(stderr, "Memory allocation failed: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    /* Read the captured image */
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (xioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
        fprintf(stderr, "Error querying buffer: %s\n", strerror(errno));
        free(buffer);
        close(fd);
        return EXIT_FAILURE;
    }

    void *mapped = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
    if (MAP_FAILED == mapped) {
        fprintf(stderr, "Error mapping buffer: %s\n", strerror(errno));
        free(buffer);
        close(fd);
        return EXIT_FAILURE;
    }

    /* Copy the mapped buffer into our own buffer */
    memcpy(buffer, mapped, buffer_size);

    /* Unmap the buffer */
    if (munmap(mapped, buf.length) < 0) {
        fprintf(stderr, "Error unmapping buffer: %s\n", strerror(errno));
        free(buffer);
        close(fd);
        return EXIT_FAILURE;
    }

    /* Close the stream */
    if (xioctl(fd, VIDIOC_STREAMOFF, &type) < 0) {
        fprintf(stderr, "Error stopping stream: %s\n", strerror(errno));
        free(buffer);
        close(fd);
        return EXIT_FAILURE;
    }

    /* Open the output file */
    fp = fopen(OUTPUT_FILE, "wb");
    if (!fp) {
        fprintf(stderr, "Error opening output file: %s\n", strerror(errno));
        free(buffer);
        close(fd);
        return EXIT_FAILURE;
    }

    /* Write the image data to the file */
    if (fwrite(buffer, 1, buffer_size, fp) != buffer_size) {
        fprintf(stderr, "Error writing image data: %s\n", strerror(errno));
        fclose(fp);
        free(buffer);
        close(fd);
        return EXIT_FAILURE;
    }

    /* Clean up */
    fclose(fp);
    free(buffer);
    close(fd);

    printf("Image saved to %s\n", OUTPUT_FILE);
    return EXIT_SUCCESS;
}

