#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    18
#define CHIP_NAME   "gpiochip0"

static volatile sig_atomic_t running = 1;

static void sighandler(int signo) {
    (void)signo;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig = NULL;
    struct gpiod_line *echo = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    trig = gpiod_chip_get_line(chip, TRIGGER_PIN);
    if (!trig) {
        fprintf(stderr, "Failed to get trigger line %d: %s\n", TRIGGER_PIN, strerror(errno));
        goto cleanup;
    }

    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!echo) {
        fprintf(stderr, "Failed to get echo line %d: %s\n", ECHO_PIN, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(trig, "hc-sr04-trig", 0) < 0) {
        fprintf(stderr, "Failed to request trigger as output: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input(echo, "hc-sr04-echo") < 0) {
        fprintf(stderr, "Failed to request echo as input: %s\n", strerror(errno));
        goto cleanup;
    }

    while (running) {
        /* Ensure trigger starts low */
        if (gpiod_line_set_value(trig, 0) < 0) {
            fprintf(stderr, "Failed to set trigger low: %s\n", strerror(errno));
            break;
        }
        usleep(2);

        /* Send 10 us pulse */
        if (gpiod_line_set_value(trig, 1) < 0) {
            fprintf(stderr, "Failed to set trigger high: %s\n", strerror(errno));
            break;
        }
        usleep(10);
        if (gpiod_line_set_value(trig, 0) < 0) {
            fprintf(stderr, "Failed to set trigger low: %s\n", strerror(errno));
            break;
        }

        /* Wait for echo rising edge (timeout ~50 ms) */
        int timeout = 0;
        while (gpiod_line_get_value(echo) == 0 && timeout < 50) {
            usleep(1);
            timeout++;
        }
        if (timeout >= 50) {
            fprintf(stderr, "Timeout waiting for echo start\n");
            break;
        }

        /* Measure echo duration (rising to falling) */
        long start_tick = 0;
        long end_tick = 0;
        int level;
        int val;
        int elapsed = 0;

        do {
            val = gpiod_line_get_value(echo);
            if (val < 0) {
                fprintf(stderr, "Error reading echo: %s\n", strerror(errno));
                goto cleanup;
            }
            if (val == 1) {
                start_tick = gpiod_line_get_value(echo);
            } else {
                end_tick = gpiod_line_get_value(echo);
            }
            usleep(1);
            elapsed++;
        } while (elapsed < 100 && running);

        if (start_tick == 0 || end_tick == 0) {
            fprintf(stderr, "Echo pulse too short or interrupted\n");
            break;
        }

        long diff = end_tick - start_tick;
        if (diff < 0) diff = -diff;

        /* Speed of sound = 343 m/s => 1 m = 58 us; diff in microseconds */
        float distance = (float)diff / 58.0f;

        printf("Distance: %.2f cm\n", distance);
        fflush(stdout);

        sleep(1);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (trig) gpiod_line_release(trig);
    if (echo) gpiod_line_release(echo);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PWM_PIN_1 8
#define PWM_PIN_2 9
#define PWM_PIN_3 11
#define PWM_PIN_4 18

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install signal handler\n");
    }

    int pins[] = {PWM_PIN_1, PWM_PIN_2, PWM_PIN_3, PWM_PIN_4};
    const int num_pins = (int)(sizeof(pins) / sizeof(pins[0]));

    while (running) {
        for (int i = 0; i < num_pins; i++) {
            if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
                fprintf(stderr, "Error: gpioSetMode failed for pin %d\n", pins[i]);
                gpioTerminate();
                return EXIT_FAILURE;
            }
            if (gpioPWM(pins[i], 128) != 0) {
                fprintf(stderr, "Error: gpioPWM failed for pin %d\n", pins[i]);
                gpioTerminate();
                return EXIT_FAILURE;
            }
        }
        printf("PWM ON\n");
        fflush(stdout);

        sleep(1);

        for (int i = 0; i < num_pins; i++) {
            if (gpioPWM(pins[i], 0) != 0) {
                fprintf(stderr, "Error: gpioPWM off failed for pin %d\n", pins[i]);
                gpioTerminate();
                return EXIT_FAILURE;
            }
        }
        printf("PWM OFF\n");
        fflush(stdout);

        sleep(1);
    }

    for (int i = 0; i < num_pins; i++) {
        gpioPWM(pins[i], 0);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/videodev2.h>

#define DEVICE_NAME "/dev/video0"
#define CAPTURE_INTERVAL_MS 100

static volatile sig_atomic_t keep_running = 1;

static void signal_handler(int signum) {
    (void)signum;
    keep_running = 0;
}

static int xioctl(int fd, unsigned long request, void *arg) {
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    int fd = open(DEVICE_NAME, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", DEVICE_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        fprintf(stderr, "VIDIOC_STREAMON failed: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    while (keep_running) {
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;

        if (xioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
            if (errno == EAGAIN) {
                continue;
            }
            fprintf(stderr, "VIDIOC_DQBUF failed: %s\n", strerror(errno));
            break;
        }

        char filename[32];
        snprintf(filename, sizeof(filename), "image_%ld.jpg", (long)buf.index);

        FILE *fp = fopen(filename, "wb");
        if (!fp) {
            fprintf(stderr, "Error opening file %s: %s\n", filename, strerror(errno));
            xioctl(fd, VIDIOC_QBUF, &buf);
            usleep(CAPTURE_INTERVAL_MS * 1000);
            continue;
        }

        size_t total = 0;
        while (total < buf.bytesused) {
            size_t n = fwrite(buf.m.userptr + total, 1, buf.bytesused - total, fp);
            if (n == 0) {
                fprintf(stderr, "Error writing to file: %s\n", strerror(errno));
                fclose(fp);
                xioctl(fd, VIDIOC_QBUF, &buf);
                goto next_iteration;
            }
            total += n;
        }

        if (fclose(fp) != 0) {
            fprintf(stderr, "Error closing file: %s\n", strerror(errno));
        }

        if (xioctl(fd, VIDIOC_QBUF, &buf) < 0) {
            fprintf(stderr, "VIDIOC_QBUF failed: %s\n", strerror(errno));
        }

    next_iteration:
        usleep(CAPTURE_INTERVAL_MS * 1000);
    }

    if (xioctl(fd, VIDIOC_STREAMOFF, &type) < 0) {
        fprintf(stderr, "VIDIOC_STREAMOFF failed: %s\n", strerror(errno));
    }

    close(fd);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PWM_PIN 18
#define PWM_RANGE 255

static volatile sig_atomic_t running = 1;

static void signal_handler(int signum) {
    (void)signum;
    running = 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PWM_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(PWM_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range on GPIO %d\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        int duty_cycle = rand() % (PWM_RANGE + 1);
        if (gpioPWM(PWM_PIN, duty_cycle) != 0) {
            fprintf(stderr, "Failed to set PWM duty cycle to %d\n", duty_cycle);
            break;
        }
        printf("PWM duty cycle: %d/%d\n", duty_cycle, PWM_RANGE);
        fflush(stdout);

        for (int i = 0; i < 5 && running; i++) {
            sleep(1);
        }
    }

    gpioPWM(PWM_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define PCF8574_ADDR   0x3F

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo) {
    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

int main(void) {
    int fd = -1;
    int rc = EXIT_FAILURE;

    if (install_signal_handlers() != 0) {
        goto cleanup;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", I2C_BUS, strerror(errno));
        goto cleanup;
    }

    if (ioctl(fd, I2C_SLAVE, PCF8574_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n",
                PCF8574_ADDR, strerror(errno));
        goto cleanup;
    }

    /* PCF8574 is 8-bit; bit 0 = R/W, bits 1-7 = data */
    uint8_t data = 0x01;  /* LED on */

    while (g_running) {
        if (write(fd, &data, 1) != 1) {
            fprintf(stderr, "Error writing to PCF8574: %s\n", strerror(errno));
            break;
        }
        usleep(100000);  /* 100 ms */
    }

    rc = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) {
        close(fd);
    }
    return rc;
}

#include <stdio.h>
