#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PWM_PIN_1 18
#define PWM_PIN_2 23
#define PWM_PIN_3 24

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed (device may be absent).\n");
        return EXIT_FAILURE;
    }

    int pins[] = {PWM_PIN_1, PWM_PIN_2, PWM_PIN_3};
    const int num_pins = (int)(sizeof(pins) / sizeof(pins[0]));

    for (int i = 0; i < num_pins; i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: gpioSetMode failed for pin %d.\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetPWMfrequency(pins[i], 1000) != 0) {
            fprintf(stderr, "Warning: gpioSetPWMfrequency failed for pin %d.\n", pins[i]);
        }
        if (gpioSetPWMrange(pins[i], 100) != 0) {
            fprintf(stderr, "Warning: gpioSetPWMrange failed for pin %d.\n", pins[i]);
        }
    }

    while (running) {
        printf("PWM State:\n");
        for (int i = 0; i < num_pins; i++) {
            int duty = (i * 10) % 100;
            if (gpioPWM(pins[i], duty) != 0) {
                fprintf(stderr, "Error: gpioPWM failed for pin %d.\n", pins[i]);
                break;
            }
            printf("  Pin %d: %d%%\n", pins[i], duty);
        }
        fflush(stdout);
        time_sleep(0.1);
    }

    for (int i = 0; i < num_pins; i++) {
        gpioPWM(pins[i], 0);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    18

static volatile sig_atomic_t running = 1;

static void sighandler(int sig)
{
    (void)sig;
    running = 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig = NULL;
    struct gpiod_line *echo = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    trig = gpiod_chip_get_line(chip, TRIGGER_PIN);
    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!trig || !echo) {
        fprintf(stderr, "Failed to get GPIO lines: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(trig, "hc-sr04-trig", 0) < 0) {
        fprintf(stderr, "Failed to request trigger line as output: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input(echo, "hc-sr04-echo") < 0) {
        fprintf(stderr, "Failed to request echo line as input: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Ensure trigger starts low */
    if (gpiod_line_set_value(trig, 0) < 0) {
        fprintf(stderr, "Failed to set trigger low: %s\n", strerror(errno));
        goto cleanup;
    }
    usleep(2);

    printf("HC-SR04 ranging started...\n");

    while (running) {
        /* Send 10us trigger pulse */
        if (gpiod_line_set_value(trig, 1) < 0) {
            fprintf(stderr, "Trigger high failed: %s\n", strerror(errno));
            break;
        }
        usleep(10);
        if (gpiod_line_set_value(trig, 0) < 0) {
            fprintf(stderr, "Trigger low failed: %s\n", strerror(errno));
            break;
        }

        /* Wait for echo rising edge */
        int val = gpiod_line_get_value(echo);
        if (val < 0) {
            fprintf(stderr, "Echo read failed: %s\n", strerror(errno));
            break;
        }
        unsigned long start_tick = 0;
        while (val == 0 && running) {
            val = gpiod_line_get_value(echo);
            if (val < 0) {
                fprintf(stderr, "Echo read failed: %s\n", strerror(errno));
                break;
            }
            if (start_tick == 0) start_tick = gpiod_line_get_value(echo);
            usleep(1);
        }
        if (!running) break;
        if (val != 0) continue;

        /* Measure echo duration */
        unsigned long end_tick = 0;
        while (val == 1 && running) {
            val = gpiod_line_get_value(echo);
            if (val < 0) {
                fprintf(stderr, "Echo read failed: %s\n", strerror(errno));
                break;
            }
            if (end_tick == 0) end_tick = gpiod_line_get_value(echo);
            usleep(1);
        }
        if (!running) break;
        if (val != 1) continue;

        unsigned long elapsed = end_tick - start_tick;
        if (elapsed == 0) {
            fprintf(stderr, "Timeout waiting for echo\n");
            continue;
        }

        /* Distance = (time_us / 1000000) * 34300 cm/s */
        double distance = (double)elapsed / 1000000.0 * 34300.0;
        printf("Distance: %.2f cm\n", distance);

        /* Wait for echo to go low before next measurement */
        val = gpiod_line_get_value(echo);
        while (val == 1 && running) {
            val = gpiod_line_get_value(echo);
            usleep(1);
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (trig) gpiod_line_release(trig);
    if (echo) gpiod_line_release(echo);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_LINE_OFFSET 23
#define POLL_INTERVAL_SEC 5

static volatile sig_atomic_t keep_running = 1;

static void signal_handler(int signum)
{
    (void)signum;
    keep_running = 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Get the line for BCM GPIO 23 */
    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (!line) {
        fprintf(stderr, "Failed to get line %d: %s\n", GPIO_LINE_OFFSET, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request the line as output, initial value LOW (0) */
    ret = gpiod_line_request_output(line, "digital-output", 0);
    if (ret < 0) {
        fprintf(stderr, "Failed to request line %d as output: %s\n",
                GPIO_LINE_OFFSET, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("Digital output control started on GPIO %d. Press Ctrl+C to exit.\n",
           GPIO_LINE_OFFSET);

    while (keep_running) {
        /* Toggle the output state */
        static int state = 0;
        state = !state;

        ret = gpiod_line_set_value(line, state);
        if (ret < 0) {
            fprintf(stderr, "Failed to set line value: %s\n", strerror(errno));
            break;
        }

        printf("GPIO %d set to %d\n", GPIO_LINE_OFFSET, state);
        fflush(stdout);

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < POLL_INTERVAL_SEC && keep_running; i++) {
            sleep(1);
        }
    }

    /* Clean up: release the line and close the chip */
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define MPU6050_ADDR 0x68

#define PWR_MGMT_1   0x6B
#define ACCEL_XOUT_H 0x3B

static volatile sig_atomic_t running = 1;

static void sighandler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening /dev/i2c-1: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n",
                MPU6050_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    /* Wake up the MPU6050 by clearing SLEEP bit in PWR_MGMT_1 */
    uint8_t buf[2] = {PWR_MGMT_1, 0x00};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing PWR_MGMT_1: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }
    usleep(100000); /* allow oscillator to stabilize */

    while (running) {
        uint8_t reg = ACCEL_XOUT_H;
        if (write(fd, &reg, 1) != 1) {
            fprintf(stderr, "Error selecting register 0x%02X: %s\n",
                    ACCEL_XOUT_H, strerror(errno));
            break;
        }

        uint8_t data[6];
        ssize_t n = read(fd, data, 6);
        if (n != 6) {
            fprintf(stderr, "Error reading accel data (got %zd bytes): %s\n",
                    n, n < 0 ? strerror(errno) : "short read");
            break;
        }

        int16_t ax = (int16_t)((data[0] << 8) | data[1]);
        int16_t ay = (int16_t)((data[2] << 8) | data[3]);
        int16_t az = (int16_t)((data[4] << 8) | data[5]);

        printf("Accel X: %d, Y: %d, Z: %d\n", ax, ay, az);
        fflush(stdout);

        usleep(100000); /* 0.1 s */
    }

    close(fd);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define GPIO_2 2
#define GPIO_3 3
#define GPIO_17 17
#define NUM_PINS 3
#define NUM_CYCLES 3
#define CYCLE_DELAY_SEC 5

static volatile sig_atomic_t running = 1;

static void signal_handler(int signum) {
    (void)signum;
    running = 0;
}

static int apply_state(struct gpiod_line *lines[], const int states[]) {
    for (int i = 0; i < NUM_PINS; i++) {
        if (gpiod_line_set_value(lines[i], states[i]) < 0) {
            fprintf(stderr, "Failed to set GPIO %d: %s\n", i, strerror(errno));
            return -1;
        }
    }
    return 0;
}

static int read_states(struct gpiod_line *lines[], int states[]) {
    for (int i = 0; i < NUM_PINS; i++) {
        int val = gpiod_line_get_value(lines[i]);
        if (val < 0) {
            fprintf(stderr, "Failed to read GPIO %d: %s\n", i, strerror(errno));
            return -1;
        }
        states[i] = val;
    }
    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_PINS];
    int states[NUM_PINS];
    int ret = EXIT_FAILURE;

    memset(lines, 0, sizeof(lines));

    for (int i = 0; i < NUM_PINS; i++) {
        lines[i] = NULL;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        goto cleanup;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        goto cleanup;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        goto cleanup;
    }

    int pins[NUM_PINS] = {GPIO_2, GPIO_3, GPIO_17};
    for (int i = 0; i < NUM_PINS; i++) {
        lines[i] = gpiod_chip_get_line(chip, pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %d: %s\n", pins[i], strerror(errno));
            goto cleanup;
        }
        if (gpiod_line_request_output(lines[i], "digital-output", 0) < 0) {
            fprintf(stderr, "Failed to request GPIO %d as output: %s\n", pins[i], strerror(errno));
            goto cleanup;
        }
    }

    printf("Starting 3-cycle cycle with 5-second delay between cycles.\n");

    for (int cycle = 0; cycle < NUM_CYCLES && running; cycle++) {
        printf("Cycle %d/%d:\n", cycle + 1, NUM_CYCLES);

        if (apply_state(lines, (const int[]){1, 0, 1}) < 0) {
            goto cleanup;
        }
        printf("  GPIO 2=1, GPIO 3=0, GPIO 17=1\n");

        sleep(CYCLE_DELAY_SEC);

        if (!running) break;

        if (read_states(lines, states) < 0) {
            goto cleanup;
        }
        printf("  Read: GPIO 2=%d, GPIO 3=%d, GPIO 17=%d\n", states[0], states[1], states[1]);

        if (apply_state(lines, (const int[]){0, 1, 0}) < 0) {
            goto cleanup;
        }
        printf("  GPIO 2=0, GPIO 3=1, GPIO 17=0\n");

        sleep(CYCLE_DELAY_SEC);
    }

    if (running) {
        ret = EXIT_SUCCESS;
    }

cleanup:
    for (int i = 0; i < NUM_PINS; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

