#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define SHT31_ADDR        0x44
#define SHT31_MEAS_HIGHREP 0x2400
#define SHT31_MEAS_LOWREP  0x2480
#define SHT31_MEAS_MEDREP  0x2500
#define SHT31_MEAS_OSR4    0x2580

static volatile sig_atomic_t g_running = 1;

static void sighandler(int signo) {
    (void)signo;
    g_running = 0;
}

static int i2c_write16(int fd, uint16_t cmd) {
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "i2c write16 failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_n(int fd, uint8_t *buf, size_t n) {
    ssize_t r = read(fd, buf, n);
    if (r < 0 || (size_t)r != n) {
        fprintf(stderr, "i2c read_n failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int sht31_measure(int fd, float *temp, float *rh) {
    uint8_t data[6];
    int rc;

    /* High repeatability measurement */
    if (i2c_write16(fd, SHT31_MEAS_HIGHREP) < 0)
        return -1;
    usleep(15000);

    rc = i2c_read_n(fd, data, 6);
    if (rc < 0)
        return -1;

    uint16_t t_raw = ((uint16_t)data[0] << 8) | data[1];
    uint16_t rh_raw = ((uint16_t)data[3] << 8) | data[4];

    *temp = -45.0f + 175.0f * (float)t_raw / 65535.0f;
    *rh   = 100.0f * (float)rh_raw / 65535.0f;

    if (*temp < -40.0f || *temp > 125.0f || *rh < 0.0f || *rh > 100.0f) {
        fprintf(stderr, "SHT31 out-of-range: T=%.2f RH=%.2f\n", *temp, *rh);
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    const char *dev = "/dev/i2c-1";
    int fd = open(dev, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", dev, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, SHT31_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n",
                SHT31_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    while (g_running) {
        float temp, rh;
        if (sht31_measure(fd, &temp, &rh) == 0) {
            printf("Temperature: %.2f C, Relative Humidity: %.2f %%\n", temp, rh);
            fflush(stdout);
        } else {
            fprintf(stderr, "Invalid sensor reading.\n");
        }
        sleep(5);
    }

    close(fd);
    return EXIT_SUCCESS;
}

