#include <signal.h>
#include <pigpio.h>

#define PWM_PIN_1 17
#define PWM_PIN_2 18
#define PWM_PIN_3 22
#define PWM_PIN_4 27

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed (device may be absent).\n");
        return EXIT_FAILURE;
    }

    int pins[] = {PWM_PIN_1, PWM_PIN_2, PWM_PIN_3, PWM_PIN_4};
    const char *labels[] = {"GPIO 17", "GPIO 18", "GPIO 22", "GPIO 27"};

    printf("Configuring PWM outputs on %s...\n", __FILE__);
    fflush(stdout);

    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); ++i) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: gpioSetMode(%d) failed.\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetPWMfrequency(pins[i], 1000) != 0) {
            fprintf(stderr, "Warning: gpioSetPWMfrequency(%d) failed.\n", pins[i]);
        }
        if (gpioSetPWMrange(pins[i], 100) != 0) {
            fprintf(stderr, "Warning: gpioSetPWMrange(%d) failed.\n", pins[i]);
        }
        if (gpioPWM(pins[i], 50) != 0) {
            fprintf(stderr, "Error: gpioPWM(%d, 50) failed.\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        printf("  %s -> PWM duty 50%%\n", labels[i]);
    }

    printf("Done.\n");
    fflush(stdout);

    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_2_OFFSET  2
#define GPIO_3_OFFSET  3
#define POLL_INTERVAL_US 1000000

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int signum)
{
    (void)signum;
    g_running = 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line2 = NULL;
    struct gpiod_line *line3 = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Get the two lines */
    line2 = gpiod_chip_get_line(chip, GPIO_2_OFFSET);
    if (!line2) {
        fprintf(stderr, "Failed to get line %d: %s\n", GPIO_2_OFFSET, strerror(errno));
        goto cleanup;
    }

    line3 = gpiod_chip_get_line(chip, GPIO_3_OFFSET);
    if (!line3) {
        fprintf(stderr, "Failed to get line %d: %s\n", GPIO_3_OFFSET, strerror(errno));
        goto cleanup;
    }

    /* Request both lines as outputs, initial value LOW (0) */
    if (gpiod_line_request_output(line2, "digital-out", 0) < 0) {
        fprintf(stderr, "Failed to request line %d as output: %s\n",
                GPIO_2_OFFSET, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(line3, "digital-out", 0) < 0) {
        fprintf(stderr, "Failed to request line %d as output: %s\n",
                GPIO_3_OFFSET, strerror(errno));
        goto cleanup;
    }

    printf("Digital output control started. Press Ctrl+C to exit.\n");

    while (g_running) {
        /* Toggle both lines */
        if (gpiod_line_set_value(line2, 1) < 0) {
            fprintf(stderr, "Failed to set line %d high: %s\n",
                    GPIO_2_OFFSET, strerror(errno));
            break;
        }
        if (gpiod_line_set_value(line3, 1) < 0) {
            fprintf(stderr, "Failed to set line %d high: %s\n",
                    GPIO_3_OFFSET, strerror(errno));
            break;
        }
        printf("GPIO %d and %d set HIGH\n", GPIO_2_OFFSET, GPIO_3_OFFSET);
        fflush(stdout);

        usleep(POLL_INTERVAL_US);

        if (!g_running)
            break;

        if (gpiod_line_set_value(line2, 0) < 0) {
            fprintf(stderr, "Failed to set line %d low: %s\n",
                    GPIO_2_OFFSET, strerror(errno));
            break;
        }
        if (gpiod_line_set_value(line3, 0) < 0) {
            fprintf(stderr, "Failed to set line %d low: %s\n",
                    GPIO_3_OFFSET, strerror(errno));
            break;
        }
        printf("GPIO %d and %d set LOW\n", GPIO_2_OFFSET, GPIO_3_OFFSET);
        fflush(stdout);

        usleep(POLL_INTERVAL_US);
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Ensure lines are left in a safe state before releasing */
    if (line2)
        gpiod_line_release(line2);
    if (line3)
        gpiod_line_release(line3);
    if (chip)
        gpiod_chip_close(chip);

    return ret;
}

