#include <errno.h>
#include <sys/ioctl.h>
#include <linux/videodev2.h>

#define DEVICE_NAME "/dev/video0"
#define OUTPUT_FILE "captured_image.jpg"

int main(void) {
    int fd = open(DEVICE_NAME, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", DEVICE_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Set format to YUYV (YUV 4:2:2) */
    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = 640;
    fmt.fmt.pix.height = 480;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        fprintf(stderr, "Error setting format: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    /* Start streaming */
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        fprintf(stderr, "Error starting stream: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    /* Capture one frame */
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
        fprintf(stderr, "Error querying buffer: %s\n", strerror(errno));
        goto cleanup;
    }

    void *buffer_start = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
    if (buffer_start == MAP_FAILED) {
        fprintf(stderr, "Error mapping buffer: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Write captured data to file */
    FILE *fp = fopen(OUTPUT_FILE, "wb");
    if (!fp) {
        fprintf(stderr, "Error opening output file: %s\n", strerror(errno));
        munmap(buffer_start, buf.length);
        goto cleanup;
    }

    size_t bytes_written = fwrite(buffer_start, 1, buf.length, fp);
    if (bytes_written != buf.length) {
        fprintf(stderr, "Error writing to file: %s\n", strerror(errno));
        fclose(fp);
        munmap(buffer_start, buf.length);
        remove(OUTPUT_FILE);
        goto cleanup;
    }

    fclose(fp);

    printf("Image saved as %s (%zu bytes)\n", OUTPUT_FILE, bytes_written);

cleanup:
    ioctl(fd, VIDIOC_STREAMOFF, &type);
    close(fd);
    return EXIT_SUCCESS;
}

