#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define LED_PIN 18

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed (device may be absent).\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    const int num_cycles = 3;
    const int delay_us = 50000; /* 0.05 seconds */

    for (int i = 0; i < num_cycles && running; ++i) {
        /* Cycle through red, green, blue, white */
        const int colours[][3] = {
            {255, 0, 0},   /* Red   */
            {0,   255, 0}, /* Green */
            {0,   0,   255},/* Blue  */
            {255, 255, 255}/* White */
        };

        for (size_t j = 0; j < sizeof(colours) / sizeof(colours[0]) && running; ++j) {
            unsigned char r = (unsigned char)colours[j][0];
            unsigned char g = (unsigned char)colours[j][1];
            unsigned char b = (unsigned char)colours[j][2];

            if (gpioWrite(LED_PIN, 1) != 0) {
                fprintf(stderr, "Warning: gpioWrite HIGH failed on cycle %d, step %zu.\n",
                        i + 1, j);
            }
            gpioDelay(delay_us);
            if (gpioWrite(LED_PIN, 0) != 0) {
                fprintf(stderr, "Warning: gpioWrite LOW failed on cycle %d, step %zu.\n",
                        i + 1, j);
            }
            gpioDelay(delay_us);
        }
    }

    /* Ensure LED is off before releasing resources */
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

