#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>

#define W1_BASE "/sys/bus/w1/devices"
#define DS18B20_ID "28-00000xxxxxxx"  /* replace with your actual sensor ID */
#define READ_INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_temperature(const char *id, float *temp_out) {
    char path[256];
    FILE *fp;
    char line[256];
    long millideg;

    snprintf(path, sizeof(path), "%s/%s/w1_slave", W1_BASE, id);
    fp = fopen(path, "r");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", path, strerror(errno));
        return -1;
    }

    if (!fgets(line, sizeof(line), fp)) {
        fprintf(stderr, "Error reading %s: %s\n", path, strerror(errno));
        fclose(fp);
        return -1;
    }
    fclose(fp);

    if (strstr(line, "YES") == NULL) {
        fprintf(stderr, "Sensor %s not ready (no YES in output)\n", id);
        return -1;
    }

    if (sscanf(line, "t=%ld", &millideg) != 1) {
        fprintf(stderr, "Failed to parse temperature from %s\n", path);
        return -1;
    }

    *temp_out = (float)millideg / 1000.0f;
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    printf("DS18B20 Temperature Monitor (GPIO 4 via sysfs-w1)\n");
    printf("Reading every %d seconds. Press Ctrl+C to stop.\n", READ_INTERVAL_SEC);

    for (int i = 0; i < 3 && running; i++) {
        float temp;
        if (read_temperature(DS18B20_ID, &temp) == 0) {
            printf("Temperature: %.2f °C\n", temp);
        } else {
            fprintf(stderr, "Failed to read temperature after %d attempts.\n", i + 1);
            return EXIT_FAILURE;
        }
        if (i < 2 && running) {
            sleep(READ_INTERVAL_SEC);
        }
    }

    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

