#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define TRIGGER_PIN 18
#define ECHO_PIN    23
#define LED_PIN     24

static volatile sig_atomic_t running = 1;

static void sighandler(int sig)
{
    (void)sig;
    running = 0;
}

static int wait_level(struct gpiod_line *line, int val, int timeout_ms)
{
    struct timespec ts = { .tv_sec = timeout_ms / 1000,
                           .tv_nsec = (timeout_ms % 1000) * 1000000L };
    while (running) {
        int v = gpiod_line_get_value(line);
        if (v == val)
            return 0;
        if (gpiod_line_event_wait(line, &ts) <= 0)
            return -1;
        gpiod_line_event_read(line, NULL);
    }
    return -1;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig = NULL, *echo = NULL, *led = NULL;
    int rc = EXIT_FAILURE;

    struct sigaction sa = { .sa_handler = sighandler };
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    trig = gpiod_chip_get_line(chip, TRIGGER_PIN);
    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    led  = gpiod_chip_get_line(chip, LED_PIN);
    if (!trig || !echo || !led) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_output(trig, "hc-sr04-trig", 0) < 0 ||
        gpiod_line_request_input(echo, "hc-sr04-echo") < 0 ||
        gpiod_line_request_output(led, "hc-sr04-led", 0) < 0) {
        perror("gpiod_line_request");
        goto cleanup;
    }

    while (running) {
        if (gpiod_line_set_value(led, 1) < 0) {
            perror("gpiod_line_set_value(led on)");
            break;
        }
        usleep(5);

        if (gpiod_line_set_value(trig, 1) < 0) {
            perror("gpiod_line_set_value(trig high)");
            break;
        }
        usleep(10);
        if (gpiod_line_set_value(trig, 0) < 0) {
            perror("gpiod_line_set_value(trig low)");
            break;
        }

        int t = wait_level(echo, 1, 100);
        if (t < 0) {
            fprintf(stderr, "Timeout waiting for echo start\n");
            break;
        }
        if (wait_level(echo, 0, 100) < 0) {
            fprintf(stderr, "Timeout waiting for echo end\n");
            break;
        }

        long long start = 0, end = 0;
        int ok = 0;
        for (;;) {
            if (gpiod_line_event_wait(echo, &(struct timespec){0, 1000000}) <= 0)
                break;
            struct gpiod_line_event ev;
            if (gpiod_line_event_read(echo, &ev) < 0)
                break;
            if (ev.event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
                start = ev.ts.tv_sec * 1000000LL + ev.ts.tv_nsec / 1000;
                ok = 1;
                break;
            }
            if (ev.event_type == GPIOD_LINE_EVENT_FALLING_EDGE) {
                end = ev.ts.tv_sec * 1000000LL + ev.ts.tv_nsec / 1000;
                break;
            }
        }
        if (!ok) {
            fprintf(stderr, "Echo event lost\n");
            break;
        }

        long long dur = end - start;
        if (dur < 0 || dur > 1000000000LL) {
            fprintf(stderr, "Out-of-range pulse: %lld ns\n", dur);
            break;
        }
        double dist = (double)dur / 2.0 / 58.0;

        if (gpiod_line_set_value(led, 0) < 0) {
            perror("gpiod_line_set_value(led off)");
            break;
        }
        printf("Distance: %.2f cm\n", dist);
        fflush(stdout);
        usleep(100000);
    }

    rc = EXIT_SUCCESS;

cleanup:
    if (trig) gpiod_line_release(trig);
    if (echo) gpiod_line_release(echo);
    if (led)  gpiod_line_release(led);
    if (chip) gpiod_chip_close(chip);
    return rc;
}

