#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PWM_PIN_1 4
#define PWM_PIN_2 17
#define PWM_PIN_3 18

static volatile sig_atomic_t running = 1;

static void signal_handler(int signum) {
    (void)signum;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install signal handler\n");
    }

    int pins[] = {PWM_PIN_1, PWM_PIN_2, PWM_PIN_3};
    const size_t num_pins = sizeof(pins) / sizeof(pins[0]);

    while (running) {
        for (size_t i = 0; i < num_pins && running; ++i) {
            int duty = rand() % 101;
            if (gpioPWM(pins[i], duty) != 0) {
                fprintf(stderr, "Error: gpioPWM failed on pin %d\n", pins[i]);
                gpioTerminate();
                return EXIT_FAILURE;
            }
            printf("Pin %d: %d%%\n", pins[i], duty);
        }
        fflush(stdout);
        time_sleep(0.1);
    }

    for (size_t i = 0; i < num_pins; ++i) {
        gpioPWM(pins[i], 0);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

