#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define DHT22_PIN 4
#define NUM_READINGS 3

static volatile sig_atomic_t running = 1;

static void sighandler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, DHT22_PIN);
    if (!line) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_input(line, "dht22") < 0) {
        perror("gpiod_line_request_input");
        goto cleanup;
    }

    printf("DHT22 reader started on GPIO %d. Reading %d times.\n", DHT22_PIN, NUM_READINGS);

    for (int i = 0; i < NUM_READINGS && running; i++) {
        int data[5] = {0};
        int j;

        /* Send start signal: pull low for >=1ms, then high */
        if (gpiod_line_set_config(line, GPIOD_LINE_REQUEST_DIRECTION_OUTPUT, 0, 0) < 0) {
            perror("gpiod_line_set_config (output)");
            goto cleanup;
        }
        usleep(2000);
        if (gpiod_line_set_value(line, 0) < 0) {
            perror("gpiod_line_set_value (low)");
            goto cleanup;
        }
        usleep(3000);
        if (gpiod_line_set_value(line, 1) < 0) {
            perror("gpiod_line_set_value (high)");
            goto cleanup;
        }
        usleep(40);

        /* Switch to input to read response */
        if (gpiod_line_set_config(line, GPIOD_LINE_REQUEST_DIRECTION_INPUT, 0, 0) < 0) {
            perror("gpiod_line_set_config (input)");
            goto cleanup;
        }

        /* Wait for DHT22 to pull low (response) */
        int timeout = 0;
        while (gpiod_line_get_value(line) == 1) {
            if (++timeout > 100) {
                fprintf(stderr, "Timeout waiting for DHT22 response (low)\n");
                goto cleanup;
            }
            usleep(1);
        }

        /* Response: ~80us low, ~80us high */
        timeout = 0;
        while (gpiod_line_get_value(line) == 0) {
            if (++timeout > 100) {
                fprintf(stderr, "Timeout waiting for DHT22 response (high)\n");
                goto cleanup;
            }
            usleep(1);
        }
        timeout = 0;
        while (gpiod_line_get_value(line) == 1) {
            if (++timeout > 100) {
                fprintf(stderr, "Timeout waiting for DHT22 response (low)\n");
                goto cleanup;
            }
            usleep(1);
        }

        /* Read 40 bits */
        for (j = 0; j < 40; j++) {
            /* Low phase (~50us) */
            timeout = 0;
            while (gpiod_line_get_value(line) == 0) {
                if (++timeout > 100) {
                    fprintf(stderr, "Timeout waiting for bit %d low\n", j);
                    goto cleanup;
                }
                usleep(1);
            }
            /* High phase: measure length */
            long high_us = 0;
            while (gpiod_line_get_value(line) == 1) {
                if (++high_us > 100) {
                    fprintf(stderr, "Timeout waiting for bit %d high\n", j);
                    goto cleanup;
                }
                usleep(1);
            }
            /* Convert high time to bit value: ~26-28us = '0', ~70us = '1' */
            if (high_us > 40) {
                data[j / 8] |= (1 << (7 - (j % 8)));
            }
        }

        /* Verify checksum */
        if ((data[0] + data[1] + data[2] + data[3]) != data[4]) {
            fprintf(stderr, "Checksum error: %d + %d + %d + %d != %d\n",
                    data[0], data[1], data[2], data[3], data[4]);
            goto cleanup;
        }

        float temperature = (float)((data[0] << 8) | data[1]) / 10.0f;
        float humidity = (float)((data[2] << 8) | data[3]) / 10.0f;

        printf("Reading %d: Temperature = %.1f C, Humidity = %.1f %%\n", i + 1, temperature, humidity);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

