        fprintf(stderr, "Failed to install signal handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP, strerror(errno));
        return EXIT_FAILURE;
    }

    lines[0] = gpiod_chip_get_line(chip, GPIO_2);
    lines[1] = gpiod_chip_get_line(chip, GPIO_3);
    lines[2] = gpiod_chip_get_line(chip, GPIO_17);
    if (!lines[0] || !lines[1] || !lines[2]) {
        fprintf(stderr, "Failed to get GPIO lines: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(lines[0], "gpio-test", 0) < 0 ||
        gpiod_line_request_output(lines[1], "gpio-test", 0) < 0 ||
        gpiod_line_request_output(lines[2], "gpio-test", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO lines as output: %s\n", strerror(errno));
        goto cleanup;
    }

    vals[0] = 1;
    vals[1] = 0;
    vals[2] = 1;

    for (int i = 0; i < 3 && keep_running; i++) {
        if (gpiod_line_set_value(lines[i], vals[i]) < 0) {
            fprintf(stderr, "Failed to set GPIO %d value: %s\n", i + 2, strerror(errno));
            goto cleanup;
        }
        printf("GPIO %d set to %d\n", i + 2, vals[i]);
    }

    rc = EXIT_SUCCESS;

cleanup:
    for (int i = 0; i < 3; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return rc;
}

