#include <pigpio.h>

#define PWM_PIN_1 4
#define PWM_PIN_2 17
#define PWM_PIN_3 18
#define PWM_PIN_4 27

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int pwm_values[] = {128, 192, 64, 255};
    int num_values = sizeof(pwm_values) / sizeof(pwm_values[0]);

    for (int cycle = 0; cycle < 5 && !terminate; ++cycle) {
        for (int i = 0; i < num_values && !terminate; ++i) {
            gpioPWM(PWM_PIN_1, pwm_values[i]);
            gpioPWM(PWM_PIN_2, pwm_values[(i + 1) % num_values]);
            gpioPWM(PWM_PIN_3, pwm_values[(i + 2) % num_values]);
            gpioPWM(PWM_PIN_4, pwm_values[(i + 3) % num_values]);
            printf("Cycle %d, Step %d: PWM1=%d PWM2=%d PWM3=%d PWM4=%d\n",
                   cycle + 1, i + 1,
                   pwm_values[i],
                   pwm_values[(i + 1) % num_values],
                   pwm_values[(i + 2) % num_values],
                   pwm_values[(i + 3) % num_values]);
            fflush(stdout);
            sleep(60);
        }
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_17 17
#define GPIO_27 27
#define CHIP_NAME "gpiochip0"
#define POLL_INTERVAL_SEC 5

static volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line17 = NULL;
    struct gpiod_line *line27 = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    line17 = gpiod_chip_get_line(chip, GPIO_17);
    if (!line17) {
        perror("gpiod_chip_get_line(17)");
        goto cleanup;
    }

    line27 = gpiod_chip_get_line(chip, GPIO_27);
    if (!line27) {
        perror("gpiod_chip_get_line(27)");
        goto cleanup;
    }

    /* Request both lines as outputs, initially low */
    if (gpiod_line_request_output(line17, "digital_out", 0) < 0) {
        perror("gpiod_line_request_output(17)");
        goto cleanup;
    }
    if (gpiod_line_request_output(line27, "digital_out", 0) < 0) {
        perror("gpiod_line_request_output(27)");
        goto cleanup;
    }

    printf("Digital output control started. Press Ctrl+C to exit.\n");

    while (keep_running) {
        /* Toggle both lines */
        if (gpiod_line_set_value(line17, 1) < 0) {
            perror("gpiod_line_set_value(17)");
            break;
        }
        if (gpiod_line_set_value(line27, 1) < 0) {
            perror("gpiod_line_set_value(27)");
            break;
        }
        printf("GPIO %d and %d set HIGH\n", GPIO_17, GPIO_27);

        sleep(POLL_INTERVAL_SEC);

        if (!keep_running) break;

        if (gpiod_line_set_value(line17, 0) < 0) {
            perror("gpiod_line_set_value(17)");
            break;
        }
        if (gpiod_line_set_value(line27, 0) < 0) {
            perror("gpiod_line_set_value(27)");
            break;
        }
        printf("GPIO %d and %d set LOW\n", GPIO_17, GPIO_27);

        sleep(POLL_INTERVAL_SEC);
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Ensure lines are left in a safe state before release */
    if (line17) gpiod_line_release(line17);
    if (line27) gpiod_line_release(line27);
    if (chip)   gpiod_chip_close(chip);

