#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define NUM_PINS 6
static const int pins[NUM_PINS] = {17, 18, 22, 23, 24, 25};

static volatile sig_atomic_t running = 1;

static void sighandler(int signo) {
    (void)signo;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_PINS; ++i) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Failed to set GPIO %d as output\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioWrite(pins[i], 0) != 0) {
            fprintf(stderr, "Failed to write 0 to GPIO %d\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    while (running) {
        for (int i = 0; i < NUM_PINS && running; ++i) {
            int duty = (rand() % 101) * 10;
            if (gpioPWM(pins[i], duty) != 0) {
                fprintf(stderr, "Failed to set PWM on GPIO %d\n", pins[i]);
                gpioTerminate();
                return EXIT_FAILURE;
            }
            printf("GPIO %d: PWM duty cycle = %d%%\n", pins[i], duty / 10);
        }
        fflush(stdout);
        time_sleep(0.05);
    }

    for (int i = 0; i < NUM_PINS; ++i) {
        gpioWrite(pins[i], 0);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define GPIO_17 17
#define GPIO_23 23
#define GPIO_24 24

static volatile sig_atomic_t keep_running = 1;

static void handle_signal(int sig)
{
    (void)sig;
    keep_running = 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[3] = {NULL, NULL, NULL};
    int pins[3] = {GPIO_17, GPIO_23, GPIO_24};
    const char *consumer = "gpio-demo";
    int rc = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on Raspberry Pi) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name(\"gpiochip0\")");
        return EXIT_FAILURE;
    }

    /* Acquire each line individually */
    for (int i = 0; i < 3; i++) {
        lines[i] = gpiod_chip_get_line(chip, pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %d: %s\n",
                    pins[i], strerror(errno));
            goto cleanup;
        }
    }

    /* Request each line as output, initial value LOW (0) */
    for (int i = 0; i < 3; i++) {
        if (gpiod_line_request_output(lines[i], consumer, 0) < 0) {
            fprintf(stderr, "Failed to request GPIO %d as output: %s\n",
                    pins[i], strerror(errno));
            goto cleanup;
        }
    }

    printf("Digital output control started on GPIO %d, %d, %d.\n",
           GPIO_17, GPIO_23, GPIO_24);
    printf("Press Ctrl+C to exit.\n");

    while (keep_running) {
        static int values[3] = {0, 0, 0};

        for (int i = 0; i < 3; i++) {
            if (gpiod_line_set_value(lines[i], values[i]) < 0) {
                fprintf(stderr, "Failed to set GPIO %d value: %s\n",
                        pins[i], strerror(errno));
                goto cleanup;
            }
            values[i] = !values[i];
        }

        printf("GPIO %d=%d, GPIO %d=%d, GPIO %d=%d\n",
               GPIO_17, values[0],
               GPIO_23, values[1],
               GPIO_24, values[2]);

        sleep(1);
    }

    rc = EXIT_SUCCESS;

cleanup:
    /* Release lines and close chip on every exit path */
    for (int i = 0; i < 3; i++) {
        if (lines[i])
            gpiod_line_release(lines[i]);
    }
    if (chip)
        gpiod_chip_close(chip);

    if (rc == EXIT_SUCCESS)
        printf("\nExiting cleanly.\n");

    return rc;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <time.h>
#include <gpiod.h>

#define DHT_PIN_1 4
#define DHT_PIN_2 17
#define NUM_READINGS 3
#define READ_INTERVAL_SEC 60

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int wait_for_level(struct gpiod_line *line, int level, int timeout_ms) {
    struct timespec start, now;
    clock_gettime(CLOCK_MONOTONIC, &start);
    while (1) {
        int val = gpiod_line_get_value(line);
        if (val < 0) return -1;
        if (val == level) return 0;
        clock_gettime(CLOCK_MONOTONIC, &now);
        long elapsed_ms = (now.tv_sec - start.tv_sec) * 1000 +
                          (now.tv_nsec - start.tv_nsec) / 1000000;
        if (elapsed_ms > timeout_ms) return -1;
    }
}

static int read_dht22(struct gpiod_line *line, float *temp, float *hum) {
    unsigned char data[5] = {0};
    int i;

    if (gpiod_line_request_output(line, "dht22", 0) < 0) return -1;
    usleep(1000);

    if (gpiod_line_request_input(line, "dht22") < 0) return -1;

    if (wait_for_level(line, 0, 100) < 0) return -1;
    if (wait_for_level(line, 1, 100) < 0) return -1;
    if (wait_for_level(line, 0, 100) < 0) return -1;

    for (i = 0; i < 40; i++) {
        if (wait_for_level(line, 1, 100) < 0) return -1;
        long t0 = 0, t1 = 0;
        clock_gettime(CLOCK_MONOTONIC, &t0);
        while (gpiod_line_get_value(line) == 1) {
            clock_gettime(CLOCK_MONOTONIC, &t1);
            long elapsed_us = (t1.tv_sec - t0.tv_sec) * 1000000 +
                              (t1.tv_nsec - t0.tv_nsec) / 1000;
            if (elapsed_us > 100) return -1;
        }
        clock_gettime(CLOCK_MONOTONIC, &t0);
        while (gpiod_line_get_value(line) == 0) {
            clock_gettime(CLOCK_MONOTONIC, &t1);
            long elapsed_us = (t1.tv_sec - t0.tv_sec) * 1000000 +
                              (t1.tv_nsec - t0.tv_nsec) / 1000;
            if (elapsed_us > 100) return -1;
        }
        clock_gettime(CLOCK_MONOTONIC, &t0);
        while (gpiod_line_get_value(line) == 1) {
            clock_gettime(CLOCK_MONOTONIC, &t1);
            long elapsed_us = (t1.tv_sec - t0.tv_sec) * 1000000 +
                              (t1.tv_nsec - t0.tv_nsec) / 1000;
            if (elapsed_us > 100) return -1;
        }

        if ((t1.tv_sec - t0.tv_sec) * 1000000 + (t1.tv_nsec - t0.tv_nsec) / 1000 > 50) {
            data[i / 8] |= (1 << (7 - (i % 8)));
        }
    }

    if ((data[0] + data[1] + data[2] + data[3]) != data[4]) {
        fprintf(stderr, "DHT22 checksum error\n");
        return -1;
    }

    int raw_hum = (data[0] << 8) | data[1];
    int raw_temp = (data[2] << 8) | data[3];

    *hum = raw_hum / 10.0f;
    if (raw_temp & 0x8000) {
        *temp = -(raw_temp & 0x7FFF) / 10.0f;
    } else {
        *temp = raw_temp / 10.0f;
    }

    if (*hum < 0.0f || *hum > 100.0f || *temp < -40.0f || *temp > 80.0f) {
        fprintf(stderr, "DHT22 out-of-range: H=%.1f T=%.1f\n", *hum, *temp);
        return -1;
    }

    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[2] = {NULL, NULL};
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    lines[0] = gpiod_chip_get_line(chip, DHT_PIN_1);
    lines[1] = gpiod_chip_get_line(chip, DHT_PIN_2);
    if (!lines[0] || !lines[1]) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    printf("Starting DHT22 readings on GPIO %d and %d for %d cycles.\n",
           DHT_PIN_1, DHT_PIN_2, NUM_READINGS);

    for (int cycle = 0; cycle < NUM_READINGS && running; cycle++) {
        float temp = 0.0f, hum = 0.0f;
        int ok = 0;

        if (read_dht22(lines[0], &temp, &hum) == 0) {
            printf("Cycle %d: GPIO %d - Temp: %.1fC, Hum: %.1f%%\n",
                   cycle + 1, DHT_PIN_1, temp, hum);
            ok = 1;
        } else {
            fprintf(stderr, "Cycle %d: GPIO %d - Read failed\n", cycle + 1, DHT_PIN_1);
        }

        if (read_dht22(lines[1], &temp, &hum) == 0) {
            printf("Cycle %d: GPIO %d - Temp: %.1fC, Hum: %.1f%%\n",
                   cycle + 1, DHT_PIN_2, temp, hum);
            ok = 1;
        } else {
            fprintf(stderr, "Cycle %d: GPIO %d - Read failed\n", cycle + 1, DHT_PIN_2);
        }

        if (!ok) {
            fprintf(stderr, "Cycle %d: All reads failed. Exiting.\n", cycle + 1);
            goto cleanup;
        }

        if (cycle < NUM_READINGS - 1 && running) {
            sleep(READ_INTERVAL_SEC);
        }
    }

    if (running) {
        ret = EXIT_SUCCESS;
    }

cleanup:
    for (int i = 0; i < 2; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

