#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define TRIGGER_PIN 4
#define ECHO_PIN    17
#define TRIG_HIGH_US 10
#define LOOP_DELAY_MS 100

static volatile sig_atomic_t running = 1;

static void sighandler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig = NULL;
    struct gpiod_line *echo = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to install signal handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    trig = gpiod_chip_get_line(chip, TRIGGER_PIN);
    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!trig || !echo) {
        fprintf(stderr, "Failed to get GPIO lines: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(trig, "hc-sr04-trig", 0) < 0) {
        fprintf(stderr, "Failed to request trigger line as output: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input(echo, "hc-sr04-echo") < 0) {
        fprintf(stderr, "Failed to request echo line as input: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("HC-SR04 ranging started. Press Ctrl+C to exit.\n");

    while (running) {
        if (gpiod_line_set_value(trig, 0) < 0) {
            fprintf(stderr, "Failed to set trigger low: %s\n", strerror(errno));
            break;
        }
        usleep(5);

        if (gpiod_line_set_value(trig, 1) < 0) {
            fprintf(stderr, "Failed to set trigger high: %s\n", strerror(errno));
            break;
        }
        usleep(TRIG_HIGH_US);

        if (gpiod_line_set_value(trig, 0) < 0) {
            fprintf(stderr, "Failed to reset trigger: %s\n", strerror(errno));
            break;
        }

        int timeout = 0;
        while (gpiod_line_get_value(echo) == 0 && timeout < 1000) {
            usleep(1);
            timeout++;
        }
        if (timeout >= 1000) {
            fprintf(stderr, "Timeout waiting for echo start\n");
            break;
        }

        unsigned long start_tick = 0;
        timeout = 0;
        while (gpiod_line_get_value(echo) == 1 && timeout < 1000) {
            usleep(1);
            timeout++;
        }
        if (timeout >= 1000) {
            fprintf(stderr, "Timeout waiting for echo end\n");
            break;
        }

        unsigned long end_tick = 0;
        timeout = 0;
        while (gpiod_line_get_value(echo) == 0 && timeout < 1000) {
            usleep(1);
            timeout++;
        }
        if (timeout >= 1000) {
            fprintf(stderr, "Timeout waiting for echo release\n");
            break;
        }

        unsigned long elapsed_us = end_tick - start_tick;
        float distance_cm = (elapsed_us / 1000000.0f) * 34300.0f / 2.0f;

        printf("Distance: %.2f cm\n", distance_cm);
        ret = EXIT_SUCCESS;
        break;
    }

cleanup:
    if (trig) gpiod_line_release(trig);
    if (echo) gpiod_line_release(echo);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

