#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>

#define BMP280_ADDR 0x03
#define I2C_BUS "/dev/i2c-1"

static volatile sig_atomic_t running = 1;

void handle_sig(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = handle_sig;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("open i2c bus");
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, BMP280_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(fd);
        return EXIT_FAILURE;
    }

    // BMP280 register addresses
    uint8_t reg = 0x00;
    uint8_t data[3];
    int ret;

    for (int i = 0; i < 3 && running; i++) {
        // Read temperature (2 bytes)
        reg = 0xFA;
        if (write(fd, &reg, 1) != 1) { perror("write reg"); break; }
        if (read(fd, data, 2) != 2) { perror("read temp"); break; }
        uint16_t raw_temp = ((uint16_t)data[0] << 4) | (data[1] >> 4);
        printf("Temperature: %u\n", raw_temp);

        // Read pressure (3 bytes)
        reg = 0xF7;
        if (write(fd, &reg, 1) != 1) { perror("write reg"); break; }
        if (read(fd, data, 3) != 3) { perror("read press"); break; }
        uint32_t raw_press = ((uint32_t)data[0] << 12) | ((uint32_t)data[1] << 4) | (data[2] >> 4);
        printf("Pressure: %u\n", raw_press);

        usleep(100000); // 100ms delay between readings
    }

    close(fd);
    return EXIT_SUCCESS;
}

