#define BME280_I2C_ADDR 0x76
#define I2C_BUS "/dev/i2c-1"

static volatile sig_atomic_t running = 1;

void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, val, 1) != 1) return -1;
    return 0;
}

int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, len) != len) return -1;
    return 0;
}

int bme280_init(int fd) {
    uint8_t id;
    if (i2c_read_reg8(fd, 0xD0, &id) < 0) return -1;
    if (id != 0x60) {
        fprintf(stderr, "BME280 not found (ID=0x%02X)\n", id);
        return -1;
    }
    if (i2c_write_reg8(fd, 0xF4, 0x25) < 0) return -1; // Oversampling x1, x1, x1
    if (i2c_write_reg8(fd, 0xF5, 0xA0) < 0) return -1; // Standby 1000ms, filter off
    if (i2c_write_reg8(fd, 0xF6, 0x00) < 0) return -1; // TStandby 0.5ms
    if (i2c_write_reg8(fd, 0xF7, 0x00) < 0) return -1; // Config
    if (i2c_write_reg8(fd, 0xF5, 0xA0) < 0) return -1; // CtrlHum off
    return 0;
}

int bme280_read(int fd, float *temp, float *hum) {
    uint8_t d[8];
    if (i2c_read_burst(fd, 0xF7, d, 8) < 0) return -1;
    int32_t raw_p = (d[0] << 12) | (d[1] << 4) | (d[2] >> 4);
    int32_t raw_t = (d[3] << 12) | (d[4] << 4) | (d[5] >> 4);
    int32_t raw_h = (d[6] << 8) | d[7];
    *temp = (float)raw_t / 100.0f;
    *hum = (float)raw_h / 1024.0f;
    return 0;
}

int main(void) {
    struct sigaction sa = {0};
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("open i2c");
        return 1;
    }

    if (ioctl(fd, I2C_SLAVE, BME280_I2C_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(fd);
        return 1;
    }

    if (bme280_init(fd) < 0) {
        fprintf(stderr, "BME280 init failed\n");
        close(fd);
        return 1;
    }

    for (int i = 0; i < 3 && running; i++) {
        float t, h;
        if (bme280_read(fd, &t, &h) == 0) {
            printf("T=%.2f C  H=%.2f %%\n", t, h);
        } else {
            fprintf(stderr, "Read failed\n");
        }
        sleep(5);
    }

    close(fd);
    return 0;
}

