}

int i2c_read_reg16(int fd, uint8_t reg, uint16_t *value) {
    if (write(fd, &reg, 1) != 1) return -1;
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) return -1;
    *value = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

int veml7700_init(int fd) {
    // Set integration time to 1 second (IT=1), no shutdown mode
    if (i2c_write_reg8(fd, VEML7700_REG_CONFIG, 0x0000) < 0) return -1;
    usleep(10000);
    return 0;
}

int veml7700_read(int fd, uint16_t *out) {
    return i2c_read_reg16(fd, VEML7700_REG_DATA, out);
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Failed to open /dev/i2c-1");
