#include <errno.h>
#include <signal.h>
#include <termios.h>

#define SERIAL_PORT "/dev/ttyS0"
#define BAUD_RATE   B9600

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int configure_serial(const char *port, speed_t baud)
{
    int fd = open(port, O_RDWR | O_NOCTTY | O_NONBLOCK);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", port, strerror(errno));
        return -1;
    }

    /* Clear O_NONBLOCK so reads block normally */
    if (fcntl(fd, F_SETFL, 0) < 0) {
        fprintf(stderr, "fcntl(F_SETFL): %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        fprintf(stderr, "tcgetattr: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    cfsetispeed(&tty, baud);
    cfsetospeed(&tty, baud);

    tty.c_cflag &= ~(PARENB | CSTOPB | CSIZE | CRTSCTS);
    tty.c_cflag |= (CLOCAL | CREAD | CS8);

    tty.c_iflag &= ~(IXON | IXOFF | IXANY | IGNBRK | BRKINT | PARMRK |
                     ISTRIP | INLCR | IGNCR | ICRNL);
    tty.c_lflag &= ~(ICANON | ECHO | ECHOE | ISIG);
    tty.c_oflag &= ~OPOST;

    tty.c_cc[VMIN]  = 0;
    tty.c_cc[VTIME] = 5; /* 0.5 s inter-byte timeout */

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        fprintf(stderr, "tcsetattr: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    tcflush(fd, TCIOFLUSH);
    return fd;
}

int main(void)
{
    if (install_signal_handlers() != 0) {
        return EXIT_FAILURE;
    }

    int fd = configure_serial(SERIAL_PORT, BAUD_RATE);
    if (fd < 0) {
        return EXIT_FAILURE;
    }

    printf("Serial port %s configured at 9600 baud. Press Ctrl+C to stop.\n",
           SERIAL_PORT);

    while (g_running) {
        unsigned char buf[256];
        ssize_t n = read(fd, buf, sizeof(buf));

        if (n > 0) {
            size_t printed = 0;
            for (ssize_t i = 0; i < n && printed < (size_t)n; i++) {
                putchar(buf[i]);
                printed++;
            }
            fflush(stdout);
        } else if (n == 0) {
            /* No data available — loop and check g_running */
        } else {
            if (errno == EAGAIN || errno == EWOULDBLOCK) {
                /* VTIME elapsed with no data — normal */
            } else {
                fprintf(stderr, "read error: %s\n", strerror(errno));
                break;
            }
        }

        usleep(100000); /* 0.1 s */
    }

    if (close(fd) != 0) {
        fprintf(stderr, "close: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

