#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_4   4
#define GPIO_17  17
#define GPIO_27  27

static volatile sig_atomic_t keep_running = 1;

static void handle_signal(int sig)
{
    (void)sig;
    keep_running = 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[3] = {NULL, NULL, NULL};
    int values[3] = {0, 0, 0};
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on Raspberry Pi) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get the three lines */
    lines[0] = gpiod_chip_get_line(chip, GPIO_4);
    lines[1] = gpiod_chip_get_line(chip, GPIO_17);
    lines[2] = gpiod_chip_get_line(chip, GPIO_27);
    if (!lines[0] || !lines[1] || !lines[2]) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    /* Request each line as output, initially low */
    for (int i = 0; i < 3; i++) {
        if (gpiod_line_request_output(lines[i], "digital-out", 0) < 0) {
            perror("gpiod_line_request_output");
            goto cleanup;
        }
    }

    /* Main loop: toggle all three outputs every 0.5 s */
    while (keep_running) {
        for (int i = 0; i < 3; i++) {
            values[i] = !values[i];
            if (gpiod_line_set_value(lines[i], values[i]) < 0) {
                perror("gpiod_line_set_value");
                goto cleanup;
            }
        }
        printf("GPIO %d=%d, GPIO %d=%d, GPIO %d=%d\n",
               GPIO_4, values[0],
               GPIO_17, values[1],
               GPIO_27, values[2]);
        fflush(stdout);
        usleep(500000); /* 0.5 s */
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines and close chip on every exit path */
    for (int i = 0; i < 3; i++) {
        if (lines[i])
            gpiod_line_release(lines[i]);
    }
    if (chip)
        gpiod_chip_close(chip);

    return ret;
}

#include <pigpio.h>
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>

#define PWM_PIN 18
#define PWM_RANGE 255
#define PWM_FREQ 1000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PWM_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(PWM_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range on GPIO %d\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(PWM_PIN, PWM_FREQ) != 0) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO %d\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        int duty = (rand() % (PWM_RANGE + 1));
        if (gpioPWM(PWM_PIN, duty) != 0) {
            fprintf(stderr, "Failed to write PWM duty cycle %d on GPIO %d\n", duty, PWM_PIN);
            break;
        }
        printf("GPIO %d: PWM duty cycle = %d (%.1f%%)\n",
               PWM_PIN, duty, (double)duty / PWM_RANGE * 100.0);
        fflush(stdout);
        time_sleep(0.1);
    }

    gpioPWM(PWM_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_4 4
#define GPIO_17 17
#define NUM_CYCLES 5

static volatile sig_atomic_t keep_running = 1;

void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line4 = NULL;
    struct gpiod_line *line17 = NULL;
    int ret = EXIT_FAILURE;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open gpiochip0");
        return EXIT_FAILURE;
    }

    line4 = gpiod_chip_get_line(chip, GPIO_4);
    if (!line4) {
        perror("Failed to get GPIO 4");
        goto cleanup;
    }

    line17 = gpiod_chip_get_line(chip, GPIO_17);
    if (!line17) {
        perror("Failed to get GPIO 17");
        goto cleanup;
    }

    if (gpiod_line_request_output(line4, "digital_output", 0) < 0) {
        perror("Failed to request GPIO 4 as output");
        goto cleanup;
    }

    if (gpiod_line_request_output(line17, "digital_output", 0) < 0) {
        perror("Failed to request GPIO 17 as output");
        goto cleanup;
    }

    printf("Starting %d cycles...\n", NUM_CYCLES);

    for (int i = 0; i < NUM_CYCLES && keep_running; i++) {
        printf("Cycle %d: Setting GPIO 4 HIGH\n", i + 1);
        if (gpiod_line_set_value(line4, 1) < 0) {
            perror("Failed to set GPIO 4 HIGH");
            goto cleanup;
        }
        sleep(1);

        printf("Cycle %d: Setting GPIO 4 LOW\n", i + 1);
        if (gpiod_line_set_value(line4, 0) < 0) {
            perror("Failed to set GPIO 4 LOW");
            goto cleanup;
        }
        sleep(1);

        printf("Cycle %d: Setting GPIO 17 HIGH\n", i + 1);
        if (gpiod_line_set_value(line17, 1) < 0) {
            perror("Failed to set GPIO 17 HIGH");
            goto cleanup;
        }
        sleep(1);

        printf("Cycle %d: Setting GPIO 17 LOW\n", i + 1);
        if (gpiod_line_set_value(line17, 0) < 0) {
            perror("Failed to set GPIO 17 LOW");
            goto cleanup;
        }
        sleep(1);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line4) gpiod_line_release(line4);
    if (line17) gpiod_line_release(line17);
    if (chip) gpiod_chip_close(chip);

    if (ret == EXIT_SUCCESS) {
        printf("Exiting cleanly.\n");
    } else {
        fprintf(stderr, "Exiting with error.\n");
    }

    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip0"
#define GPIO_17_OFFSET 17
#define GPIO_21_OFFSET 21
#define POLL_INTERVAL_US 100000

static volatile sig_atomic_t keep_running = 1;

static void signal_handler(int signum)
{
    (void)signum;
    keep_running = 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line17 = NULL;
    struct gpiod_line *line21 = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Get the lines */
    line17 = gpiod_chip_get_line(chip, GPIO_17_OFFSET);
    if (!line17) {
        fprintf(stderr, "Failed to get line %d: %s\n", GPIO_17_OFFSET, strerror(errno));
        goto cleanup;
    }

    line21 = gpiod_chip_get_line(chip, GPIO_21_OFFSET);
    if (!line21) {
        fprintf(stderr, "Failed to get line %d: %s\n", GPIO_21_OFFSET, strerror(errno));
        goto cleanup;
    }

    /* Request both lines as outputs, initially low */
    if (gpiod_line_request_output(line17, "digital-out-17", 0) < 0) {
        fprintf(stderr, "Failed to request line %d as output: %s\n", GPIO_17_OFFSET, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(line21, "digital-out-21", 0) < 0) {
        fprintf(stderr, "Failed to request line %d as output: %s\n", GPIO_21_OFFSET, strerror(errno));
        goto cleanup;
    }

    printf("Digital output control started. Press Ctrl+C to exit.\n");

    while (keep_running) {
        /* Toggle both lines */
        if (gpiod_line_set_value(line17, 1) < 0) {
            fprintf(stderr, "Failed to set line %d high: %s\n", GPIO_17_OFFSET, strerror(errno));
            goto cleanup;
        }
        if (gpiod_line_set_value(line21, 1) < 0) {
            fprintf(stderr, "Failed to set line %d high: %s\n", GPIO_21_OFFSET, strerror(errno));
            goto cleanup;
        }
        printf("GPIO %d and %d set HIGH\n", GPIO_17_OFFSET, GPIO_21_OFFSET);

        usleep(POLL_INTERVAL_US);

        if (gpiod_line_set_value(line17, 0) < 0) {
            fprintf(stderr, "Failed to set line %d low: %s\n", GPIO_17_OFFSET, strerror(errno));
            goto cleanup;
        }
        if (gpiod_line_set_value(line21, 0) < 0) {
            fprintf(stderr, "Failed to set line %d low: %s\n", GPIO_21_OFFSET, strerror(errno));
            goto cleanup;
        }
        printf("GPIO %d and %d set LOW\n", GPIO_17_OFFSET, GPIO_21_OFFSET);

        usleep(POLL_INTERVAL_US);
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Ensure lines are released even on error path */
    if (line17) {
        gpiod_line_release(line17);
    }
    if (line21) {
        gpiod_line_release(line21);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    if (ret == EXIT_SUCCESS) {
        printf("\nExiting cleanly.\n");
    }
    return ret;
}

