    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    line17 = gpiod_chip_get_line(chip, GPIO_17);
    if (!line17) {
        fprintf(stderr, "Failed to get line %d: %s\n", GPIO_17, strerror(errno));
        goto cleanup;
    }

    line27 = gpiod_chip_get_line(chip, GPIO_27);
    if (!line27) {
        fprintf(stderr, "Failed to get line %d: %s\n", GPIO_27, strerror(errno));
        goto cleanup;
    }

    /* Request both lines as outputs, initially low */
    if (gpiod_line_request_output(line17, "digital-out", 0) < 0) {
        fprintf(stderr, "Failed to request line %d as output: %s\n", GPIO_17, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(line27, "digital-out", 0) < 0) {
        fprintf(stderr, "Failed to request line %d as output: %s\n", GPIO_27, strerror(errno));
        goto cleanup;
    }

    while (keep_running) {
        printf("GPIO %d -> 1, GPIO %d -> 0\n", GPIO_17, GPIO_27);
        fflush(stdout);

        if (gpiod_line_set_value(line17, 1) < 0) {
            fprintf(stderr, "Failed to set GPIO %d high: %s\n", GPIO_17, strerror(errno));
            goto cleanup;
        }
        if (gpiod_line_set_value(line27, 0) < 0) {
            fprintf(stderr, "Failed to set GPIO %d low: %s\n", GPIO_27, strerror(errno));
            goto cleanup;
        }

        usleep(POLL_INTERVAL_US);
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Ensure lines are left in a safe state before release */
    if (line17) {
        gpiod_line_set_value(line17, 0);
        gpiod_line_release(line17);
    }
    if (line27) {
        gpiod_line_set_value(line27, 0);
        gpiod_line_release(line27);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    18
#define SOUND_SPEED 34300.0
#define MAX_DISTANCE 400.0

static volatile sig_atomic_t running = 1;

void handle_signal(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trigger = NULL;
    struct gpiod_line *echo = NULL;
    int ret = EXIT_FAILURE;

    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Failed to open gpiochip0");
        return EXIT_FAILURE;
    }

    trigger = gpiod_chip_get_line(chip, TRIGGER_PIN);
    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    if (!trigger || !echo) {
        perror("Failed to get GPIO lines");
        goto cleanup;
    }

    if (gpiod_line_request_output(trigger, "hc-sr04-trigger", 0) < 0) {
        perror("Failed to request trigger line as output");
        goto cleanup;
    }

    if (gpiod_line_request_input(echo, "hc-sr04-echo") < 0) {
        perror("Failed to request echo line as input");
        goto cleanup;
    }

    printf("HC-SR04 Distance Measurement\n");

    while (running) {
        // Send 10us trigger pulse
        gpiod_line_set_value(trigger, 1);
        usleep(10);
        gpiod_line_set_value(trigger, 0);

        // Wait for echo start (rising edge)
        int timeout = 0;
        while (gpiod_line_get_value(echo) == 0 && timeout < 100000) {
            usleep(1);
            timeout++;
        }
        if (timeout >= 100000) {
            fprintf(stderr, "Timeout waiting for echo start\n");
            continue;
        }

        long start_tick = 0;
        timeout = 0;
        while (gpiod_line_get_value(echo) == 1 && timeout < 100000) {
            start_tick = gpiod_line_get_value(echo);
            usleep(1);
            timeout++;
        }
        if (timeout >= 100000) {
            fprintf(stderr, "Timeout waiting for echo end\n");
            continue;
        }

        long end_tick = start_tick;
        timeout = 0;
        while (gpiod_line_get_value(echo) == 1 && timeout < 100000) {
            end_tick = gpiod_line_get_value(echo);
            usleep(1);
            timeout++;
        }
        if (timeout >= 100000) {
            fprintf(stderr, "Timeout waiting for echo end\n");
            continue;
        }

        // Calculate time difference in microseconds
        long diff = end_tick - start_tick;
        float distance = (diff / 1000000.0) * SOUND_SPEED / 2.0;

        if (distance > MAX_DISTANCE) {
            printf("Distance: %.2f cm (out of range)\n", distance);
        } else {
            printf("Distance: %.2f cm\n", distance);
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (trigger) gpiod_line_release(trigger);
    if (echo) gpiod_line_release(echo);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_PIN_1 18
#define PWM_PIN_2 21
#define PWM_PIN_3 22

volatile sig_atomic_t terminate = 0;

void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register signal handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int pins[] = {PWM_PIN_1, PWM_PIN_2, PWM_PIN_3};
    const int num_pins = sizeof(pins) / sizeof(pins[0]);

    for (int i = 0; i < num_pins && !terminate; ++i) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Failed to set GPIO %d as output\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioPWM(pins[i], 128) != 0) {
            fprintf(stderr, "Failed to set PWM on GPIO %d\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        printf("GPIO %d set to PWM duty cycle 128\n", pins[i]);
    }

    if (terminate) {
        fprintf(stderr, "\nInterrupted by signal, cleaning up...\n");
    } else {
        printf("\nAll GPIOs configured successfully.\n");
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

