#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define TRIGGER_PIN 4
#define ECHO_PIN    17
#define BUZZER_PIN  18

static volatile sig_atomic_t running = 1;

static void sighandler(int sig)
{
    (void)sig;
    running = 0;
}

static int wait_level(struct gpiod_line *line, int val, int timeout_ms)
{
    struct timespec ts = { .tv_sec = 0, .tv_nsec = 10000000 };
    int prev = -1;

    while (running) {
        int v = gpiod_line_get_value(line);
        if (v < 0) return -1;
        if (v != prev) {
            if (v == val) return 0;
            prev = v;
        }
        nanosleep(&ts, NULL);
    }
    return -1;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig = NULL, *echo = NULL, *buz = NULL;
    int rc = EXIT_FAILURE;

    struct sigaction sa = { .sa_handler = sighandler };
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    trig = gpiod_chip_get_line(chip, TRIGGER_PIN);
    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    buz  = gpiod_chip_get_line(chip, BUZZER_PIN);
    if (!trig || !echo || !buz) {
        fprintf(stderr, "Failed to get GPIO lines: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(trig, "hc-sr04-trig", 0) < 0 ||
        gpiod_line_request_input(echo, "hc-sr04-echo") < 0 ||
        gpiod_line_request_output(buz, "hc-sr04-buzz", 0) < 0) {
        perror("gpiod_line_request");
        goto cleanup;
    }

    while (running) {
        gpiod_line_set_value(trig, 0);
        usleep(2);
        gpiod_line_set_value(trig, 1);
        usleep(10);
        gpiod_line_set_value(trig, 0);

        if (wait_level(echo, 1, 30000) < 0) {
            fprintf(stderr, "Timeout waiting for echo start\n");
            continue;
        }
        long t1 = 0;
        while (running && t1 < 30000) {
            t1++;
            usleep(1);
        }
        if (!running) break;
        if (t1 >= 30000) {
            fprintf(stderr, "Timeout waiting for echo end\n");
            continue;
        }
        if (wait_level(echo, 0, 30000) < 0) {
            fprintf(stderr, "Timeout waiting for echo end\n");
            continue;
        }

        long elapsed = 0;
        while (running && elapsed < 30000) {
            elapsed++;
            usleep(1);
        }
        if (!running) break;
        if (elapsed >= 30000) {
            fprintf(stderr, "Timeout measuring pulse width\n");
            continue;
        }

        double pulse_us = (double)elapsed;
        double distance = pulse_us / 58.0;
        printf("Distance: %.2f cm\n", distance);

        if (distance > 400.0 || distance < 2.0) {
            fprintf(stderr, "Warning: out-of-range reading (%.2f cm)\n", distance);
        }

        gpiod_line_set_value(buz, 1);
        usleep(500000);
        gpiod_line_set_value(buz, 0);
        usleep(100000);
    }

    rc = EXIT_SUCCESS;

cleanup:
    if (trig) gpiod_line_release(trig);
    if (echo) gpiod_line_release(echo);
    if (buz)  gpiod_line_release(buz);
    if (chip) gpiod_chip_close(chip);
    return rc;
}

