#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define TCS34725_ADDRESS 0x29

/* TCS34725 Registers */
#define TCS34725_ENABLE  0x80
#define TCS34725_ATIME   0x81
#define TCS34725_CONTROL 0x8F
#define TCS34725_ID      0x12
#define TCS34725_CDATA   0x14
#define TCS34725_RDATA   0x16
#define TCS34725_GDATA   0x18
#define TCS34725_BDATA   0x1A

static volatile sig_atomic_t running = 1;

static void sig_handler(int signo) {
    (void)signo;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write failed (reg 0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select) failed: %s\n", strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (block reg select) failed: %s\n", strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C block read failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int tcs34725_init(int fd) {
    uint8_t id;
    if (i2c_read_reg8(fd, TCS34725_ID, &id) < 0) {
        return -1;
    }
    if (id != 0x44 && id != 0x4D) {
        fprintf(stderr, "Unexpected ID 0x%02X (expected 0x44 or 0x4D)\n", id);
        return -1;
    }

    /* Power ON, AEN enabled */
    if (i2c_write_reg8(fd, TCS34725_ENABLE, 0x03) < 0) return -1;
    usleep(3000);

    /* Integration time ~2.4ms (ATIME=0xFF) */
    if (i2c_write_reg8(fd, TCS34725_ATIME, 0xFF) < 0) return -1;

    /* Gain 1x */
    if (i2c_write_reg8(fd, TCS34725_CONTROL, 0x00) < 0) return -1;

    return 0;
}

static int tcs34725_read_data(int fd, uint16_t *r, uint16_t *g, uint16_t *b, uint16_t *c) {
    uint8_t buf[8];
    if (i2c_read_block(fd, TCS34725_CDATA, buf, 8) < 0) return -1;
    *c = (uint16_t)((buf[1] << 8) | buf[0]);
    *r = (uint16_t)((buf[3] << 8) | buf[2]);
    *g = (uint16_t)((buf[5] << 8) | buf[4]);
    *b = (uint16_t)((buf[7] << 8) | buf[6]);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    const char *dev = "/dev/i2c-1";
    int fd = open(dev, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", dev, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, TCS34725_ADDRESS) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n", TCS34725_ADDRESS, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    if (tcs34725_init(fd) < 0) {
        fprintf(stderr, "TCS34725 initialization failed.\n");
        close(fd);
        return EXIT_FAILURE;
    }

    while (running) {
        uint16_t r, g, b, c;
        if (tcs34725_read_data(fd, &r, &g, &b, &c) == 0) {
            printf("R: %u, G: %u, B: %u, C: %u\n", r, g, b, c);
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }
        sleep(0.5);
    }

    if (close(fd) < 0) {
        fprintf(stderr, "Warning: close failed: %s\n", strerror(errno));
    }
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME "gpiochip4"
#define GPIO_18_OFFSET 18
#define GPIO_23_OFFSET 23
#define POLL_INTERVAL_US 10000

static volatile sig_atomic_t keep_running = 1;

static void signal_handler(int signum) {
    (void)signum;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line18 = NULL;
    struct gpiod_line *line23 = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("Failed to install SIGINT handler");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("Failed to install SIGTERM handler");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Error opening %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    line18 = gpiod_chip_get_line(chip, GPIO_18_OFFSET);
    if (!line18) {
        fprintf(stderr, "Error getting GPIO %d: %s\n", GPIO_18_OFFSET, strerror(errno));
        goto cleanup;
    }

    line23 = gpiod_chip_get_line(chip, GPIO_23_OFFSET);
    if (!line23) {
        fprintf(stderr, "Error getting GPIO %d: %s\n", GPIO_23_OFFSET, strerror(errno));
        goto cleanup;
    }

    /* Request both lines as outputs, initially low */
    if (gpiod_line_request_output(line18, "digital_output_18", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO %d as output: %s\n", GPIO_18_OFFSET, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(line23, "digital_output_23", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO %d as output: %s\n", GPIO_23_OFFSET, strerror(errno));
        goto cleanup;
    }

    printf("Digital output control started. Press Ctrl+C to exit.\n");

    while (keep_running) {
        if (gpiod_line_set_value(line18, 1) < 0) {
            fprintf(stderr, "Error setting GPIO %d high: %s\n", GPIO_18_OFFSET, strerror(errno));
            break;
        }
        if (gpiod_line_set_value(line23, 1) < 0) {
            fprintf(stderr, "Error setting GPIO %d high: %s\n", GPIO_23_OFFSET, strerror(errno));
            break;
        }
        printf("GPIO %d and GPIO %d set HIGH\n", GPIO_18_OFFSET, GPIO_23_OFFSET);

        usleep(POLL_INTERVAL_US);

        if (gpiod_line_set_value(line18, 0) < 0) {
            fprintf(stderr, "Error setting GPIO %d low: %s\n", GPIO_18_OFFSET, strerror(errno));
            break;
        }
        if (gpiod_line_set_value(line23, 0) < 0) {
            fprintf(stderr, "Error setting GPIO %d low: %s\n", GPIO_23_OFFSET, strerror(errno));
            break;
        }
        printf("GPIO %d and GPIO %d set LOW\n", GPIO_18_OFFSET, GPIO_23_OFFSET);

        usleep(POLL_INTERVAL_US);
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Ensure lines are left in a safe state before release */
    if (line18) {
        gpiod_line_set_value(line18, 0);
        gpiod_line_release(line18);
    }
    if (line23) {
        gpiod_line_set_value(line23, 0);
        gpiod_line_release(line23);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    if (ret == EXIT_SUCCESS) {
        printf("\nExiting cleanly.\n");
    }
    return ret;
}

