#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define TRIGGER_PIN 18
#define ECHO_PIN    23
#define BUZZER_PIN  24

static volatile sig_atomic_t running = 1;

static void sighandler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *trig = NULL, *echo = NULL, *buz = NULL;
    int rc = EXIT_FAILURE;

    struct sigaction sa = {0};
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    trig = gpiod_chip_get_line(chip, TRIGGER_PIN);
    echo = gpiod_chip_get_line(chip, ECHO_PIN);
    buz = gpiod_chip_get_line(chip, BUZZER_PIN);
    if (!trig || !echo || !buz) {
        fprintf(stderr, "Failed to get GPIO lines: %s\n", strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(trig, "hc-sr04-trig", 0) < 0 ||
        gpiod_line_request_input(echo, "hc-sr04-echo") < 0 ||
        gpiod_line_request_output(buz, "hc-sr04-buzz", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO lines: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Ensure trigger starts low */
    if (gpiod_line_set_value(trig, 0) < 0) {
        fprintf(stderr, "Failed to set trigger low: %s\n", strerror(errno));
        goto cleanup;
    }
    usleep(50000);

    printf("HC-SR04 ranging started...\n");

    while (running) {
        /* Send 10us trigger pulse */
        if (gpiod_line_set_value(trig, 1) < 0) {
            fprintf(stderr, "Trigger high failed: %s\n", strerror(errno));
            break;
        }
        usleep(10);
        if (gpiod_line_set_value(trig, 0) < 0) {
            fprintf(stderr, "Trigger low failed: %s\n", strerror(errno));
            break;
        }

        /* Wait for echo rising edge */
        int timeout = 0;
        while (gpiod_line_get_value(echo) == 0 && running) {
            usleep(100);
            timeout++;
            if (timeout > 1000) {
                fprintf(stderr, "Timeout waiting for echo start\n");
                break;
            }
        }
        if (!running) break;

        unsigned long start_tick = 0;
        while (gpiod_line_get_value(echo) == 1 && running) {
            start_tick = gpiod_line_get_value(echo);
            usleep(100);
            if (start_tick == 0) break;
        }
        if (!running) break;

        unsigned long end_tick = 0;
        unsigned long elapsed = 0;
        while (gpiod_line_get_value(echo) == 1 && running) {
            end_tick = gpiod_line_get_value(echo);
            usleep(100);
            if (end_tick == 0) break;
            elapsed++;
            if (elapsed > 1000) {
                fprintf(stderr, "Timeout waiting for echo end\n");
                break;
            }
        }
        if (!running) break;

        if (end_tick == 0) continue;

        /* Distance in cm = (elapsed_us / 58) */
        float distance = (float)(end_tick - start_tick) / 58.0f;

        printf("Distance: %.2f cm\n", distance);

        if (distance < 5.0f) {
            if (gpiod_line_set_value(buz, 1) < 0) {
                fprintf(stderr, "Buzzer on failed: %s\n", strerror(errno));
                break;
            }
            sleep(1);
            if (gpiod_line_set_value(buz, 0) < 0) {
                fprintf(stderr, "Buzzer off failed: %s\n", strerror(errno));
                break;
            }
        } else {
            if (gpiod_line_set_value(buz, 0) < 0) {
                fprintf(stderr, "Buzzer off failed: %s\n", strerror(errno));
                break;
            }
        }
    }

    rc = EXIT_SUCCESS;

cleanup:
    if (trig) gpiod_line_release(trig);
    if (echo) gpiod_line_release(echo);
    if (buz) gpiod_line_release(buz);
    if (chip) gpiod_chip_close(chip);
    return rc;
}

