#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>

#define PWM_PIN 18
#define DUTY_CYCLE 500000  /* 50% of 1M range */
#define LOOP_DELAY_US 200000  /* 0.2 seconds */

static volatile sig_atomic_t running = 1;

static void signal_handler(int signum) {
    (void)signum;
    running = 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PWM_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", PWM_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(PWM_PIN, 1000) != 0) {
        fprintf(stderr, "Warning: could not set PWM frequency on GPIO %d.\n", PWM_PIN);
    }

    if (gpioSetPWMrange(PWM_PIN, 1000000) != 0) {
        fprintf(stderr, "Warning: could not set PWM range on GPIO %d.\n", PWM_PIN);
    }

    while (running) {
        if (gpioPWM(PWM_PIN, DUTY_CYCLE) != 0) {
            fprintf(stderr, "Error: failed to write PWM duty cycle.\n");
            break;
        }
        printf("PWM duty cycle set to %d\n", DUTY_CYCLE);
        fflush(stdout);

        if (running) {
            gpioDelay(LOOP_DELAY_US);
        }
    }

    /* Ensure PWM is off before releasing pigpio */
    gpioPWM(PWM_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

