    }

    while (keep_running) {
        for (int i = 0; i < 3; i++) {
            if (gpiod_line_set_value(lines[i], vals[i]) < 0) {
                fprintf(stderr, "Failed to set line %d: %s\n", pins[i], strerror(errno));
                goto cleanup;
            }
            printf("GPIO %d -> %d\n", pins[i], vals[i]);
        }
        fflush(stdout);
        usleep(100000);
    }

    rc = EXIT_SUCCESS;

cleanup:
    for (int i = 0; i < 3; i++) {
        if (lines[i])
            gpiod_line_release(lines[i]);
    }
    if (chip)
        gpiod_chip_close(chip);

    return rc;
}

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>

#define MPU6050_ADDR 0x68

static volatile sig_atomic_t running = 1;

void handle_signal(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    int fd = -1;
    uint8_t buf[6];
    int16_t accel_x, accel_y, accel_z;
    int16_t gyro_x, gyro_y, gyro_z;

    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("open /dev/i2c-1");
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(fd);
        return EXIT_FAILURE;
    }

    while (running) {
        // Read accelerometer data (registers 0x3B to 0x40)
        if (write(fd, (uint8_t[]){0x3B}, 1) != 1) {
            perror("write reg 0x3B");
            break;
        }
        if (read(fd, buf, 6) != 6) {
            perror("read accel");
            break;
        }
        accel_x = (buf[0] << 8) | buf[1];
        accel_y = (buf[2] << 8) | buf[3];
        accel_z = (buf[4] << 8) | buf[5];

        // Read gyroscope data (registers 0x43 to 0x48)
        if (write(fd, (uint8_t[]){0x43}, 1) != 1) {
            perror("write reg 0x43");
            break;
        }
        if (read(fd, buf, 6) != 6) {
            perror("read gyro");
            break;
        }
        gyro_x = (buf[0] << 8) | buf[1];
        gyro_y = (buf[2] << 8) | buf[3];
        gyro_z = (buf[4] << 8) | buf[5];

        printf("Accel: X=%d Y=%d Z=%d | Gyro: X=%d Y=%d Z=%d\n",
               accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z);
        fflush(stdout);

        sleep(1);
    }

    if (fd >= 0) {
        close(fd);
    }
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <gpiod.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_LINE 17
#define POLL_INTERVAL_US 600000

static volatile sig_atomic_t keep_running = 1;

static void handle_signal(int sig) {
    (void)sig;
    keep_running = 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    /* Get the line for BCM GPIO 17 */
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    /* Request the line as output, initial value LOW (0) */
    ret = gpiod_line_request_output(line, "digital-output", 0);
    if (ret < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("Digital output on GPIO %d controlled by libgpiod.\n", GPIO_LINE);
    printf("Press Ctrl+C to exit.\n");

    while (keep_running) {
        /* Toggle the output: HIGH (1) then LOW (0) */
        ret = gpiod_line_set_value(line, 1);
        if (ret < 0) {
            perror("gpiod_line_set_value HIGH");
            break;
        }
        printf("GPIO %d set HIGH\n", GPIO_LINE);
        usleep(POLL_INTERVAL_US);

        ret = gpiod_line_set_value(line, 0);
        if (ret < 0) {
            perror("gpiod_line_set_value LOW");
            break;
        }
        printf("GPIO %d set LOW\n", GPIO_LINE);
        usleep(POLL_INTERVAL_US);
    }

    /* Clean up: release the line and close the chip */
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}
